-- Easy Professions (Forever): guide texts in frFR (translated from wow-professions.com/forever)
local _, ns = ...
ns.AddTranslation("frFR", {
  ["This WoW Forever Alchemy leveling guide will show you the fastest and cheapest way to level your Alchemy skill from 1 to 300. You will also find every trainer location and where to train Alchemy past 75, 150 and 225."] = "Ce guide de montée en Alchimie pour WoW Forever te montre la façon la plus rapide et la moins chère de monter ta compétence d'Alchimie de 1 à 300. Tu y trouveras aussi l'emplacement de chaque maître et où apprendre l'Alchimie au-delà de 75, 150 et 225.",
  ["Below you will find the full shopping list, the Alchemy trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Alchemy is best combined with Herbalism, with these two you can save a lot of gold because you don't have to buy the herbs from the Auction House."] = "Tu trouveras ci-dessous la liste de courses complète, les maîtres d'Alchimie par zone de départ et capitale, et les recettes les moins chères pour chaque palier de compétence, d'Apprenti à Artisan. L'Alchimie se marie le mieux avec l'Herboristerie : avec ces deux métiers, tu économises beaucoup d'or car tu n'as pas à acheter les herbes à l'hôtel des ventes.",
  ["This is based on the Forever beta. Leveling takes a long time, so testing the higher levels on live will take a while. If you find something that's off, send me feedback."] = "Ce guide se base sur la bêta de Forever. La montée de niveau prend du temps, donc tester les hauts niveaux sur le serveur live va prendre un moment. Si tu trouves quelque chose d'incorrect, envoie-moi un retour.",
  ["Shopping List"] = "Liste de courses",
  ["These numbers are estimates. Once a recipe turns yellow you won't get a skill point from every craft, so you might need a few more or a few less."] = "Ces chiffres sont des estimations. Une fois qu'une recette devient jaune, chaque fabrication ne te donne plus forcément un point de compétence, il te faudra donc peut-être un peu plus ou un peu moins.",
  ["Alchemy Trainer Locations"] = "Emplacements des maîtres d'Alchimie",
  ["Apprentice Alchemy has no level requirement in Forever, so you can learn it on a fresh character."] = "L'Alchimie (Apprenti) n'a aucun niveau requis dans Forever, tu peux donc l'apprendre sur un personnage tout neuf.",
  ["Every capital city has a trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "Chaque capitale a un maître. Tu peux aussi demander à un garde, il sera alors marqué d'un drapeau rouge sur ta carte.",
  ["Capital Cities"] = "Capitales",
  ["Orgrimmar: {n:0:horde:Whuut}"] = "Orgrimmar : {n:0:horde:Whuut}",
  ["Undercity: {n:0:horde:Doctor Martin Felben}"] = "Fossoyeuse : {n:0:horde:Doctor Martin Felben}",
  ["Thunder Bluff: {n:0:horde:Kray}"] = "Les Pitons-du-Tonnerre : {n:0:horde:Kray}",
  ["Starting Zones"] = "Zones de départ",
  ["Not every zone has a trainer, the table shows the closest one for each race."] = "Toutes les zones n'ont pas de maître, le tableau indique le plus proche pour chaque race.",
  ["Closest trainer"] = "Maître le plus proche",
  ["{n:0:horde:Miao'zan} in Sen'jin Village"] = "{n:0:horde:Miao'zan} au village de Sen'jin",
  ["There is no Alchemy trainer in Mulgore, go to {n:0:horde:Kray} on the middle rise in Thunder Bluff"] = "Il n'y a pas de maître d'Alchimie en Mulgore, va voir {n:0:horde:Kray} sur le pic central des Pitons-du-Tonnerre",
  ["Undead"] = "Mort-vivant",
  ["Tirisfal Glades"] = "Clairières de Tirisfal",
  ["{n:0:horde:Carolai Anise} in the small house at the north-west end of Brill"] = "{n:0:horde:Carolai Anise} dans la petite maison au nord-ouest de Brill",
  ["{n:0::Iaadaria Bitterwind} or {n:0::Valiena Swiftgale} in Valanaar, {n:0::Nyassa Swiftdraught} in Shen'dar Village"] = "{n:0::Iaadaria Bitterwind} ou {n:0::Valiena Swiftgale} à Valanaar, {n:0::Nyassa Swiftdraught} au village de Shen'dar",
  ["Stormwind City: {n:0:alliance:Tel'Athir}"] = "Hurlevent : {n:0:alliance:Tel'Athir}",
  ["Ironforge: {n:0:alliance:Vosur Brakthel}"] = "Forgefer : {n:0:alliance:Vosur Brakthel}",
  ["Darnassus: {n:0:alliance:Milla Fairancora}"] = "Darnassus : {n:0:alliance:Milla Fairancora}",
  ["Human"] = "Humain",
  ["Elwynn Forest"] = "Forêt d'Elwynn",
  ["{n:0:alliance:Alchemist Mallory} in a cottage in the hills between Stormwind and Northshire"] = "{n:0:alliance:Alchemist Mallory} dans une maisonnette sur les collines entre Hurlevent et Comté-du-Nord",
  ["Dwarf, Gnome"] = "Nain, Gnome",
  ["There is no Alchemy trainer in Dun Morogh, go to {n:0:alliance:Vosur Brakthel} in Tinker Town in Ironforge"] = "Il n'y a pas de maître d'Alchimie à Dun Morogh, va voir {n:0:alliance:Vosur Brakthel} à Brikabrok, à Forgefer",
  ["Night Elf"] = "Elfe de la nuit",
  ["{n:0:alliance:Cyndra Kindwhisper} in a small house east of the inn in Dolanaar"] = "{n:0:alliance:Cyndra Kindwhisper} dans une petite maison à l'est de l'auberge de Dolanaar",
  ["You can find every Alchemy trainer for Horde and Alliance on my WoW Forever Alchemy Trainers page."] = "Tu trouveras tous les maîtres d'Alchimie de la Horde et de l'Alliance sur ma page WoW Forever Alchemy Trainers.",
  ["Apprentice Alchemy (1-55)"] = "Alchimie (Apprenti) (1-55)",
  ["9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 9 Silverleaf, 9 Empty Vial"] = "9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 9 Feuillargent, 9 Fiole vide",
  ["The vials are sold by Alchemy Supply and Trade Supply vendors, most trainers have one nearby. In Undercity the closest one is {n:0:horde:Algernon}, in Dolanaar it's {n:0:alliance:Narret Shadowgrove}."] = "Les fioles sont vendues par les marchands de fournitures d'alchimie et de fournitures commerciales, la plupart des maîtres en ont un à proximité. À Fossoyeuse, le plus proche est {n:0:horde:Algernon}, à Dolanaar c'est {n:0:alliance:Narret Shadowgrove}.",
  ["45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 45 Silverleaf, 45 Peacebloom, 45 Empty Vial"] = "45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 45 Feuillargent, 45 Pacifique, 45 Fiole vide",
  ["Journeyman Alchemy (55-150)"] = "Alchimie (Compagnon) (55-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Alchemy. You need {b}Alchemy 50{/b} and {b}level 10{/b}:"] = "Pour dépasser 75, va voir l'un de ces maîtres et apprends Alchimie (Compagnon). Il te faut {b}Alchimie 50{/b} et {b}niveau 10{/b} :",
  ["{b}Horde trainers:{/b}"] = "{b}Maîtres de la Horde :{/b}",
  ["Orgrimmar: {n:0:horde:Yelmak}"] = "Orgrimmar : {n:0:horde:Yelmak}",
  ["Undercity: {n:0:horde:Doctor Marsh}"] = "Fossoyeuse : {n:0:horde:Doctor Marsh}",
  ["Thunder Bluff: {n:0:horde:Bena Winterhoof}"] = "Les Pitons-du-Tonnerre : {n:0:horde:Bena Winterhoof}",
  ["{b}Alliance trainers:{/b}"] = "{b}Maîtres de l'Alliance :{/b}",
  ["Stormwind City: {n:0:alliance:Lilyssia Nightbreeze}"] = "Hurlevent : {n:0:alliance:Lilyssia Nightbreeze}",
  ["Ironforge: {n:0:alliance:Tally Berryfizz}"] = "Forgefer : {n:0:alliance:Tally Berryfizz}",
  ["Darnassus: {n:0:alliance:Sylvanna Forestmoon}"] = "Darnassus : {n:0:alliance:Sylvanna Forestmoon}",
  ["10x {s:2331:inv_potion_70:Minor Mana Potion} - 10 Mageroyal, 10 Peacebloom, 10 Empty Vial"] = "10x {s:2331:inv_potion_70:Minor Mana Potion} - 10 Mage royal, 10 Pacifique, 10 Fiole vide",
  ["28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 56 Earthroot, 28 Peacebloom, 28 Empty Vial"] = "28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 56 Terrestrine, 28 Pacifique, 28 Fiole vide",
  ["30x {s:3171:inv_potion_06:Elixir of Wisdom} - 30 Mageroyal, 60 Briarthorn, 30 Empty Vial"] = "30x {s:3171:inv_potion_06:Elixir of Wisdom} - 30 Mage royal, 60 Églantine, 30 Fiole vide",
  ["Keep the elixirs if you also level Tailoring, you will need them for the Gloves of Meditation."] = "Garde les élixirs si tu montes aussi la Couture, tu en auras besoin pour les Gloves of Meditation.",
  ["10x {s:3173:inv_potion_71:Lesser Mana Potion} - 10 Mageroyal, 10 Stranglekelp, 10 Empty Vial"] = "10x {s:3173:inv_potion_71:Lesser Mana Potion} - 10 Mage royal, 10 Étouffante, 10 Fiole vide",
  ["20x {s:7837:inv_potion_38:Fire Oil} - 40 Firefin Snapper, 20 Empty Vial"] = "20x {s:7837:inv_potion_38:Fire Oil} - 40 Firefin Snapper, 20 Fiole vide",
  ["You get 2 oils from every craft. Keep 30 of them, you will need them for the Elixir of Fire Power in the next part."] = "Chaque fabrication te donne 2 huiles. Garde-en 30, tu en auras besoin pour l'Elixir of Fire Power dans la partie suivante.",
  ["Expert Alchemy (150-225)"] = "Alchimie (Expert) (150-225)",
  ["To train past 150, visit {n:0:horde:Doctor Herbert Halsey} in Undercity (Horde) or {n:0:alliance:Ainethil} in Darnassus (Alliance) and learn Expert Alchemy. You need {b}Alchemy 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Pour dépasser 150, va voir {n:0:horde:Doctor Herbert Halsey} à Fossoyeuse (Horde) ou {n:0:alliance:Ainethil} à Darnassus (Alliance) et apprends Alchimie (Expert). Il te faut {b}Alchimie 125{/b} et {b}niveau 20{/b}, et ça coûte 50 pièces d'argent.",
  ["15x {s:7845:inv_potion_55:Elixir of Fire Power} - 30 Fire Oil, 15 Kingsblood, 15 Leaded Vial"] = "15x {s:7845:inv_potion_55:Elixir of Fire Power} - 30 Fire Oil, 15 Sang-royal, 15 Fiole plombée",
  ["These are the Fire Oils you kept."] = "Ce sont les Fire Oil que tu as gardées.",
  ["36x {s:3452:inv_potion_72:Mana Potion} - 36 Stranglekelp, 36 Kingsblood, 36 Leaded Vial"] = "36x {s:3452:inv_potion_72:Mana Potion} - 36 Étouffante, 36 Sang-royal, 36 Fiole plombée",
  ["36x {s:7259:inv_potion_06:Nature Protection Potion} - 36 Liferoot, 36 Stranglekelp, 36 Leaded Vial"] = "36x {s:7259:inv_potion_06:Nature Protection Potion} - 36 Vietérule, 36 Étouffante, 36 Fiole plombée",
  ["{i:6057:inv_scroll_03:Recipe: Nature Protection Potion} is sold by these vendors, it's bind on pickup, so buy it with the character that levels Alchemy:"] = "{i:6057:inv_scroll_03:Recipe: Nature Protection Potion} est vendue par ces marchands, elle est liée quand ramassée, alors achète-la avec le personnage qui monte l'Alchimie :",
  ["{n:0:horde:Bronk} in Feralas"] = "{n:0:horde:Bronk} à Féralas",
  ["{n:0:alliance:Logannas} in Feralas"] = "{n:0:alliance:Logannas} à Féralas",
  ["{n:0::Glyx Brewright} in Stranglethorn Vale"] = "{n:0::Glyx Brewright} dans la vallée de Strangleronce",
  ["{n:0::Alchemist Pestlezugg} in Tanaris"] = "{n:0::Alchemist Pestlezugg} à Tanaris",
  ["Artisan Alchemy (225-300)"] = "Alchimie (Artisan) (225-300)",
  ["To train past 225, visit {n:0:horde:Rogvar} in Stonard, Swamp of Sorrows (Horde) or {n:0:alliance:Kylanna Windwhisper} in Feathermoon Stronghold, Feralas (Alliance) and learn Artisan Alchemy. You need {b}Alchemy 200{/b} and {b}level 35{/b}."] = "Pour dépasser 225, va voir {n:0:horde:Rogvar} à Pierrêche, dans le marais des Chagrins (Horde) ou {n:0:alliance:Kylanna Windwhisper} au bastion de Plumelune, à Féralas (Alliance) et apprends Alchimie (Artisan). Il te faut {b}Alchimie 200{/b} et {b}niveau 35{/b}.",
  ["26x {s:7259:inv_potion_06:Nature Protection Potion} - 26 Liferoot, 26 Stranglekelp, 26 Leaded Vial"] = "26x {s:7259:inv_potion_06:Nature Protection Potion} - 26 Vietérule, 26 Étouffante, 26 Fiole plombée",
  ["15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 15 Blindweed, 15 Khadgar's Whisker, 15 Crystal Vial"] = "15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 15 Aveuglette, 15 Moustache de Khadgar, 15 Fiole en cristal",
  ["47x {s:17551:inv_potion_68:Stonescale Oil} - 47 Stonescale Eel, 47 Leaded Vial"] = "47x {s:17551:inv_potion_68:Stonescale Oil} - 47 Anguille pierre-écaille, 47 Fiole plombée",
  ["{b}Keep all of them{/b}, one craft makes 2 and the elixirs at 265 need all 94."] = "{b}Garde-les toutes{/b}, une fabrication en donne 2 et les élixirs à 265 nécessitent les 94.",
  ["Alternative recipe"] = "Recette alternative",
  ["If {i:13422:inv_misc_fish_11:Stonescale Eel} is expensive, skip this and keep making the Elixir of Greater Intellect until 265 (about 21), then make the Superior Mana Potions under 265-300."] = "Si {i:13422:inv_misc_fish_11:Stonescale Eel} est cher, saute cette étape et continue l'Elixir of Greater Intellect jusqu'à 265 (environ 21), puis fais les Superior Mana Potion de l'étape 265-300.",
  ["10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 10 Blindweed, 10 Khadgar's Whisker, 10 Crystal Vial"] = "10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 10 Aveuglette, 10 Moustache de Khadgar, 10 Fiole en cristal",
  ["47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 94 Stonescale Oil, 47 Sungrass, 47 Crystal Vial"] = "47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 94 Stonescale Oil, 47 Soleillette, 47 Fiole en cristal",
  ["{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense} is sold by {n:0:horde:Kor'geld} in Orgrimmar and {n:0:alliance:Soolie Berryfizz} in Ironforge."] = "{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense} est vendue par {n:0:horde:Kor'geld} à Orgrimmar et {n:0:alliance:Soolie Berryfizz} à Forgefer.",
  ["If you skipped the Stonescale Oil, make this:"] = "Si tu as sauté la Stonescale Oil, fais ceci :",
  ["55x {s:17553:inv_potion_74:Superior Mana Potion} - 110 Sungrass, 110 Blindweed, 55 Crystal Vial."] = "55x {s:17553:inv_potion_74:Superior Mana Potion} - 110 Soleillette, 110 Aveuglette, 55 Fiole en cristal.",
  ["{i:13477:inv_scroll_03:Recipe: Superior Mana Potion} is sold by {n:0:horde:Algernon} in Undercity and {n:0:alliance:Ulthir} in Darnassus."] = "{i:13477:inv_scroll_03:Recipe: Superior Mana Potion} est vendue par {n:0:horde:Algernon} à Fossoyeuse et {n:0:alliance:Ulthir} à Darnassus.",
  ["This WoW Forever Blacksmithing leveling guide will show you the fastest and cheapest way to level your Blacksmithing skill from 1 to 300. You will also find every trainer location and where to train Blacksmithing past 75, 150 and 225."] = "Ce guide de montée en Forge pour WoW Forever te montre la façon la plus rapide et la moins chère de monter ta compétence de Forge de 1 à 300. Tu y trouveras aussi l'emplacement de chaque maître et où apprendre la Forge au-delà de 75, 150 et 225.",
  ["Below you will find the full shopping list, the Blacksmithing trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Blacksmithing uses a lot of ore, so I recommend leveling it together with Mining, you will need a lot of gold if you want to buy everything from the Auction House."] = "Tu trouveras ci-dessous la liste de courses complète, les maîtres de Forge par zone de départ et capitale, et les recettes les moins chères pour chaque palier de compétence, d'Apprenti à Artisan. La Forge utilise beaucoup de minerai, je te conseille donc de la monter avec le Minage : il te faudra beaucoup d'or si tu veux tout acheter à l'hôtel des ventes.",
  ["The Thorium Bars include the 140 you need for the four quests."] = "Les barres de thorium incluent les 140 dont tu as besoin pour les quatre quêtes.",
  ["Blacksmithing Trainer Locations"] = "Emplacements des maîtres de Forge",
  ["Apprentice Blacksmithing has no level requirement in Forever, so you can learn it on a fresh character."] = "La Forge (Apprenti) n'a aucun niveau requis dans Forever, tu peux donc l'apprendre sur un personnage tout neuf.",
  ["Every capital city has a trainer except Darnassus. You can also ask a guard, then it will be marked with a red flag on your map."] = "Chaque capitale a un maître, sauf Darnassus. Tu peux aussi demander à un garde, il sera alors marqué d'un drapeau rouge sur ta carte.",
  ["Orgrimmar: {n:0:horde:Ug'thok}"] = "Orgrimmar : {n:0:horde:Ug'thok}",
  ["Undercity: {n:0:horde:Basil Frye}"] = "Fossoyeuse : {n:0:horde:Basil Frye}",
  ["Thunder Bluff: {n:0:horde:Thrag Stonehoof}"] = "Les Pitons-du-Tonnerre : {n:0:horde:Thrag Stonehoof}",
  ["{n:0:horde:Dwukk} at the forge in Razor Hill"] = "{n:0:horde:Dwukk} à la forge de Tranchecolline",
  ["There is no Blacksmithing trainer in Mulgore, go to {n:0:horde:Thrag Stonehoof} on the lower rise in Thunder Bluff"] = "Il n'y a pas de maître de Forge en Mulgore, va voir {n:0:horde:Thrag Stonehoof} sur le pic inférieur des Pitons-du-Tonnerre",
  ["{n:0:horde:Angus Hammerhand} at Bandarion Keep. Nobody near him sells a {i:5956:inv_hammer_20:Blacksmith Hammer}, {b}buy one before you go{/b} from {n:0:horde:Walter Mason} in Deathknell or {n:0:horde:Abigail Shiel} in Brill."] = "{n:0:horde:Angus Hammerhand} à Bandarion Keep. Personne près de lui ne vend de {i:5956:inv_hammer_20:Blacksmith Hammer}, {b}achètes-en un avant d'y aller{/b} auprès de {n:0:horde:Walter Mason} au Glas ou {n:0:horde:Abigail Shiel} à Brill.",
  ["{n:0::Daeann Steelwind} in Valanaar, {n:0::Aedi Thriceforged} in Shen'dar Village"] = "{n:0::Daeann Steelwind} à Valanaar, {n:0::Aedi Thriceforged} au village de Shen'dar",
  ["Stormwind City: {n:0:alliance:Dane Lindgren}"] = "Hurlevent : {n:0:alliance:Dane Lindgren}",
  ["Ironforge: {n:0:alliance:Groum Stonebeard}"] = "Forgefer : {n:0:alliance:Groum Stonebeard}",
  ["{n:0:alliance:Smith Argus} in Goldshire, across from the inn"] = "{n:0:alliance:Smith Argus} à Comté-de-l'Or, en face de l'auberge",
  ["{n:0:alliance:Tognus Flintfire} in Kharanos, across from the Thunderbrew Distillery"] = "{n:0:alliance:Tognus Flintfire} à Kharanos, en face de la distillerie Brasse-Tonnerre",
  ["There is no Blacksmithing trainer in Teldrassil or Darnassus, the closest one is {n:0:alliance:Delfrum Flintbeard} in Auberdine, Darkshore"] = "Il n'y a pas de maître de Forge à Teldrassil ni à Darnassus, le plus proche est {n:0:alliance:Delfrum Flintbeard} à Auberdine, en Sombrivage",
  ["You can find every Blacksmithing trainer for Horde and Alliance on my WoW Forever Blacksmithing Trainers page."] = "Tu trouveras tous les maîtres de Forge de la Horde et de l'Alliance sur ma page WoW Forever Blacksmithing Trainers.",
  ["Apprentice Blacksmithing (1-75)"] = "Forge (Apprenti) (1-75)",
  ["Buy a {i:5956:inv_hammer_20:Blacksmith Hammer} when you learn Blacksmithing, most recipes need it, so you can craft gear for yourself while you level. It costs a few copper, open your faction below to see who sells it closest to your trainer."] = "Achète un {i:5956:inv_hammer_20:Blacksmith Hammer} quand tu apprends la Forge, la plupart des recettes en ont besoin, et tu pourras ainsi fabriquer ton propre équipement en montant. Il coûte quelques pièces de cuivre, ouvre ta faction ci-dessous pour voir qui le vend le plus près de ton maître.",
  ["Horde vendors"] = "Marchands de la Horde",
  ["Vendor"] = "Marchand",
  ["{n:0:horde:Sumi}, right next to the trainer"] = "{n:0:horde:Sumi}, juste à côté du maître",
  ["Undercity"] = "Fossoyeuse",
  ["{n:0:horde:Samuel Van Brunt}, right next to the trainer"] = "{n:0:horde:Samuel Van Brunt}, juste à côté du maître",
  ["Thunder Bluff"] = "Les Pitons-du-Tonnerre",
  ["{n:0:horde:Taur Stonehoof}, right next to the trainer"] = "{n:0:horde:Taur Stonehoof}, juste à côté du maître",
  ["{n:0:horde:Flakk} in Razor Hill"] = "{n:0:horde:Flakk} à Tranchecolline",
  ["{n:0:horde:Walter Mason} in Deathknell {n:0:horde:Abigail Shiel} in Brill"] = "{n:0:horde:Walter Mason} au Glas {n:0:horde:Abigail Shiel} à Brill",
  ["{n:0::Halavuul Cragwind}, the Mining trainer in Valanaar {n:0::Aedi Thriceforged} in Shen'dar Village"] = "{n:0::Halavuul Cragwind}, le maître de Minage à Valanaar {n:0::Aedi Thriceforged} au village de Shen'dar",
  ["Alliance vendors"] = "Marchands de l'Alliance",
  ["Stormwind City"] = "Hurlevent",
  ["{n:0:alliance:Kaita Deepforge}, right next to the trainer"] = "{n:0:alliance:Kaita Deepforge}, juste à côté du maître",
  ["Ironforge"] = "Forgefer",
  ["{n:0:alliance:Thurgrum Deepforge}, right next to the trainer"] = "{n:0:alliance:Thurgrum Deepforge}, juste à côté du maître",
  ["{n:0:alliance:Tharynn Bouden} in Goldshire"] = "{n:0:alliance:Tharynn Bouden} à Comté-de-l'Or",
  ["{n:0:alliance:Thrawn Boltar}, right next to the trainer"] = "{n:0:alliance:Thrawn Boltar}, juste à côté du maître",
  ["Darkshore"] = "Sombrivage",
  ["{n:0:alliance:Elisa Steelhand} in Auberdine, right next to the trainer"] = "{n:0:alliance:Elisa Steelhand} à Auberdine, juste à côté du maître",
  ["30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 30 Rough Stone"] = "30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 30 Pierre brute",
  ["30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 60 Rough Stone"] = "30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 60 Pierre brute",
  ["Keep 10 of them, you need them for the Silver Rods at 75."] = "Garde-en 10, tu en auras besoin pour les Silver Rod à 75.",
  ["36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 72 Coarse Stone"] = "36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 72 Pierre grossière",
  ["Make all 36, you will need them for the bracers at 95 and 112."] = "Fais les 36, tu en auras besoin pour les brassards à 95 et 112.",
  ["If you are not at 75 after these, make a few more."] = "Si tu n'es pas à 75 après ça, fais-en quelques-uns de plus.",
  ["Journeyman Blacksmithing (75-150)"] = "Forge (Compagnon) (75-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Blacksmithing. You need {b}Blacksmithing 50{/b} and {b}level 10{/b}:"] = "Pour dépasser 75, va voir l'un de ces maîtres et apprends Forge (Compagnon). Il te faut {b}Forge 50{/b} et {b}niveau 10{/b} :",
  ["Orgrimmar: {n:0:horde:Snarl}"] = "Orgrimmar : {n:0:horde:Snarl}",
  ["Undercity: {n:0:horde:James Van Brunt}"] = "Fossoyeuse : {n:0:horde:James Van Brunt}",
  ["Thunder Bluff: {n:0:horde:Karn Stonehoof}"] = "Les Pitons-du-Tonnerre : {n:0:horde:Karn Stonehoof}",
  ["Tirisfal Glades: {n:0:horde:Angus Hammerhand} at Bandarion Keep"] = "Clairières de Tirisfal : {n:0:horde:Angus Hammerhand} à Bandarion Keep",
  ["Zephras Isle: {n:0::Daeann Steelwind} in Valanaar"] = "Zephras Isle : {n:0::Daeann Steelwind} à Valanaar",
  ["Stormwind City: {n:0:alliance:Therum Deepforge}"] = "Hurlevent : {n:0:alliance:Therum Deepforge}",
  ["Ironforge: {n:0:alliance:Rotgath Stonebeard}"] = "Forgefer : {n:0:alliance:Rotgath Stonebeard}",
  ["5x {s:7818:inv_staff_01:Silver Rod} - 5 Silver Bar, 10 Rough Grinding Stone"] = "5x {s:7818:inv_staff_01:Silver Rod} - 5 Barre d'argent, 10 Rough Grinding Stone",
  ["You need the {i:5956:inv_hammer_20:Blacksmith Hammer} from here on."] = "À partir d'ici, il te faut le {i:5956:inv_hammer_20:Blacksmith Hammer}.",
  ["Make 5x {s:2666:inv_belt_03:Runed Copper Belt} instead (10 Copper Bar each) if one Silver Bar costs more than 10 Copper Bars."] = "Fais plutôt 5x {s:2666:inv_belt_03:Runed Copper Belt} (10 Barre de cuivre chacune) si une barre d'argent coûte plus cher que 10 barres de cuivre.",
  ["18x {s:2666:inv_belt_03:Runed Copper Belt} - 180 Copper Bar"] = "18x {s:2666:inv_belt_03:Runed Copper Belt} - 180 Barre de cuivre",
  ["5x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 25 Bronze Bar, 10 Coarse Grinding Stone"] = "5x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 25 Barre de bronze, 10 Coarse Grinding Stone",
  ["Use 10 of the Coarse Grinding Stones you made at 50 and keep the other 26 for 112."] = "Utilise 10 des Coarse Grinding Stone que tu as faites à 50 et garde les 26 autres pour 112.",
  ["20x {s:3337:inv_stone_grindingstone_03:Heavy Grinding Stone} - 60 Heavy Stone"] = "20x {s:3337:inv_stone_grindingstone_03:Heavy Grinding Stone} - 60 Pierre lourde",
  ["Keep them, you need all 20 for the Golden Scale Bracers at 180."] = "Garde-les, il te les faut toutes les 20 pour les Golden Scale Bracers à 180.",
  ["13x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 65 Bronze Bar, 26 Coarse Grinding Stone"] = "13x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 65 Barre de bronze, 26 Coarse Grinding Stone",
  ["24x {s:2742:inv_sword_04:Bronze Shortsword} - 120 Bronze Bar, 96 Weak Flux, 48 Medium Leather"] = "24x {s:2742:inv_sword_04:Bronze Shortsword} - 120 Barre de bronze, 96 Fondant faible, 48 Cuir moyen",
  ["I recommend these over the Patterned Bronze Bracers because they sell for more than twice as much to a vendor, so they end up cheaper."] = "Je te les conseille plutôt que les Patterned Bronze Bracers car elles se revendent plus de deux fois plus cher à un marchand, donc elles reviennent moins cher.",
  ["{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} and the {i:3466:inv_misc_ammo_gunpowder_01:Strong Flux} for the Bronze Warhammers (140-150) are sold by the Blacksmithing Supply vendor right next to the Blacksmithing trainer in every capital city."] = "Le {i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} et le {i:3466:inv_misc_ammo_gunpowder_01:Strong Flux} pour les Bronze Warhammer (140-150) sont vendus par le marchand de fournitures de forge juste à côté du maître de Forge dans chaque capitale.",
  ["If you disenchant your greens:"] = "Si tu désenchantes tes objets verts :",
  ["24x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 120 Bronze Bar, 48 Coarse Grinding Stone."] = "24x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 120 Barre de bronze, 48 Coarse Grinding Stone.",
  ["10x {s:9985:inv_hammer_18:Bronze Warhammer} - 80 Bronze Bar, 10 Strong Flux, 10 Medium Leather"] = "10x {s:9985:inv_hammer_18:Bronze Warhammer} - 80 Barre de bronze, 10 Fondant puissant, 10 Cuir moyen",
  ["Expert Blacksmithing (150-215)"] = "Forge (Expert) (150-215)",
  ["To train past 150, visit {n:0:horde:Saru Steelfury} in Orgrimmar (Horde) or {n:0:alliance:Bengus Deepforge} in Ironforge (Alliance) and learn Expert Blacksmithing. You need {b}Blacksmithing 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Pour dépasser 150, va voir {n:0:horde:Saru Steelfury} à Orgrimmar (Horde) ou {n:0:alliance:Bengus Deepforge} à Forgefer (Alliance) et apprends Forge (Expert). Il te faut {b}Forge 125{/b} et {b}niveau 20{/b}, et ça coûte 50 pièces d'argent.",
  ["30x {s:3501:inv_bracer_06:Green Iron Bracers} - 180 Iron Bar, 30 Green Dye"] = "30x {s:3501:inv_bracer_06:Green Iron Bracers} - 180 Barre de fer, 30 Teinture verte",
  ["Green Dye is sold by {n:0:horde:Tamar} in Orgrimmar and {n:0:alliance:Bombus Finespindle} in Ironforge."] = "La teinture verte est vendue par {n:0:horde:Tamar} à Orgrimmar et {n:0:alliance:Bombus Finespindle} à Forgefer.",
  ["8x {s:9920:inv_stone_grindingstone_04:Solid Grinding Stone} - 32 Solid Stone"] = "8x {s:9920:inv_stone_grindingstone_04:Solid Grinding Stone} - 32 Pierre solide",
  ["Keep them, you need 6 for the Heavy Mithril Axes at 210."] = "Garde-les, il t'en faut 6 pour les Heavy Mithril Axe à 210.",
  ["20x {s:7223:inv_bracer_10:Golden Scale Bracers} - 100 Steel Bar, 40 Heavy Grinding Stone"] = "20x {s:7223:inv_bracer_10:Golden Scale Bracers} - 100 Barre d'acier, 40 Heavy Grinding Stone",
  ["Use the 20 Heavy Grinding Stones you made at 100 and make 20 more (60 {i:2838:inv_stone_12:Heavy Stone})."] = "Utilise les 20 Heavy Grinding Stone que tu as faites à 100 et fais-en 20 de plus (60 {i:2838:inv_stone_12:Heavy Stone}).",
  ["If you have Mining 165, you can smelt the {i:3859:inv_ingot_steel:Steel Bars} yourself from {i:3575:inv_ingot_iron:Iron Bar} and {i:3857:inv_ore_tin_01:Coal}. Coal is sold by the Blacksmithing Supply vendor next to the Blacksmithing trainer in every capital city."] = "Si tu as Minage 165, tu peux fondre toi-même les {i:3859:inv_ingot_steel:Steel Bars} à partir de {i:3575:inv_ingot_iron:Iron Bar} et de {i:3857:inv_ore_tin_01:Coal}. Le charbon est vendu par le marchand de fournitures de forge à côté du maître de Forge dans chaque capitale.",
  ["Alliance players should keep 6 of these. You might need them if you choose Armorsmithing."] = "Les joueurs de l'Alliance devraient en garder 6. Tu pourrais en avoir besoin si tu choisis Fabricant d'armures.",
  ["17x {s:9931:inv_pants_04:Mithril Plate Pants} - 204 Mithril Bar"] = "17x {s:9931:inv_pants_04:Mithril Plate Pants} - 204 Barre de mithril",
  ["I recommend these over the Heavy Mithril Gauntlets because they sell for more than three times as much to a vendor, so they end up cheaper."] = "Je te les conseille plutôt que les Heavy Mithril Gauntlet car ils se revendent plus de trois fois plus cher à un marchand, donc ils reviennent moins cher.",
  ["6x {s:9993:inv_axe_14:Heavy Mithril Axe} - 72 Mithril Bar, 12 Citrine, 6 Solid Grinding Stone, 24 Heavy Leather"] = "6x {s:9993:inv_axe_14:Heavy Mithril Axe} - 72 Barre de mithril, 12 Citrine, 6 Solid Grinding Stone, 24 Cuir lourd",
  ["Keep 2 of these. You might need them if you choose Weaponsmithing."] = "Garde-en 2. Tu pourrais en avoir besoin si tu choisis Fabricant d'armes.",
  ["Blacksmithing Specializations"] = "Spécialisations de Forge",
  ["At {b}Blacksmithing 200{/b} and {b}level 40{/b}, you can specialize in Armorsmithing or Weaponsmithing to craft powerful armor or weapons. Choosing one is optional, you don't need it to level Blacksmithing, and you can choose later too."] = "À {b}Forge 200{/b} et {b}niveau 40{/b}, tu peux te spécialiser en Fabricant d'armures ou Fabricant d'armes pour fabriquer de puissantes armures ou armes. Ce choix est facultatif, tu n'en as pas besoin pour monter la Forge, et tu peux aussi choisir plus tard.",
  ["For information on how to become an Armorsmith or a Weaponsmith, please see my separate guides:"] = "Pour savoir comment devenir Fabricant d'armures ou Fabricant d'armes, consulte mes guides dédiés :",
  ["Artisan Blacksmithing (215-300)"] = "Forge (Artisan) (215-300)",
  ["To train past 225, visit {n:0::Brikk Keencraft} in Booty Bay, Stranglethorn Vale and learn Artisan Blacksmithing. You need {b}Blacksmithing 200{/b} and {b}level 35{/b}, and both factions learn it there."] = "Pour dépasser 225, va voir {n:0::Brikk Keencraft} à Baie-du-Butin, dans la vallée de Strangleronce, et apprends Forge (Artisan). Il te faut {b}Forge 200{/b} et {b}niveau 35{/b}, et les deux factions l'apprennent là-bas.",
  ["{i:7989:inv_scroll_06:Plans: Mithril Spurs} is a world drop. If you already have it, you can use the {b}Mithril Spurs{/b} tab instead."] = "{i:7989:inv_scroll_06:Plans: Mithril Spurs} est un butin aléatoire du monde. Si tu l'as déjà, tu peux utiliser l'onglet {b}Mithril Spurs{/b} à la place.",
  ["10x {s:9959:inv_chest_plate10:Heavy Mithril Breastplate} - 160 Mithril Bar"] = "10x {s:9959:inv_chest_plate10:Heavy Mithril Breastplate} - 160 Barre de mithril",
  ["Keep 2 of these. You might need them if you choose Armorsmithing."] = "Garde-en 2. Tu pourrais en avoir besoin si tu choisis Fabricant d'armures.",
  ["5x {s:16641:inv_stone_sharpeningstone_05:Dense Sharpening Stone} - 5 Dense Stone"] = "5x {s:16641:inv_stone_sharpeningstone_05:Dense Sharpening Stone} - 5 Pierre dense",
  ["16x {s:9968:inv_boots_plate_01:Heavy Mithril Boots} - 224 Mithril Bar, 64 Thick Leather"] = "16x {s:9968:inv_boots_plate_01:Heavy Mithril Boots} - 224 Barre de mithril, 64 Cuir épais",
  ["5x {s:16647:inv_belt_01:Imperial Plate Belt} - 110 Thorium Bar, 30 Rugged Leather, 5 Aquamarine"] = "5x {s:16647:inv_belt_01:Imperial Plate Belt} - 110 Barre de thorium, 30 Cuir robuste, 5 Aigue-marine",
  ["You can get the recipe from the {q:7653::Imperial Plate Belt} quest (Requires {b}level 50{/b}) in Tanaris from {n:14567::Derotain Mudsipper}. You will need 20 Thorium Bar to complete it. Do his {q:7652::A Blue Light Bargain} quest first, it unlocks the Imperial Plate quests."] = "Tu peux obtenir la recette grâce à la quête {q:7653::Imperial Plate Belt} ({b}niveau 50{/b} requis) à Tanaris, auprès de {n:14567::Derotain Mudsipper}. Il te faudra 20 Barre de thorium pour la terminer. Fais d'abord sa quête {q:7652::A Blue Light Bargain}, elle débloque les quêtes Imperial Plate.",
  ["{b}The next three recipes are also from the same NPC{/b}, so make sure to bring at least 140 Thorium Bar with you to get all 4 recipes."] = "{b}Les trois recettes suivantes viennent aussi du même PNJ{/b}, alors emporte au moins 140 Barre de thorium pour obtenir les 4 recettes.",
  ["If you have the plans for one of these world drops, you can make it from 240 instead:"] = "Si tu as les plans de l'un de ces butins du monde, tu peux le fabriquer à partir de 240 à la place :",
  ["240-255: 27x {s:10005:inv_sword_30:Dazzling Mithril Rapier} - 378 Mithril Bar, 27 Aquamarine, 54 Lesser Moonstone, 54 Moss Agate, 27 Solid Grinding Stone, 54 Mageweave Cloth"] = "240-255 : 27x {s:10005:inv_sword_30:Dazzling Mithril Rapier} - 378 Barre de mithril, 27 Aigue-marine, 54 Pierre de lune inférieure, 54 Agate mousse, 27 Solid Grinding Stone, 54 Tisse-mage",
  ["240-255: 20x {s:10009:inv_hammer_17:Runed Mithril Hammer} - 360 Mithril Bar, 40 Core of Earth, 20 Solid Grinding Stone, 80 Thick Leather"] = "240-255 : 20x {s:10009:inv_hammer_17:Runed Mithril Hammer} - 360 Barre de mithril, 40 Noyau de terre, 20 Solid Grinding Stone, 80 Cuir épais",
  ["240-255: 17x {s:16644:inv_bracer_13:Thorium Bracers} - 204 Thorium Bar, 68 Blue Power Crystal"] = "240-255 : 17x {s:16644:inv_bracer_13:Thorium Bracers} - 204 Barre de thorium, 68 Cristal de puissance bleu",
  ["10x {s:9964:ability_rogue_sprint:Mithril Spurs} - 40 Mithril Bar, 30 Solid Grinding Stone (120 Solid Stone)"] = "10x {s:9964:ability_rogue_sprint:Mithril Spurs} - 40 Barre de mithril, 30 Solid Grinding Stone (120 Pierre solide)",
  ["33x {s:9964:ability_rogue_sprint:Mithril Spurs} - 132 Mithril Bar, 99 Solid Grinding Stone (396 Solid Stone)"] = "33x {s:9964:ability_rogue_sprint:Mithril Spurs} - 132 Barre de mithril, 99 Solid Grinding Stone (396 Pierre solide)",
  ["{b}The next three recipes all come from one NPC in Tanaris{/b}, so make sure to bring at least 120 Thorium Bar with you to get all 3 recipes."] = "{b}Les trois recettes suivantes viennent toutes d'un même PNJ à Tanaris{/b}, alors emporte au moins 120 Barre de thorium pour obtenir les 3 recettes.",
  ["27x {s:16649:inv_bracer_19:Imperial Plate Bracers} - 540 Thorium Bar, 27 Star Ruby"] = "27x {s:16649:inv_bracer_19:Imperial Plate Bracers} - 540 Barre de thorium, 27 Rubis étoilé",
  ["You get the recipe from the {q:7655::Imperial Plate Bracer} quest (Requires {b}level 50{/b}) in Tanaris from {n:14567::Derotain Mudsipper}. You will need 20 Thorium Bar to complete it."] = "Tu obtiens la recette grâce à la quête {q:7655::Imperial Plate Bracer} ({b}niveau 50{/b} requis) à Tanaris, auprès de {n:14567::Derotain Mudsipper}. Il te faudra 20 Barre de thorium pour la terminer.",
  ["20x {s:16657:inv_boots_plate_01:Imperial Plate Boots} - 680 Thorium Bar, 20 Star Ruby, 20 Aquamarine"] = "20x {s:16657:inv_boots_plate_01:Imperial Plate Boots} - 680 Barre de thorium, 20 Rubis étoilé, 20 Aigue-marine",
  ["You get the recipe from the {q:7654::Imperial Plate Boots} quest, it needs 40 Thorium Bar."] = "Tu obtiens la recette grâce à la quête {q:7654::Imperial Plate Boots}, elle demande 40 Barre de thorium.",
  ["{b}Note:{/b} It wasn't possible to level this far on the beta, so this part only relies on the data I found in the game files. There might be more recipes we haven't discovered yet, but if there is nothing else, these are the only recipes you can use to level until 300."] = "{b}Remarque :{/b} il n'était pas possible de monter aussi haut sur la bêta, cette partie repose donc uniquement sur les données que j'ai trouvées dans les fichiers du jeu. Il y a peut-être d'autres recettes que nous n'avons pas encore découvertes, mais s'il n'y a rien d'autre, ce sont les seules recettes qui te permettent de monter jusqu'à 300.",
  ["10x {s:16730:inv_pants_04:Imperial Plate Leggings} - 440 Thorium Bar, 20 Star Ruby"] = "10x {s:16730:inv_pants_04:Imperial Plate Leggings} - 440 Barre de thorium, 20 Rubis étoilé",
  ["You get the recipe from the {q:7658::Imperial Plate Leggings} quest, it needs 60 Thorium Bar."] = "Tu obtiens la recette grâce à la quête {q:7658::Imperial Plate Leggings}, elle demande 60 Barre de thorium.",
  ["This WoW Forever Enchanting leveling guide will show you the fastest and cheapest way to level your Enchanting skill from 1 to 300. You will also find every trainer location and where to train Enchanting past 75, 150 and 225."] = "Ce guide de montée en Enchantement pour WoW Forever te montre la façon la plus rapide et la moins chère de monter ta compétence d'Enchantement de 1 à 300. Tu y trouveras aussi l'emplacement de chaque maître et où apprendre l'Enchantement au-delà de 75, 150 et 225.",
  ["Enchanting goes well with Tailoring because you don't need a gathering profession for either of them, and you can disenchant the items you made with Tailoring. Below you will find the shopping list, the Enchanting trainers by starting zone and capital city, and the cheapest enchants for every skill range. Forever added a few new low level recipes, so the first 70 points are cheaper than in Classic."] = "L'Enchantement va bien avec la Couture car aucun des deux ne nécessite de métier de récolte, et tu peux désenchanter les objets fabriqués en Couture. Tu trouveras ci-dessous la liste de courses, les maîtres d'Enchantement par zone de départ et capitale, et les enchantements les moins chers pour chaque palier de compétence. Forever a ajouté quelques nouvelles recettes de bas niveau, donc les 70 premiers points coûtent moins cher que dans Classic.",
  ["An alternative replaces the whole row, so buy the one that is cheaper."] = "Une alternative remplace toute la ligne, alors achète celle qui est la moins chère.",
  ["Enchanting Trainer Locations"] = "Emplacements des maîtres d'Enchantement",
  ["Apprentice Enchanting has no level requirement in Forever, so you can learn it on a fresh character."] = "L'Enchantement (Apprenti) n'a aucun niveau requis dans Forever, tu peux donc l'apprendre sur un personnage tout neuf.",
  ["Orgrimmar: {n:0:horde:Jhag}"] = "Orgrimmar : {n:0:horde:Jhag}",
  ["Undercity: {n:0:horde:Malcomb Wynn}"] = "Fossoyeuse : {n:0:horde:Malcomb Wynn}",
  ["Thunder Bluff: {n:0:horde:Mot Dawnstrider}"] = "Les Pitons-du-Tonnerre : {n:0:horde:Mot Dawnstrider}",
  ["{n:0:horde:Pa'zula} in Sen'jin Village"] = "{n:0:horde:Pa'zula} au village de Sen'jin",
  ["There is no Enchanting trainer in Mulgore, go to {n:0:horde:Mot Dawnstrider} on the middle rise in Thunder Bluff"] = "Il n'y a pas de maître d'Enchantement en Mulgore, va voir {n:0:horde:Mot Dawnstrider} sur le pic central des Pitons-du-Tonnerre",
  ["{n:0:horde:Vance Undergloom} upstairs in the inn in Brill"] = "{n:0:horde:Vance Undergloom} à l'étage de l'auberge de Brill",
  ["{n:0::Eaysaa Brightgust} in Valanaar, {n:0::Nasalanna Windsinger} in Shen'dar Village"] = "{n:0::Eaysaa Brightgust} à Valanaar, {n:0::Nasalanna Windsinger} au village de Shen'dar",
  ["Stormwind City: {n:0:alliance:Betty Quin}"] = "Hurlevent : {n:0:alliance:Betty Quin}",
  ["Ironforge: {n:0:alliance:Thonys Pillarstone}"] = "Forgefer : {n:0:alliance:Thonys Pillarstone}",
  ["Darnassus: {n:0:alliance:Lalina Summermoon}"] = "Darnassus : {n:0:alliance:Lalina Summermoon}",
  ["There is no Enchanting trainer in Elwynn Forest, go to {n:0:alliance:Betty Quin} in the Mage Quarter in Stormwind City"] = "Il n'y a pas de maître d'Enchantement dans la forêt d'Elwynn, va voir {n:0:alliance:Betty Quin} dans le quartier des Mages à Hurlevent",
  ["There is no Enchanting trainer in Dun Morogh, go to {n:0:alliance:Thonys Pillarstone} at the Great Forge in Ironforge"] = "Il n'y a pas de maître d'Enchantement à Dun Morogh, va voir {n:0:alliance:Thonys Pillarstone} à la Grande Forge de Forgefer",
  ["{n:0:alliance:Alanna Raveneye} at the Oracle Glade, in the north-west of Teldrassil"] = "{n:0:alliance:Alanna Raveneye} à la clairière de l'Oracle, au nord-ouest de Teldrassil",
  ["You can find every Enchanting trainer for Horde and Alliance on my WoW Forever Enchanting Trainers page."] = "Tu trouveras tous les maîtres d'Enchantement de la Horde et de l'Alliance sur ma page WoW Forever Enchanting Trainers.",
  ["Enchanting Macro for Faster Leveling"] = "Macro d'Enchantement pour monter plus vite",
  ["I highly recommend using this macro to speed up the leveling process."] = "Je te recommande vivement d'utiliser cette macro pour accélérer la montée.",
  ["This macro presses the Create button for you and confirms the prompt that asks if you want to replace the enchant already on the item, without any extra clicks."] = "Cette macro appuie sur le bouton Créer à ta place et confirme la fenêtre qui demande si tu veux remplacer l'enchantement déjà présent sur l'objet, sans aucun clic supplémentaire.",
  ["If you have never made a macro, type /m in the chat and press Enter, click New, give it a name and paste these two lines into it."] = "Si tu n'as jamais créé de macro, tape /m dans le chat et appuie sur Entrée, clique sur Nouveau, donne-lui un nom et colle-y ces deux lignes.",
  ["How to Use"] = "Utilisation",
  ["Place the macro on your action bar"] = "Place la macro sur ta barre d'action",
  ["Open your Enchanting profession window"] = "Ouvre ta fenêtre de métier Enchantement",
  ["Select the enchant you want to craft (make sure it's the right one)"] = "Sélectionne l'enchantement que tu veux fabriquer (vérifie que c'est le bon)",
  ["Put the item you want to enchant into the optional target slot"] = "Place l'objet à enchanter dans l'emplacement de cible facultatif",
  ["Press the macro repeatedly"] = "Appuie plusieurs fois sur la macro",
  ["Disenchanting"] = "Désenchantement",
  ["You get {s:13262:inv_enchant_disenchant:Disenchant} together with Apprentice Enchanting. In WoW Forever {b}Disenchant is not in your spellbook{/b}, it's in the Enchanting box of the Professions window."] = "Tu obtiens {s:13262:inv_enchant_disenchant:Disenchant} en même temps qu'Enchantement (Apprenti). Dans WoW Forever, {b}Désenchanter n'est pas dans ton grimoire{/b}, il se trouve dans le cadre Enchantement de la fenêtre des métiers.",
  ["If you are looking for the disenchanting table, it's in my disenchanting guide, and if you can't find the Disenchant button, the guide shows it with pictures:"] = "Si tu cherches le tableau de désenchantement, il est dans mon guide de désenchantement, et si tu ne trouves pas le bouton Désenchanter, le guide le montre en images :",
  ["Apprentice Enchanting (1-70)"] = "Enchantement (Apprenti) (1-70)",
  ["1x {s:7421:inv_staff_goldfeathered_01:Runed Copper Rod} - 1 Copper Rod, 1 Mote of Magic"] = "1x {s:7421:inv_staff_goldfeathered_01:Runed Copper Rod} - 1 Bâtonnet en cuivre, 1 Mote of Magic",
  ["The {i:6217:inv_misc_flute_01:Copper Rod} and the {i:247786:inv_elemental_mote_mana:Mote of Magic} are sold by the Enchanting Supply vendor near your trainer, don't buy them from the Auction House."] = "Le {i:6217:inv_misc_flute_01:Copper Rod} et le {i:247786:inv_elemental_mote_mana:Mote of Magic} sont vendus par le marchand de fournitures d'enchantement près de ton maître, ne les achète pas à l'hôtel des ventes.",
  ["{b}If you are leveling in a starting zone with a low level character{/b}, you can buy the Copper Rod from a trade vendor there, but the Mote of Magic is only sold by Enchanting vendors. In the starting zones only the trainers on {b}Zephras Isle{/b} and in {b}Tirisfal Glades{/b} (Brill) sell it, everyone else has to visit the trainer in the capital city, the vendor stands right next to them."] = "{b}Si tu montes dans une zone de départ avec un personnage de bas niveau{/b}, tu peux acheter le bâtonnet en cuivre chez un marchand de fournitures commerciales sur place, mais le Mote of Magic n'est vendu que par les marchands d'enchantement. Dans les zones de départ, seuls les maîtres de {b}Zephras Isle{/b} et des {b}clairières de Tirisfal{/b} (Brill) le vendent, tous les autres doivent aller voir le maître de la capitale, le marchand se trouve juste à côté.",
  ["Make one of these:"] = "Fais l'un de ces enchantements :",
  ["50x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 50 Strange Dust"] = "50x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 50 Poussière étrange",
  ["50x {s:7428:spell_holy_greaterheal:Enchant Bracer - Minor Deflect} - 50 Lesser Magic Essence"] = "50x {s:7428:spell_holy_greaterheal:Enchant Bracer - Minor Deflect} - 50 Essence magique inférieure",
  ["A {i:10939:inv_enchant_essencemagiclarge:Greater Magic Essence} turns into 3 Lesser Magic Essence when you right-click it in your bags, so you can buy those too."] = "Une {i:10939:inv_enchant_essencemagiclarge:Greater Magic Essence} se transforme en 3 Essence magique inférieure quand tu fais un clic droit dessus dans tes sacs, tu peux donc aussi acheter celles-là.",
  ["Journeyman Enchanting (70-150)"] = "Enchantement (Compagnon) (70-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Enchanting. You need {b}Enchanting 50{/b} and {b}level 10{/b}:"] = "Pour dépasser 75, va voir l'un de ces maîtres et apprends Enchantement (Compagnon). Il te faut {b}Enchantement 50{/b} et {b}niveau 10{/b} :",
  ["Orgrimmar: {n:0:horde:Godan}"] = "Orgrimmar : {n:0:horde:Godan}",
  ["Undercity: {n:0:horde:Lavinia Crowe}"] = "Fossoyeuse : {n:0:horde:Lavinia Crowe}",
  ["Thunder Bluff: {n:0:horde:Teg Dawnstrider}"] = "Les Pitons-du-Tonnerre : {n:0:horde:Teg Dawnstrider}",
  ["Stormwind City: {n:0:alliance:Lucan Cordell}"] = "Hurlevent : {n:0:alliance:Lucan Cordell}",
  ["Ironforge: {n:0:alliance:Gimble Thistlefuzz}"] = "Forgefer : {n:0:alliance:Gimble Thistlefuzz}",
  ["Darnassus: {n:0:alliance:Taladan}"] = "Darnassus : {n:0:alliance:Taladan}",
  ["If you bought Strange Dust pick the {b}Strange Dust{/b} tab, if you bought Lesser Magic Essence pick the {b}Lesser Magic Essence{/b} tab."] = "Si tu as acheté de la Poussière étrange, choisis l'onglet {b}Poussière étrange{/b}, si tu as acheté de l'Essence magique inférieure, choisis l'onglet {b}Essence magique inférieure{/b}.",
  ["Strange Dust"] = "Poussière étrange",
  ["Lesser Magic Essence"] = "Essence magique inférieure",
  ["49x {s:7426:spell_holy_greaterheal:Enchant Chest - Minor Absorption} - 49 Lesser Magic Essence"] = "49x {s:7426:spell_holy_greaterheal:Enchant Chest - Minor Absorption} - 49 Essence magique inférieure",
  ["1x {s:7795:inv_staff_01:Runed Silver Rod} - 1 Silver Rod, 3 Strange Dust, 4 Lesser Magic Essence, 1 Shadowgem"] = "1x {s:7795:inv_staff_01:Runed Silver Rod} - 1 Bâtonnet en argent, 3 Poussière étrange, 4 Essence magique inférieure, 1 Gemme d'ombre",
  ["{i:6338:inv_staff_01:Silver Rod} and every other rod in this guide (Golden, Truesilver, Arcanite) is made by Blacksmiths, you can buy them from the Auction House."] = "Le {i:6338:inv_staff_01:Silver Rod} et tous les autres bâtonnets de ce guide (en or, en vrai-argent, en arcanite) sont fabriqués par les forgerons, tu peux les acheter à l'hôtel des ventes.",
  ["23x {s:14807:inv_staff_07:Greater Magic Wand} - 23 Simple Wood, 46 Lesser Magic Essence"] = "23x {s:14807:inv_staff_07:Greater Magic Wand} - 23 Bois simple, 46 Essence magique inférieure",
  ["37x {s:7793:spell_holy_greaterheal:Enchant 2H Weapon - Lesser Intellect} - 148 Lesser Magic Essence"] = "37x {s:7793:spell_holy_greaterheal:Enchant 2H Weapon - Lesser Intellect} - 148 Essence magique inférieure",
  ["{i:6349:inv_misc_note_01:Formula: Enchant 2H Weapon - Lesser Intellect} is sold by these vendors:"] = "{i:6349:inv_misc_note_01:Formula: Enchant 2H Weapon - Lesser Intellect} est vendue par ces marchands :",
  ["{n:0:horde:Kithas} in Orgrimmar"] = "{n:0:horde:Kithas} à Orgrimmar",
  ["{n:0:horde:Nata Dawnstrider} in Thunder Bluff"] = "{n:0:horde:Nata Dawnstrider} aux Pitons-du-Tonnerre",
  ["{n:0:horde:Leo Sarn} in Silverpine Forest"] = "{n:0:horde:Leo Sarn} dans la forêt des Pins-Argentés",
  ["{n:0:alliance:Tilli Thistlefuzz} in Ironforge"] = "{n:0:alliance:Tilli Thistlefuzz} à Forgefer",
  ["Buy {i:20752:inv_misc_note_01:Formula: Minor Mana Oil} and {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} from them too, you will need them at 150 and 200."] = "Achète-leur aussi {i:20752:inv_misc_note_01:Formula: Minor Mana Oil} et {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}, tu en auras besoin à 150 et 200.",
  ["If you don't want to get the formula, make this:"] = "Si tu ne veux pas prendre la formule, fais ceci :",
  ["25x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 100 Strange Dust"] = "25x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 100 Poussière étrange",
  ["23x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 23 Strange Dust"] = "23x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 23 Poussière étrange",
  ["15x {s:7457:spell_holy_greaterheal:Enchant Bracer - Minor Stamina} - 30 Strange Dust"] = "15x {s:7457:spell_holy_greaterheal:Enchant Bracer - Minor Stamina} - 30 Poussière étrange",
  ["9x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 18 Strange Dust"] = "9x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 18 Poussière étrange",
  ["32x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 64 Strange Dust"] = "32x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 64 Poussière étrange",
  ["20x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 80 Strange Dust"] = "20x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 80 Poussière étrange",
  ["If 20 Soul Dust cost less than 80 Strange Dust, make this:"] = "Si 20 Poussière d'âme coûtent moins cher que 80 Poussière étrange, fais ceci :",
  ["20x {s:13501:spell_holy_greaterheal:Enchant Bracer - Lesser Stamina} - 20 Soul Dust."] = "20x {s:13501:spell_holy_greaterheal:Enchant Bracer - Lesser Stamina} - 20 Poussière d'âme.",
  ["Expert Enchanting (150-225)"] = "Enchantement (Expert) (150-225)",
  ["To train past 150, visit one of these trainers and learn Expert Enchanting. You need {b}Enchanting 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Pour dépasser 150, va voir l'un de ces maîtres et apprends Enchantement (Expert). Il te faut {b}Enchantement 125{/b} et {b}niveau 20{/b}, et ça coûte 50 pièces d'argent.",
  ["There is only one Expert Enchanting trainer for each faction. {n:0:horde:Hgarth} in Stonetalon Mountains at Sun Rock Retreat is the Horde trainer, he is up on the hill above the village. {n:0:alliance:Kitta Firewind} in Elwynn Forest is the Alliance trainer, she is at the top of the Tower of Azora."] = "Il n'y a qu'un seul maître d'Enchantement (Expert) par faction. {n:0:horde:Hgarth} aux Serres-Rocheuses, à la retraite du Roc-Soleil, est le maître de la Horde, il se trouve en haut de la colline au-dessus du village. {n:0:alliance:Kitta Firewind} dans la forêt d'Elwynn est la maîtresse de l'Alliance, elle se trouve au sommet de la tour d'Azora.",
  ["1x {s:13628:inv_staff_10:Runed Golden Rod} - 1 Golden Rod, 1 Iridescent Pearl, 1 Greater Astral Essence, 1 Soul Dust"] = "1x {s:13628:inv_staff_10:Runed Golden Rod} - 1 Bâtonnet en or, 1 Perle iridescente, 1 Essence astrale supérieure, 1 Poussière d'âme",
  ["16x {s:25125:inv_potion_98:Minor Mana Oil} - 16 Soul Dust, 32 Maple Seed, 16 Leaded Vial"] = "16x {s:25125:inv_potion_98:Minor Mana Oil} - 16 Poussière d'âme, 32 Graine d'érable, 16 Fiole plombée",
  ["{i:20752:inv_misc_note_01:Formula: Minor Mana Oil} is sold by these vendors:"] = "{i:20752:inv_misc_note_01:Formula: Minor Mana Oil} est vendue par ces marchands :",
  ["{n:0:horde:Thaddeus Webb} in Undercity"] = "{n:0:horde:Thaddeus Webb} à Fossoyeuse",
  ["{n:0:alliance:Vaean} in Darnassus"] = "{n:0:alliance:Vaean} à Darnassus",
  ["{n:0:alliance:Jessara Cordell} in Stormwind City"] = "{n:0:alliance:Jessara Cordell} à Hurlevent",
  ["Buy {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} from them too, you will need it at 200."] = "Achète-leur aussi {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}, tu en auras besoin à 200.",
  ["{i:17034:inv_misc_food_02:Maple Seed} is sold by Reagent vendors and {i:3372:inv_potion_85:Leaded Vial} by Alchemy Supply vendors."] = "{i:17034:inv_misc_food_02:Maple Seed} est vendue par les marchands de composants et {i:3372:inv_potion_85:Leaded Vial} par les marchands de fournitures d'alchimie.",
  ["47x {s:13637:spell_holy_greaterheal:Enchant Boots - Lesser Agility} - 47 Soul Dust"] = "47x {s:13637:spell_holy_greaterheal:Enchant Boots - Lesser Agility} - 47 Poussière d'âme",
  ["If 2 Vision Dust cost less than 3 Soul Dust, stop the boots at 185 and make this until 200:"] = "Si 2 Poussière de vision coûtent moins cher que 3 Poussière d'âme, arrête les bottes à 185 et fais ceci jusqu'à 200 :",
  ["15x {s:13661:spell_holy_greaterheal:Enchant Bracer - Strength} - 15 Vision Dust."] = "15x {s:13661:spell_holy_greaterheal:Enchant Bracer - Strength} - 15 Poussière de vision.",
  ["1x {s:13702:inv_staff_11:Runed Truesilver Rod} - 1 Truesilver Rod, 1 Black Pearl, 1 Greater Mystic Essence, 1 Vision Dust"] = "1x {s:13702:inv_staff_11:Runed Truesilver Rod} - 1 Bâtonnet en vrai-argent, 1 Perle noire, 1 Essence mystique supérieure, 1 Poussière de vision",
  ["25x {s:25126:inv_potion_103:Lesser Wizard Oil} - 25 Vision Dust, 50 Stranglethorn Seed, 25 Leaded Vial"] = "25x {s:25126:inv_potion_103:Lesser Wizard Oil} - 25 Poussière de vision, 50 Graine de Strangleronce, 25 Fiole plombée",
  ["If you didn't buy {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} yet, the vendors are listed at the 151-165 step above."] = "Si tu n'as pas encore acheté {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}, les marchands sont indiqués à l'étape 151-165 plus haut.",
  ["{i:17035:inv_misc_food_02:Stranglethorn Seed} is sold by Reagent vendors and {i:3372:inv_potion_85:Leaded Vial} by Alchemy Supply vendors."] = "{i:17035:inv_misc_food_02:Stranglethorn Seed} est vendue par les marchands de composants et {i:3372:inv_potion_85:Leaded Vial} par les marchands de fournitures d'alchimie.",
  ["5x {s:13746:spell_holy_greaterheal:Enchant Cloak - Greater Defense} - 5 Vision Dust"] = "5x {s:13746:spell_holy_greaterheal:Enchant Cloak - Greater Defense} - 5 Poussière de vision",
  ["Artisan Enchanting (225-300)"] = "Enchantement (Artisan) (225-300)",
  ["The Expert Enchanting trainers only teach you up to 225. To train Enchanting past 225 you need {b}level 35{/b} and {b}Enchanting 200{/b}, then learn Artisan Enchanting from Annora in Uldaman (I explain below how to find her). {b}She is the only trainer who teaches Artisan Enchanting.{/b}"] = "Les maîtres d'Enchantement (Expert) ne t'enseignent que jusqu'à 225. Pour dépasser 225, il te faut {b}niveau 35{/b} et {b}Enchantement 200{/b}, puis apprends Enchantement (Artisan) auprès d'Annora à Uldaman (j'explique plus bas comment la trouver). {b}C'est la seule à enseigner Enchantement (Artisan).{/b}",
  ["There are a few recipes only Annora teaches, {b}so bring enough gold to learn every recipe and enough materials to reach Enchanting 250{/b}, otherwise you have to go back to Uldaman for the higher recipes. Around 50 {i:11137:inv_enchant_dustvision:Vision Dust} gets you to 250."] = "Quelques recettes ne sont enseignées que par Annora, {b}alors prends assez d'or pour apprendre toutes les recettes et assez de matériaux pour atteindre Enchantement 250{/b}, sinon tu devras retourner à Uldaman pour les recettes plus élevées. Environ 50 {i:11137:inv_enchant_dustvision:Vision Dust} te mènent à 250.",
  ["How to enter Uldaman"] = "Comment entrer dans Uldaman",
  ["Uldaman is in the Badlands and it has two entrances, use the back entrance. You can't solo it at level 35, so go with a party or ask a level 60 to help."] = "Uldaman se trouve dans les Terres ingrates et possède deux entrées, utilise l'entrée arrière. Tu ne peux pas le faire seul au niveau 35, alors va-y en groupe ou demande de l'aide à un niveau 60.",
  ["How to find Annora"] = "Comment trouver Annora",
  ["Annora only spawns once you {b}kill every mob in the area she is in!{/b}"] = "Annora n'apparaît qu'une fois que tu as {b}tué tous les monstres de la zone où elle se trouve !{/b}",
  ["{b}Don't forget to learn everything from Annora before you leave Uldaman!{/b} The recipes from 230 up are taught nowhere else."] = "{b}N'oublie pas d'apprendre tout ce qu'Annora enseigne avant de quitter Uldaman !{/b} Les recettes à partir de 230 ne sont enseignées nulle part ailleurs.",
  ["Recipe"] = "Recette",
  ["Skill"] = "Compétence",
  ["Cost"] = "Coût",
  ["{b}Artisan Enchanting{/b}"] = "{b}Enchantement (Artisan){/b}",
  ["37x {s:13815:spell_holy_greaterheal:Enchant Gloves - Agility} - 37 Vision Dust"] = "37x {s:13815:spell_holy_greaterheal:Enchant Gloves - Agility} - 37 Poussière de vision",
  ["20x {s:25127:inv_potion_99:Lesser Mana Oil} - 20 Dream Dust, 20 Purple Lotus, 20 Crystal Vial"] = "20x {s:25127:inv_potion_99:Lesser Mana Oil} - 20 Poussière de rêve, 20 Lotus pourpre, 20 Fiole en cristal",
  ["{i:20754:inv_misc_note_01:Formula: Lesser Mana Oil} is sold by {n:0::Kania} in Silithus, she is upstairs in the inn. {i:8925:inv_potion_86:Crystal Vial} is sold by {n:0::Mishta} in Silithus or any Alchemy Supply vendor."] = "{i:20754:inv_misc_note_01:Formula: Lesser Mana Oil} est vendue par {n:0::Kania} en Silithus, elle se trouve à l'étage de l'auberge. {i:8925:inv_potion_86:Crystal Vial} est vendue par {n:0::Mishta} en Silithus ou par n'importe quel marchand de fournitures d'alchimie.",
  ["If you don't have Purple Lotus, make {s:13939:spell_holy_greaterheal:Enchant Bracer - Greater Strength} instead (1 Dream Dust, 2 Lesser Nether Essence each), Annora teaches it."] = "Si tu n'as pas de Lotus pourpre, fais plutôt {s:13939:spell_holy_greaterheal:Enchant Bracer - Greater Strength} (1 Poussière de rêve, 2 Essence du néant inférieure chacun), Annora l'enseigne.",
  ["40x {s:20017:spell_holy_greaterheal:Enchant Shield - Greater Stamina} - 240 Dream Dust"] = "40x {s:20017:spell_holy_greaterheal:Enchant Shield - Greater Stamina} - 240 Poussière de rêve",
  ["{i:16217:inv_misc_note_01:Formula: Enchant Shield - Greater Stamina} is sold by {n:0:horde:Daniel Bartlett} in Undercity and {n:0:alliance:Mythrin'dir} in Darnassus. It's bind on pickup, so don't buy it on an alt."] = "{i:16217:inv_misc_note_01:Formula: Enchant Shield - Greater Stamina} est vendue par {n:0:horde:Daniel Bartlett} à Fossoyeuse et {n:0:alliance:Mythrin'dir} à Darnassus. Elle est liée quand ramassée, alors ne l'achète pas sur un reroll.",
  ["From 290 you can make the Runed Arcanite Rod, see the next step."] = "À partir de 290, tu peux faire le Runed Arcanite Rod, voir l'étape suivante.",
  ["1x {s:20051:inv_wand_09:Runed Arcanite Rod} - 1 Arcanite Rod, 1 Golden Pearl, 10 Illusion Dust, 4 Greater Eternal Essence, 4 Small Brilliant Shard, 2 Large Brilliant Shard"] = "1x {s:20051:inv_wand_09:Runed Arcanite Rod} - 1 Bâtonnet en arcanite, 1 Perle dorée, 10 Poussière d'illusion, 4 Essence éternelle supérieure, 4 Petit éclat brillant, 2 Grand éclat brillant",
  ["{i:16243:inv_misc_note_01:Formula: Runed Arcanite Rod} is sold by {n:0::Lorelae Wintersong} in Moonglade at Nighthaven."] = "{i:16243:inv_misc_note_01:Formula: Runed Arcanite Rod} est vendue par {n:0::Lorelae Wintersong} à Reflet-de-Lune, à Havre-de-Nuit.",
  ["{b}You need this rod for some recipes from 290 and for most recipes at 300{/b}, Crusader for example. You can make it from 290, but if you don't need it yet, you can make it later and make one more Shield for the last point instead."] = "{b}Tu as besoin de ce bâtonnet pour certaines recettes à partir de 290 et pour la plupart des recettes à 300{/b}, Croisé par exemple. Tu peux le fabriquer dès 290, mais si tu n'en as pas encore besoin, tu peux le faire plus tard et fabriquer un bouclier de plus pour le dernier point à la place.",
  ["This WoW Forever Engineering leveling guide will show you the fastest and cheapest way to level your Engineering skill from 1 to 300. You will also find every trainer location and where to train Engineering past 75, 150 and 225."] = "Ce guide de montée en Ingénierie pour WoW Forever te montre la façon la plus rapide et la moins chère de monter ta compétence d'Ingénierie de 1 à 300. Tu y trouveras aussi l'emplacement de chaque maître et où apprendre l'Ingénierie au-delà de 75, 150 et 225.",
  ["Engineering is best combined with Mining, because almost everything you make needs stone and bars, and you can mine both. If you don't have Mining, you have to buy everything from the Auction House. Below you will find the shopping list, the Engineering trainers by starting zone and capital city, and the cheapest recipes for every skill range."] = "L'Ingénierie se marie le mieux avec le Minage, car presque tout ce que tu fabriques demande de la pierre et des barres, et tu peux récolter les deux. Si tu n'as pas le Minage, tu devras tout acheter à l'hôtel des ventes. Tu trouveras ci-dessous la liste de courses, les maîtres d'Ingénierie par zone de départ et capitale, et les recettes les moins chères pour chaque palier de compétence.",
  ["Engineering Trainer Locations"] = "Emplacements des maîtres d'Ingénierie",
  ["Apprentice Engineering has no level requirement in Forever, so you can learn it on a fresh character."] = "L'Ingénierie (Apprenti) n'a aucun niveau requis dans Forever, tu peux donc l'apprendre sur un personnage tout neuf.",
  ["There is no Engineering trainer in Thunder Bluff and Darnassus, the other four capitals have one. You can also ask a guard, then it will be marked with a red flag on your map."] = "Il n'y a pas de maître d'Ingénierie aux Pitons-du-Tonnerre ni à Darnassus, les quatre autres capitales en ont un. Tu peux aussi demander à un garde, il sera alors marqué d'un drapeau rouge sur ta carte.",
  ["Orgrimmar: {n:0:horde:Thund}"] = "Orgrimmar : {n:0:horde:Thund}",
  ["Undercity: {n:0:horde:Graham Van Talen}"] = "Fossoyeuse : {n:0:horde:Graham Van Talen}",
  ["{n:0:horde:Mukdrak} in Razor Hill, near the forge next to the road to Orgrimmar"] = "{n:0:horde:Mukdrak} à Tranchecolline, près de la forge à côté de la route d'Orgrimmar",
  ["{n:0::Twizwick Sprocketgrind} on the plateau above the Venture Co. Mine, hard to reach at low level. There is no anvil near him and nobody there sells the Blacksmith Hammer, so it's probably best to go to {n:0:horde:Thund} in Orgrimmar instead."] = "{n:0::Twizwick Sprocketgrind} sur le plateau au-dessus de la mine de la KapitalRisk, difficile d'accès à bas niveau. Il n'y a pas d'enclume près de lui et personne là-bas ne vend le Blacksmith Hammer, il vaut donc sans doute mieux aller voir {n:0:horde:Thund} à Orgrimmar.",
  ["There is no Engineering trainer in Tirisfal Glades, go to {n:0:horde:Graham Van Talen} in the Rogues' Quarter in Undercity"] = "Il n'y a pas de maître d'Ingénierie dans les clairières de Tirisfal, va voir {n:0:horde:Graham Van Talen} dans le quartier des Voleurs à Fossoyeuse",
  ["{n:0::Strange Hermit} in Shadowgale Forest"] = "{n:0::Strange Hermit} dans la forêt de Shadowgale",
  ["Stormwind City: {n:0:alliance:Sprite Jumpsprocket}"] = "Hurlevent : {n:0:alliance:Sprite Jumpsprocket}",
  ["Ironforge: {n:0:alliance:Jemma Quikswitch}"] = "Forgefer : {n:0:alliance:Jemma Quikswitch}",
  ["There is no Engineering trainer in Elwynn Forest, go to {n:0:alliance:Sprite Jumpsprocket} in the Dwarven District in Stormwind City"] = "Il n'y a pas de maître d'Ingénierie dans la forêt d'Elwynn, va voir {n:0:alliance:Sprite Jumpsprocket} dans le quartier des Nains à Hurlevent",
  ["{n:0:alliance:Bronk Guzzlegear} at Steelgrill's Depot"] = "{n:0:alliance:Bronk Guzzlegear} au dépôt de Steelgrill",
  ["There is no Engineering trainer in Teldrassil or Darnassus, the closest one is {n:0:alliance:Jenna Lemkenilli} in Auberdine in Darkshore"] = "Il n'y a pas de maître d'Ingénierie à Teldrassil ni à Darnassus, le plus proche est {n:0:alliance:Jenna Lemkenilli} à Auberdine, en Sombrivage",
  ["You can find every Engineering trainer for Horde and Alliance on my WoW Forever Engineering Trainers page."] = "Tu trouveras tous les maîtres d'Ingénierie de la Horde et de l'Alliance sur ma page WoW Forever Engineering Trainers.",
  ["Apprentice Engineering (1-50)"] = "Ingénierie (Apprenti) (1-50)",
  ["Buy a {i:5956:inv_hammer_20:Blacksmith Hammer}, most recipes need it. {b}Most trainers{/b} have a Blacksmithing or Engineering Supply vendor nearby that sells it, {b}except{/b} the trainers in Dun Morogh and on Zephras Isle. In Dun Morogh buy it in Kharanos from {n:0:alliance:Thrawn Boltar}, on Zephras Isle in Shen'dar Village from {n:0::Aedi Thriceforged}."] = "Achète un {i:5956:inv_hammer_20:Blacksmith Hammer}, la plupart des recettes en ont besoin. {b}La plupart des maîtres{/b} ont à proximité un marchand de fournitures de forge ou d'ingénierie qui le vend, {b}sauf{/b} les maîtres de Dun Morogh et de Zephras Isle. À Dun Morogh, achète-le à Kharanos auprès de {n:0:alliance:Thrawn Boltar}, sur Zephras Isle au village de Shen'dar auprès de {n:0::Aedi Thriceforged}.",
  ["The {b}Gnome{/b} racial changed in Forever. Instead of +15 Engineering skill, Engineering Specialization now makes your devices fail or backfire 20% less often, so Gnomes level Engineering exactly like everyone else."] = "Le trait racial des {b}Gnomes{/b} a changé dans Forever. Au lieu de +15 en compétence d'Ingénierie, Spécialisation en ingénierie fait désormais rater ou se retourner tes appareils 20 % moins souvent, donc les Gnomes montent l'Ingénierie exactement comme tout le monde.",
  ["66x {s:3918:inv_misc_dust_01:Rough Blasting Powder} - 66 Rough Stone"] = "66x {s:3918:inv_misc_dust_01:Rough Blasting Powder} - 66 Pierre brute",
  ["Keep all of them, you need 66 for the bombs at 51."] = "Garde-les toutes, il t'en faut 66 pour les bombes à 51.",
  ["33x {s:3922:inv_misc_gear_06:Handful of Copper Bolts} - 33 Copper Bar"] = "33x {s:3922:inv_misc_gear_06:Handful of Copper Bolts} - 33 Barre de cuivre",
  ["Keep these too, you will need all 33 for the bombs."] = "Garde-les aussi, il te les faudra tous les 33 pour les bombes.",
  ["1x {s:7430:inv_misc_wrench_01:Arclight Spanner} - 6 Copper Bar"] = "1x {s:7430:inv_misc_wrench_01:Arclight Spanner} - 6 Barre de cuivre",
  ["You will use this to craft Engineering recipes, so keep it."] = "Tu t'en serviras pour fabriquer des recettes d'Ingénierie, alors garde-la.",
  ["Journeyman Engineering (50-150)"] = "Ingénierie (Compagnon) (50-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Engineering. You need {b}Engineering 50{/b} and {b}level 10{/b}:"] = "Pour dépasser 75, va voir l'un de ces maîtres et apprends Ingénierie (Compagnon). Il te faut {b}Ingénierie 50{/b} et {b}niveau 10{/b} :",
  ["Orgrimmar: {n:0:horde:Nogg}"] = "Orgrimmar : {n:0:horde:Nogg}",
  ["Undercity: {n:0:horde:Franklin Lloyd}"] = "Fossoyeuse : {n:0:horde:Franklin Lloyd}",
  ["Stormwind City: {n:0:alliance:Lilliam Sparkspindle}"] = "Hurlevent : {n:0:alliance:Lilliam Sparkspindle}",
  ["Ironforge: {n:0:alliance:Trixie Quikswitch}"] = "Forgefer : {n:0:alliance:Trixie Quikswitch}",
  ["Duskwood: {n:0:alliance:Finbus Geargrind}"] = "Bois de la Pénombre : {n:0:alliance:Finbus Geargrind}",
  ["33x {s:3923:inv_misc_bomb_09:Rough Copper Bomb} - 33 Copper Bar, 33 Handful of Copper Bolts, 66 Rough Blasting Powder, 33 Linen Cloth"] = "33x {s:3923:inv_misc_bomb_09:Rough Copper Bomb} - 33 Barre de cuivre, 33 Handful of Copper Bolts, 66 Rough Blasting Powder, 33 Étoffe de lin",
  ["{b}It's possible that you reach further than 75 with these{/b}, so it's best not to afk craft them unless you already learned Journeyman Engineering. Either make sure you learn it first, or just don't afk craft them. (Depends on luck, sometimes you don't even reach 75.)"] = "{b}Il est possible que tu dépasses 75 avec celles-ci{/b}, il vaut donc mieux ne pas les fabriquer en AFK sauf si tu as déjà appris Ingénierie (Compagnon). Assure-toi de l'apprendre avant, ou ne les fabrique simplement pas en AFK. (Ça dépend de la chance, parfois tu n'atteins même pas 75.)",
  ["60x {s:3929:inv_misc_dust_02:Coarse Blasting Powder} - 60 Coarse Stone"] = "60x {s:3929:inv_misc_dust_02:Coarse Blasting Powder} - 60 Pierre grossière",
  ["Keep them, you will need all 60 for the dynamite at 90."] = "Garde-les, il te les faudra toutes les 60 pour la dynamite à 90.",
  ["20x {s:3931:inv_misc_bomb_06:Coarse Dynamite} - 60 Coarse Blasting Powder, 20 Linen Cloth"] = "20x {s:3931:inv_misc_bomb_06:Coarse Dynamite} - 60 Coarse Blasting Powder, 20 Étoffe de lin",
  ["5x {s:3973:inv_ingot_04:Silver Contact} - 5 Silver Bar"] = "5x {s:3973:inv_ingot_04:Silver Contact} - 5 Barre d'argent",
  ["If Silver Bar is expensive, make this instead:"] = "Si la barre d'argent est chère, fais plutôt ceci :",
  ["5x {s:3934:inv_helmet_47:Flying Tiger Goggles} - 30 Light Leather, 10 Tigerseye."] = "5x {s:3934:inv_helmet_47:Flying Tiger Goggles} - 30 Cuir léger, 10 Oeil de tigre.",
  ["25x {s:3938:inv_gizmo_pipe_01:Bronze Tube} - 50 Bronze Bar, 25 Weak Flux"] = "25x {s:3938:inv_gizmo_pipe_01:Bronze Tube} - 50 Barre de bronze, 25 Fondant faible",
  ["Keep 10 of them, you will need them at 125."] = "Garde-en 10, tu en auras besoin à 125.",
  ["{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} is sold by Engineering Supply vendors near your trainer."] = "{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} est vendu par les marchands de fournitures d'ingénierie près de ton maître.",
  ["If you end up a few points short of 125, don't make more tubes, just start the scopes."] = "S'il te manque quelques points pour atteindre 125, ne fais pas plus de tubes, commence simplement les lunettes de visée.",
  ["10x {s:3978:inv_misc_spyglass_02:Standard Scope} - 10 Bronze Tube, 10 Moss Agate"] = "10x {s:3978:inv_misc_spyglass_02:Standard Scope} - 10 Bronze Tube, 10 Agate mousse",
  ["Start making {s:3945:inv_misc_dust_06:Heavy Blasting Powder} instead if you don't have any Moss Agate, or it's really expensive."] = "Commence plutôt la {s:3945:inv_misc_dust_06:Heavy Blasting Powder} si tu n'as pas d'Agate mousse, ou si elle est vraiment chère.",
  ["Make both of these:"] = "Fais ces deux recettes :",
  ["30x {s:3945:inv_misc_dust_06:Heavy Blasting Powder} - 30 Heavy Stone"] = "30x {s:3945:inv_misc_dust_06:Heavy Blasting Powder} - 30 Pierre lourde",
  ["15x {s:3942:inv_gizmo_02:Whirring Bronze Gizmo} - 30 Bronze Bar, 15 Wool Cloth"] = "15x {s:3942:inv_gizmo_02:Whirring Bronze Gizmo} - 30 Barre de bronze, 15 Étoffe de laine",
  ["{b}Make sure to make them in the same order.{/b} You need both for the sheep at 160, so make them now and you should reach 150 with them."] = "{b}Veille à les faire dans le même ordre.{/b} Il te faut les deux pour les moutons à 160, alors fais-les maintenant et tu devrais atteindre 150 avec.",
  ["Expert Engineering (150-200)"] = "Ingénierie (Expert) (150-200)",
  ["To train past 150, visit {n:0:horde:Roxxik} in Orgrimmar (Horde) or {n:0:alliance:Springspindle Fizzlegear} in Ironforge (Alliance) and learn Expert Engineering. You need {b}Engineering 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Pour dépasser 150, va voir {n:0:horde:Roxxik} à Orgrimmar (Horde) ou {n:0:alliance:Springspindle Fizzlegear} à Forgefer (Alliance) et apprends Ingénierie (Expert). Il te faut {b}Ingénierie 125{/b} et {b}niveau 20{/b}, et ça coûte 50 pièces d'argent.",
  ["15x {s:3953:inv_gizmo_bronzeframework_01:Bronze Framework} - 30 Bronze Bar, 15 Medium Leather, 15 Wool Cloth"] = "15x {s:3953:inv_gizmo_bronzeframework_01:Bronze Framework} - 30 Barre de bronze, 15 Cuir moyen, 15 Étoffe de laine",
  ["Keep these too, you will need all 15 for the sheep."] = "Garde-les aussi, il te les faudra toutes les 15 pour les moutons.",
  ["The 15 will probably take you past 160, that's fine."] = "Les 15 te feront probablement dépasser 160, ce n'est pas grave.",
  ["15x {s:3955:spell_nature_polymorph:Explosive Sheep} - 30 Heavy Blasting Powder, 15 Whirring Bronze Gizmo, 15 Bronze Framework, 30 Wool Cloth"] = "15x {s:3955:spell_nature_polymorph:Explosive Sheep} - 30 Heavy Blasting Powder, 15 Whirring Bronze Gizmo, 15 Bronze Framework, 30 Étoffe de laine",
  ["Keep 5 of them, you might need them if you choose Goblin Engineering at 200."] = "Garde-en 5, tu pourrais en avoir besoin si tu choisis l'Ingénierie gobeline à 200.",
  ["60x {s:12585:inv_misc_powder_black:Solid Blasting Powder} - 120 Solid Stone"] = "60x {s:12585:inv_misc_powder_black:Solid Blasting Powder} - 120 Pierre solide",
  ["Save these, you will need them later."] = "Garde-les, tu en auras besoin plus tard.",
  ["1x {s:12590:inv_misc_screwdriver_02:Gyromatic Micro-Adjustor} - 4 Steel Bar"] = "1x {s:12590:inv_misc_screwdriver_02:Gyromatic Micro-Adjustor} - 4 Barre d'acier",
  ["Keep this, you will need it to craft some of the Engineering recipes."] = "Garde-le, tu en auras besoin pour fabriquer certaines recettes d'Ingénierie.",
  ["If you were unlucky with the skill points and didn't reach 195, craft a few {s:3962:inv_misc_bomb_08:Iron Grenade} or any other recipe that gives skill points."] = "Si tu n'as pas eu de chance avec les points de compétence et que tu n'as pas atteint 195, fabrique quelques {s:3962:inv_misc_bomb_08:Iron Grenade} ou n'importe quelle autre recette qui donne des points de compétence.",
  ["6x {s:12589:inv_musket_01:Mithril Tube} - 18 Mithril Bar"] = "6x {s:12589:inv_musket_01:Mithril Tube} - 18 Barre de mithril",
  ["Keep all 6, you might need them if you choose Gnomish Engineering at 200."] = "Garde les 6, tu pourrais en avoir besoin si tu choisis l'Ingénierie gnome à 200.",
  ["Engineering Specializations"] = "Spécialisations d'Ingénierie",
  ["At {b}Engineering 200{/b} and {b}level 30{/b}, you can specialize in Gnomish or Goblin Engineering. Some items require a specific specialization to use, while other items are crafted by one specialization but are usable by any engineer. Fortunately, most recipes that are crafted by one specialization can be used by both."] = "À {b}Ingénierie 200{/b} et {b}niveau 30{/b}, tu peux te spécialiser en Ingénierie gnome ou gobeline. Certains objets nécessitent une spécialisation précise pour être utilisés, tandis que d'autres sont fabriqués par une spécialisation mais utilisables par n'importe quel ingénieur. Heureusement, la plupart des recettes fabriquées par une spécialisation peuvent être utilisées par les deux.",
  ["For information on how to choose a specialization, please see my separate guide:"] = "Pour savoir comment choisir une spécialisation, consulte mon guide dédié :",
  ["Artisan Engineering (200-300)"] = "Ingénierie (Artisan) (200-300)",
  ["To train Engineering past 225 you need {b}Engineering 200{/b} and {b}level 35{/b}, then learn Artisan Engineering from {n:0::Buzzek Bracketswing} in Tanaris at Gadgetzan, he is right outside the inn near the mailbox. He also teaches the recipes above 200, so go there as soon as you reach 200."] = "Pour dépasser 225, il te faut {b}Ingénierie 200{/b} et {b}niveau 35{/b}, puis apprends Ingénierie (Artisan) auprès de {n:0::Buzzek Bracketswing} à Gadgetzan, en Tanaris : il se trouve juste devant l'auberge, près de la boîte aux lettres. Il enseigne aussi les recettes au-delà de 200, alors vas-y dès que tu atteins 200.",
  ["20x {s:12591:inv_battery_01:Unstable Trigger} - 20 Mithril Bar, 20 Mageweave Cloth, 20 Solid Blasting Powder"] = "20x {s:12591:inv_battery_01:Unstable Trigger} - 20 Barre de mithril, 20 Tisse-mage, 20 Solid Blasting Powder",
  ["Keep them, you will need all 20 for the bombs at 238."] = "Garde-les, il te les faudra tous les 20 pour les bombes à 238.",
  ["40x {s:12599:inv_gizmo_mithrilcasing_01:Mithril Casing} - 120 Mithril Bar"] = "40x {s:12599:inv_gizmo_mithrilcasing_01:Mithril Casing} - 120 Barre de mithril",
  ["Keep these too, you will need 40 for the bombs."] = "Garde-les aussi, il t'en faudra 40 pour les bombes.",
  ["44x {s:19788:inv_misc_ammo_gunpowder_01:Dense Blasting Powder} - 88 Dense Stone"] = "44x {s:19788:inv_misc_ammo_gunpowder_01:Dense Blasting Powder} - 88 Pierre dense",
  ["35x {s:19791:inv_gizmo_04:Thorium Widget} - 105 Thorium Bar, 35 Runecloth"] = "35x {s:19791:inv_gizmo_04:Thorium Widget} - 105 Barre de thorium, 35 Étoffe runique",
  ["{i:16042:inv_scroll_03:Schematic: Thorium Widget} is sold by {n:0:horde:Sovik} in Orgrimmar and {n:0:alliance:Gearcutter Cogspinner} in Ironforge."] = "{i:16042:inv_scroll_03:Schematic: Thorium Widget} est vendu par {n:0:horde:Sovik} à Orgrimmar et {n:0:alliance:Gearcutter Cogspinner} à Forgefer.",
  ["20x {s:19795:inv_gizmo_pipe_04:Thorium Tube} - 120 Thorium Bar"] = "20x {s:19795:inv_gizmo_pipe_04:Thorium Tube} - 120 Barre de thorium",
  ["{i:16047:inv_scroll_03:Schematic: Thorium Tube} is sold by {n:0::Xizzer Fizzbolt} in Winterspring at Everlook, in the first building on the right after the gate. It's bind on pickup in Forever, so buy it with the character that levels Engineering."] = "{i:16047:inv_scroll_03:Schematic: Thorium Tube} est vendu par {n:0::Xizzer Fizzbolt} à Long-Guet, dans le Berceau-de-l'Hiver, dans le premier bâtiment à droite après la porte. Il est lié quand ramassé dans Forever, alors achète-le avec le personnage qui monte l'Ingénierie.",
  ["This WoW Forever Leatherworking leveling guide will show you the fastest and cheapest way to level your Leatherworking skill from 1 to 300. You will also find every trainer location and where to train Leatherworking past 75, 150 and 225."] = "Ce guide de montée en Travail du cuir pour WoW Forever te montre la façon la plus rapide et la moins chère de monter ta compétence de Travail du cuir de 1 à 300. Tu y trouveras aussi l'emplacement de chaque maître et où apprendre le Travail du cuir au-delà de 75, 150 et 225.",
  ["Below you will find the full shopping list, the Leatherworking trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Leatherworking is best combined with Skinning because leather is most of the cost, but you can also buy everything in the guide from the Auction House."] = "Tu trouveras ci-dessous la liste de courses complète, les maîtres du Travail du cuir par zone de départ et capitale, et les recettes les moins chères pour chaque palier de compétence, d'Apprenti à Artisan. Le Travail du cuir se marie le mieux avec le Dépeçage car le cuir représente l'essentiel du coût, mais tu peux aussi acheter tout ce qui est dans le guide à l'hôtel des ventes.",
  ["When a recipe is yellow or green, a craft doesn't always give you a skill point, so nobody can tell exactly how many materials you will need. That's why the counts that depend a lot on luck are a range. {b}With the bigger number 9 out of 10 players have enough, with the smaller one it's 50/50.{/b} If you buy the smaller number, be ready to buy more later."] = "Quand une recette est jaune ou verte, une fabrication ne te donne pas toujours un point de compétence, donc personne ne peut dire exactement combien de matériaux il te faudra. C'est pourquoi les quantités qui dépendent beaucoup de la chance sont données sous forme de fourchette. {b}Avec le plus grand nombre, 9 joueurs sur 10 en ont assez, avec le plus petit, c'est du 50/50.{/b} Si tu achètes le plus petit nombre, prépare-toi à en racheter plus tard.",
  ["Material"] = "Matériau",
  ["Leatherworking Trainer Locations"] = "Emplacements des maîtres du Travail du cuir",
  ["Apprentice Leatherworking has no level requirement in Forever, so you can learn it on a fresh character."] = "Le Travail du cuir (Apprenti) n'a aucun niveau requis dans Forever, tu peux donc l'apprendre sur un personnage tout neuf.",
  ["Orgrimmar: {n:0:horde:Kamari}"] = "Orgrimmar : {n:0:horde:Kamari}",
  ["Undercity: {n:0:horde:Dan Golthas}"] = "Fossoyeuse : {n:0:horde:Dan Golthas}",
  ["Thunder Bluff: {n:0:horde:Mak}"] = "Les Pitons-du-Tonnerre : {n:0:horde:Mak}",
  ["There is no Leatherworking trainer in Durotar, go to {n:0:horde:Kamari} in the Drag in Orgrimmar"] = "Il n'y a pas de maître du Travail du cuir à Durotar, va voir {n:0:horde:Kamari} dans la Herse à Orgrimmar",
  ["{n:0:horde:Chaw Stronghide} in Bloodhoof Village"] = "{n:0:horde:Chaw Stronghide} au village de Sabot-de-Sang",
  ["{n:0:horde:Shelene Rhobart} at the road junction southeast of Brill"] = "{n:0:horde:Shelene Rhobart} au carrefour au sud-est de Brill",
  ["{n:0::Emerii Tallgust} in Valanaar, {n:0::Indari Sunseam} in Shen'dar Village"] = "{n:0::Emerii Tallgust} à Valanaar, {n:0::Indari Sunseam} au village de Shen'dar",
  ["Stormwind City: {n:0:alliance:Randal Worth}"] = "Hurlevent : {n:0:alliance:Randal Worth}",
  ["Ironforge: {n:0:alliance:Gretta Finespindle}"] = "Forgefer : {n:0:alliance:Gretta Finespindle}",
  ["Darnassus: {n:0:alliance:Darianna}"] = "Darnassus : {n:0:alliance:Darianna}",
  ["{n:0:alliance:Adele Fielder} in the small house by Crystal Lake, northeast of Goldshire"] = "{n:0:alliance:Adele Fielder} dans la petite maison près du lac de Cristal, au nord-est de Comté-de-l'Or",
  ["There is no Leatherworking trainer in Dun Morogh, go to {n:0:alliance:Gretta Finespindle} at the Great Forge in Ironforge"] = "Il n'y a pas de maître du Travail du cuir à Dun Morogh, va voir {n:0:alliance:Gretta Finespindle} à la Grande Forge de Forgefer",
  ["{n:0:alliance:Nadyia Maneweaver} in the small house near the road to Darnassus"] = "{n:0:alliance:Nadyia Maneweaver} dans la petite maison près de la route de Darnassus",
  ["You can find every Leatherworking trainer for Horde and Alliance on my WoW Forever Leatherworking Trainers page."] = "Tu trouveras tous les maîtres du Travail du cuir de la Horde et de l'Alliance sur ma page WoW Forever Leatherworking Trainers.",
  ["Apprentice Leatherworking (1-55)"] = "Travail du cuir (Apprenti) (1-55)",
  ["35x {s:2881:inv_misc_leatherscrap_03:Light Leather} - 105 Ruined Leather Scraps"] = "35x {s:2881:inv_misc_leatherscrap_03:Light Leather} - 105 Morceaux de cuir abîmés",
  ["27x {s:3816:inv_misc_pelt_wolf_01:Cured Light Hide} - 27 Light Hide, 27 Salt"] = "27x {s:3816:inv_misc_pelt_wolf_01:Cured Light Hide} - 27 Peau légère, 27 Sel",
  ["{b}NOTE:{/b} {b}Most trainers{/b} have a Leatherworking Supply vendor nearby that sells the threads, dyes, and salt, {b}except{/b} the trainers in Elwynn Forest and Tirisfal Glades. For those, buy the Salt and Coarse Thread in Goldshire from {n:0:alliance:Tharynn Bouden} or in Brill from {n:0:horde:Abigail Shiel}."] = "{b}REMARQUE :{/b} {b}la plupart des maîtres{/b} ont à proximité un marchand de fournitures du travail du cuir qui vend les fils, les teintures et le sel, {b}sauf{/b} les maîtres de la forêt d'Elwynn et des clairières de Tirisfal. Pour ceux-là, achète le sel et le fil grossier à Comté-de-l'Or auprès de {n:0:alliance:Tharynn Bouden} ou à Brill auprès de {n:0:horde:Abigail Shiel}.",
  ["Keep 24 of the hides, you will need them for the Light Leather Pants at 100."] = "Garde 24 des peaux, tu en auras besoin pour les Light Leather Pants à 100.",
  ["Alternative recipes"] = "Recettes alternatives",
  ["If you farm your own leather and don't have 27 Light Hides, make Light Armor Kits until 45, then Embossed Leather Gloves until 55:"] = "Si tu récoltes ton propre cuir et que tu n'as pas 27 Peau légère, fais des Light Armor Kit jusqu'à 45, puis des Embossed Leather Gloves jusqu'à 55 :",
  ["24x {s:2152:inv_misc_armorkit_17:Light Armor Kit} - 24 Light Leather"] = "24x {s:2152:inv_misc_armorkit_17:Light Armor Kit} - 24 Cuir léger",
  ["10x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 30 Light Leather, 20 Coarse Thread"] = "10x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 30 Cuir léger, 20 Fil grossier",
  ["You still need 24 Cured Light Hide for the Light Leather Pants at 100, so keep the Light Hides you skin until then."] = "Il te faut quand même 24 Cured Light Hide pour les Light Leather Pants à 100, alors garde jusque-là les peaux légères que tu dépèces.",
  ["Journeyman Leatherworking (55-130)"] = "Travail du cuir (Compagnon) (55-130)",
  ["To train past 75, visit one of these trainers and learn Journeyman Leatherworking. You need {b}Leatherworking 50{/b} and {b}level 10{/b}:"] = "Pour dépasser 75, va voir l'un de ces maîtres et apprends Travail du cuir (Compagnon). Il te faut {b}Travail du cuir 50{/b} et {b}niveau 10{/b} :",
  ["Orgrimmar: {n:0:horde:Karolek}"] = "Orgrimmar : {n:0:horde:Karolek}",
  ["Undercity: {n:0:horde:Arthur Moore}"] = "Fossoyeuse : {n:0:horde:Arthur Moore}",
  ["Thunder Bluff: {n:0:horde:Tarn}"] = "Les Pitons-du-Tonnerre : {n:0:horde:Tarn}",
  ["Stormwind City: {n:0:alliance:Simon Tanner}"] = "Hurlevent : {n:0:alliance:Simon Tanner}",
  ["Ironforge: {n:0:alliance:Fimble Finespindle}"] = "Forgefer : {n:0:alliance:Fimble Finespindle}",
  ["Darnassus: {n:0:alliance:Faldron}"] = "Darnassus : {n:0:alliance:Faldron}",
  ["21x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 63 Light Leather, 42 Coarse Thread"] = "21x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 63 Cuir léger, 42 Fil grossier",
  ["8x {s:20648:inv_misc_leatherscrap_05:Medium Leather} - 32 Light Leather"] = "8x {s:20648:inv_misc_leatherscrap_05:Medium Leather} - 32 Cuir léger",
  ["10x {s:3817:inv_misc_pelt_bear_02:Cured Medium Hide} - 10 Medium Hide, 10 Salt"] = "10x {s:3817:inv_misc_pelt_bear_02:Cured Medium Hide} - 10 Peau moyenne, 10 Sel",
  ["Keep the Cured Medium Hides, you will need them for the Dark Leather Belts at 115."] = "Garde les Cured Medium Hide, tu en auras besoin pour les Dark Leather Belt à 115.",
  ["19x {s:3763:inv_belt_04:Fine Leather Belt} - 114 Light Leather, 38 Coarse Thread"] = "19x {s:3763:inv_belt_04:Fine Leather Belt} - 114 Cuir léger, 38 Fil grossier",
  ["Keep 10 of the belts for the Dark Leather Belts at 115."] = "Garde 10 ceintures pour les Dark Leather Belt à 115.",
  ["24x {s:9068:inv_pants_02:Light Leather Pants} - 240 Light Leather, 24 Cured Light Hide, 24 Fine Thread"] = "24x {s:9068:inv_pants_02:Light Leather Pants} - 240 Cuir léger, 24 Cured Light Hide, 24 Fil fin",
  ["10x {s:3766:inv_belt_03:Dark Leather Belt} - 10 Fine Leather Belt, 10 Cured Medium Hide, 20 Fine Thread, 10 Gray Dye"] = "10x {s:3766:inv_belt_03:Dark Leather Belt} - 10 Fine Leather Belt, 10 Cured Medium Hide, 20 Fil fin, 10 Teinture grise",
  ["7x {s:20649:inv_misc_leatherscrap_07:Heavy Leather} - 35 Medium Leather"] = "7x {s:20649:inv_misc_leatherscrap_07:Heavy Leather} - 35 Cuir moyen",
  ["Expert Leatherworking (130-205)"] = "Travail du cuir (Expert) (130-205)",
  ["To train past 150, visit {n:0:horde:Una} in Thunder Bluff (Horde) or {n:0:alliance:Telonis} in Darnassus (Alliance) and learn Expert Leatherworking. You need {b}Leatherworking 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Pour dépasser 150, va voir {n:0:horde:Una} aux Pitons-du-Tonnerre (Horde) ou {n:0:alliance:Telonis} à Darnassus (Alliance) et apprends Travail du cuir (Expert). Il te faut {b}Travail du cuir 125{/b} et {b}niveau 20{/b}, et ça coûte 50 pièces d'argent.",
  ["30x {s:3818:inv_misc_pelt_wolf_02:Cured Heavy Hide} - 30 Heavy Hide, 90 Salt"] = "30x {s:3818:inv_misc_pelt_wolf_02:Cured Heavy Hide} - 30 Peau lourde, 90 Sel",
  ["Keep the Cured Heavy Hides, you will need 10 for the Barbaric Shoulders at 155 and 20 for the Guardian Gloves at 165."] = "Garde les Cured Heavy Hide, il t'en faudra 10 pour les Barbaric Shoulders à 155 et 20 pour les Guardian Gloves à 165.",
  ["17x {s:3764:inv_gauntlets_05:Hillman's Leather Gloves} - 238 Medium Leather, 68 Fine Thread"] = "17x {s:3764:inv_gauntlets_05:Hillman's Leather Gloves} - 238 Cuir moyen, 68 Fil fin",
  ["10x {s:7151:inv_shoulder_08:Barbaric Shoulders} - 80 Heavy Leather, 10 Cured Heavy Hide, 20 Fine Thread"] = "10x {s:7151:inv_shoulder_08:Barbaric Shoulders} - 80 Cuir lourd, 10 Cured Heavy Hide, 20 Fil fin",
  ["20x {s:7156:inv_gauntlets_05:Guardian Gloves} - 80 Heavy Leather, 20 Cured Heavy Hide, 20 Silken Thread"] = "20x {s:7156:inv_gauntlets_05:Guardian Gloves} - 80 Cuir lourd, 20 Cured Heavy Hide, 20 Fil de soie",
  ["22x {s:10507:inv_belt_24:Nightscape Headband} - 110 Thick Leather, 44 Silken Thread"] = "22x {s:10507:inv_belt_24:Nightscape Headband} - 110 Cuir épais, 44 Fil de soie",
  ["Leatherworking Specializations"] = "Spécialisations du Travail du cuir",
  ["Once you reach {b}Leatherworking 225{/b} and {b}level 40{/b}, you can choose one of the three Leatherworking specializations: Dragonscale, Elemental, or Tribal. Each specialization gives access to a specific set of patterns."] = "Une fois à {b}Travail du cuir 225{/b} et {b}niveau 40{/b}, tu peux choisir l'une des trois spécialisations du Travail du cuir : Travail du cuir d'écailles de dragon, élémentaire ou tribal. Chaque spécialisation donne accès à un ensemble précis de patrons.",
  ["Dragonscale - Mail-type gear"] = "Écailles de dragon - équipement en mailles",
  ["Elemental - elemental resistance and Leather-type agility gear"] = "Élémentaire - équipement de résistance élémentaire et équipement en cuir d'agilité",
  ["Tribal - Leather-type intellect & agility gear and the Devilsaur Armor set"] = "Tribal - équipement en cuir d'intelligence et d'agilité, et l'ensemble Devilsaur Armor",
  ["For information on how to become a Dragonscale, Elemental, or Tribal Leatherworker, please see my separate guides:"] = "Pour savoir comment te spécialiser en Travail du cuir d'écailles de dragon, élémentaire ou tribal, consulte mes guides dédiés :",
  ["Artisan Leatherworking (205-300)"] = "Travail du cuir (Artisan) (205-300)",
  ["To train past 225, visit {n:0:horde:Hahrana Ironhide} in Camp Mojache, Feralas (Horde) or {n:0:alliance:Drakk Stonehand} in Aerie Peak, The Hinterlands (Alliance) and learn Artisan Leatherworking. You need {b}Leatherworking 200{/b} and {b}level 35{/b}."] = "Pour dépasser 225, va voir {n:0:horde:Hahrana Ironhide} au camp Mojache, à Féralas (Horde) ou {n:0:alliance:Drakk Stonehand} au Nid-de-l'Aigle, dans les Hinterlands (Alliance) et apprends Travail du cuir (Artisan). Il te faut {b}Travail du cuir 200{/b} et {b}niveau 35{/b}.",
  ["36x {s:10548:inv_pants_11:Nightscape Pants} - 504 Thick Leather, 144 Silken Thread"] = "36x {s:10548:inv_pants_11:Nightscape Pants} - 504 Cuir épais, 144 Fil de soie",
  ["{b}The Expert trainers in Thunder Bluff and Darnassus don't teach this recipe{/b}, you can only learn it from the two trainers above."] = "{b}Les maîtres Expert des Pitons-du-Tonnerre et de Darnassus n'enseignent pas cette recette{/b}, tu ne peux l'apprendre qu'auprès des deux maîtres ci-dessus.",
  ["I recommend these over the Nightscape Boots because they sell for more to a vendor, so they end up cheaper."] = "Je te les conseille plutôt que les Nightscape Boots car ils se revendent plus cher à un marchand, donc ils reviennent moins cher.",
  ["36x {s:19049:inv_gauntlets_31:Wicked Leather Gauntlets} - 288 Rugged Leather, 36 Black Dye, 36 Rune Thread"] = "36x {s:19049:inv_gauntlets_31:Wicked Leather Gauntlets} - 288 Cuir robuste, 36 Teinture noire, 36 Fil runique",
  ["The pattern is sold by {n:0:horde:Werg Thickblade} in Tirisfal Glades (Horde) and {n:0:alliance:Leonard Porter} in Western Plaguelands (Alliance)."] = "Le patron est vendu par {n:0:horde:Werg Thickblade} dans les clairières de Tirisfal (Horde) et {n:0:alliance:Leonard Porter} dans les Maleterres de l'Ouest (Alliance).",
  ["Blue Suede Shoes use the same leather but sell for more to a vendor, so they save you about 13 gold on this step. If the pattern costs less than that on the Auction House, make these instead:"] = "Les Blue Suede Shoes utilisent le même cuir mais se revendent plus cher à un marchand, elles te font donc économiser environ 13 pièces d'or sur cette étape. Si le patron coûte moins que ça à l'hôtel des ventes, fais plutôt celles-ci :",
  ["36x {s:1255048:inv_boots_leather_12:Blue Suede Shoes} - 288 Rugged Leather, 36 Blue Dye, 36 Rune Thread."] = "36x {s:1255048:inv_boots_leather_12:Blue Suede Shoes} - 288 Cuir robuste, 36 Teinture bleue, 36 Fil runique.",
  ["53x {s:19082:inv_misc_bandage_11:Runic Leather Headband} - 742 Rugged Leather, 530 Runecloth, 53 Rune Thread"] = "53x {s:19082:inv_misc_bandage_11:Runic Leather Headband} - 742 Cuir robuste, 530 Étoffe runique, 53 Fil runique",
  ["The pattern is sold by {n:0::Jase Farlane} at Light's Hope Chapel in Eastern Plaguelands."] = "Le patron est vendu par {n:0::Jase Farlane} à la chapelle de l'Espoir de Lumière, dans les Maleterres de l'Est.",
  ["If you have the pattern, make these from 275 instead:"] = "Si tu as le patron, fais plutôt ceux-ci à partir de 275 :",
  ["27x {s:1255019:inv_bracer_22a:Blue Suede Bracers} - 270 Rugged Leather, 27 Blue Dye, 27 Rune Thread."] = "27x {s:1255019:inv_bracer_22a:Blue Suede Bracers} - 270 Cuir robuste, 27 Teinture bleue, 27 Fil runique.",
  ["{b}Someone with Leatherworking 300 has to place the Sewing Machine for you.{/b} You can't place a Sewing Machine yourself before 300, even if you buy one. I'm not sure if this is an oversight by Blizzard, so they might change it."] = "{b}Quelqu'un avec Travail du cuir 300 doit poser la machine à coudre pour toi.{/b} Tu ne peux pas poser de machine à coudre toi-même avant 300, même si tu en achètes une. Je ne sais pas si c'est un oubli de Blizzard, ça pourrait donc changer.",
  ["If you can use one and have the pattern, you can make these from 280:"] = "Si tu peux en utiliser une et que tu as le patron, tu peux faire ceux-ci à partir de 280 :",
  ["20x {s:1255017:inv_helm_armor_buckledhat_b_01_blue:Blue Suede Hat} - 320 Rugged Leather, 80 Blue Dye, 20 Rune Thread."] = "20x {s:1255017:inv_helm_armor_buckledhat_b_01_blue:Blue Suede Hat} - 320 Cuir robuste, 80 Teinture bleue, 20 Fil runique.",
  ["This WoW Forever Tailoring leveling guide will show you the fastest and cheapest way to level your Tailoring skill from 1 to 300. You will also find every trainer location and where to train Tailoring past 75, 150 and 225."] = "Ce guide de montée en Couture pour WoW Forever te montre la façon la plus rapide et la moins chère de monter ta compétence de Couture de 1 à 300. Tu y trouveras aussi l'emplacement de chaque maître et où apprendre la Couture au-delà de 75, 150 et 225.",
  ["Below you will find the full shopping list, the Tailoring trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Tailoring uses cloth as its main material, but cloth drops from humanoids, so you don't need a gathering profession and you can combine Tailoring with anything. Enchanting is a popular choice because you can disenchant the things you make while leveling and use the dust to level Enchanting."] = "Tu trouveras ci-dessous la liste de courses complète, les maîtres de Couture par zone de départ et capitale, et les recettes les moins chères pour chaque palier de compétence, d'Apprenti à Artisan. La Couture utilise l'étoffe comme matériau principal, et l'étoffe est lâchée par les humanoïdes : tu n'as donc pas besoin de métier de récolte et tu peux combiner la Couture avec n'importe quoi. L'Enchantement est un choix populaire car tu peux désenchanter ce que tu fabriques en montant et utiliser la poussière pour monter l'Enchantement.",
  ["{b}NOTE:{/b} {b}Most trainers{/b} have a Tailoring Supply vendor nearby that sells the threads and dyes, {b}except{/b} the trainer in Tirisfal Glades. For that one, buy the Coarse Thread in Brill from {n:0:horde:Abigail Shiel}."] = "{b}REMARQUE :{/b} {b}la plupart des maîtres{/b} ont à proximité un marchand de fournitures de couture qui vend les fils et les teintures, {b}sauf{/b} le maître des clairières de Tirisfal. Pour celui-là, achète le fil grossier à Brill auprès de {n:0:horde:Abigail Shiel}.",
  ["Alternative (if cheaper)"] = "Alternative (si moins chère)",
  ["This list is not final yet, but the skill ranges come from the game data, so it should be pretty close. The 280-300 part is not included here yet."] = "Cette liste n'est pas encore définitive, mais les paliers de compétence viennent des données du jeu, elle devrait donc être assez juste. La partie 280-300 n'est pas encore incluse ici.",
  ["Tailoring Trainer Locations"] = "Emplacements des maîtres de Couture",
  ["Apprentice Tailoring has no level requirement in Forever, so you can learn it on a fresh character."] = "La Couture (Apprenti) n'a aucun niveau requis dans Forever, tu peux donc l'apprendre sur un personnage tout neuf.",
  ["Orgrimmar: {n:0:horde:Snang}"] = "Orgrimmar : {n:0:horde:Snang}",
  ["Undercity: {n:0:horde:Victor Ward}"] = "Fossoyeuse : {n:0:horde:Victor Ward}",
  ["Thunder Bluff: {n:0:horde:Vhan}"] = "Les Pitons-du-Tonnerre : {n:0:horde:Vhan}",
  ["There is no Tailoring trainer in Durotar, go to {n:0:horde:Snang} in the Drag in Orgrimmar"] = "Il n'y a pas de maître de Couture à Durotar, va voir {n:0:horde:Snang} dans la Herse à Orgrimmar",
  ["There is no Tailoring trainer in Mulgore, go to {n:0:horde:Vhan} on the middle rise in Thunder Bluff"] = "Il n'y a pas de maître de Couture en Mulgore, va voir {n:0:horde:Vhan} sur le pic central des Pitons-du-Tonnerre",
  ["{n:0:horde:Bowen Brisboise} in the small house at Cold Hearth Manor, southwest of Brill"] = "{n:0:horde:Bowen Brisboise} dans la petite maison du manoir de Cold Hearth, au sud-ouest de Brill",
  ["{n:0::Othesia Evengale} in Valanaar, {n:0::Taleen Shimmerthread} in Shen'dar Village"] = "{n:0::Othesia Evengale} à Valanaar, {n:0::Taleen Shimmerthread} au village de Shen'dar",
  ["Stormwind City: {n:0:alliance:Lawrence Schneider}"] = "Hurlevent : {n:0:alliance:Lawrence Schneider}",
  ["Ironforge: {n:0:alliance:Uthrar Threx}"] = "Forgefer : {n:0:alliance:Uthrar Threx}",
  ["Darnassus: {n:0:alliance:Trianna}"] = "Darnassus : {n:0:alliance:Trianna}",
  ["{n:0:alliance:Eldrin} in a house at the Eastvale Logging Camp"] = "{n:0:alliance:Eldrin} dans une maison du camp de bûcherons du Val d'Est",
  ["There is no Tailoring trainer in Dun Morogh, go to {n:0:alliance:Uthrar Threx} at the Great Forge in Ironforge"] = "Il n'y a pas de maître de Couture à Dun Morogh, va voir {n:0:alliance:Uthrar Threx} à la Grande Forge de Forgefer",
  ["There is no Tailoring trainer in Teldrassil, go to {n:0:alliance:Trianna} at the Craftsmen's Terrace in Darnassus"] = "Il n'y a pas de maître de Couture à Teldrassil, va voir {n:0:alliance:Trianna} à la terrasse des Artisans à Darnassus",
  ["You can find every Tailoring trainer for Horde and Alliance on my WoW Forever Tailoring Trainers page."] = "Tu trouveras tous les maîtres de Couture de la Horde et de l'Alliance sur ma page WoW Forever Tailoring Trainers.",
  ["Apprentice Tailoring (1-55)"] = "Couture (Apprenti) (1-55)",
  ["30x {s:2963:inv_fabric_linen_02:Bolt of Linen Cloth} - 60 Linen Cloth"] = "30x {s:2963:inv_fabric_linen_02:Bolt of Linen Cloth} - 60 Étoffe de lin",
  ["Keep the bolts, you need all of them for the belts."] = "Garde les rouleaux, il te les faut tous pour les ceintures.",
  ["28x {s:8776:inv_belt_05:Linen Belt} - 28 Bolt of Linen Cloth, 28 Coarse Thread"] = "28x {s:8776:inv_belt_05:Linen Belt} - 28 Rouleau d'étoffe de lin, 28 Fil grossier",
  ["Journeyman Tailoring (55-140)"] = "Couture (Compagnon) (55-140)",
  ["To train past 75, visit one of these trainers and learn Journeyman Tailoring. You need {b}Tailoring 50{/b} and {b}level 10{/b}:"] = "Pour dépasser 75, va voir l'un de ces maîtres et apprends Couture (Compagnon). Il te faut {b}Couture 50{/b} et {b}niveau 10{/b} :",
  ["Orgrimmar: {n:0:horde:Magar}"] = "Orgrimmar : {n:0:horde:Magar}",
  ["Undercity: {n:0:horde:Rhiannon Davis}"] = "Fossoyeuse : {n:0:horde:Rhiannon Davis}",
  ["Thunder Bluff: {n:0:horde:Tepa}"] = "Les Pitons-du-Tonnerre : {n:0:horde:Tepa}",
  ["Stormwind City: {n:0:alliance:Sellandus}"] = "Hurlevent : {n:0:alliance:Sellandus}",
  ["Ironforge: {n:0:alliance:Jormund Stonebrow}"] = "Forgefer : {n:0:alliance:Jormund Stonebrow}",
  ["Darnassus: {n:0:alliance:Me'lynn}"] = "Darnassus : {n:0:alliance:Me'lynn}",
  ["{b}Learn Journeyman Tailoring before you make these.{/b} You can reach past 75 with them, but you won't get any skill points above 75 until you learn it, so don't go AFK while crafting before you have it."] = "{b}Apprends Couture (Compagnon) avant de fabriquer ceux-ci.{/b} Tu peux dépasser 75 avec, mais tu ne gagneras aucun point de compétence au-delà de 75 tant que tu ne l'as pas appris, alors ne pars pas en AFK pendant la fabrication avant de l'avoir.",
  ["45x {s:2964:inv_fabric_wool_03:Bolt of Woolen Cloth} - 135 Wool Cloth"] = "45x {s:2964:inv_fabric_wool_03:Bolt of Woolen Cloth} - 135 Étoffe de laine",
  ["Keep the bolts, you will need them later. In total you will need 153 {i:2997:inv_fabric_wool_03:Bolt of Woolen Cloth} (459 {i:2592:inv_fabric_wool_01:Wool Cloth}) until 140, so you can also make all of them now."] = "Garde les rouleaux, tu en auras besoin plus tard. Au total, il te faudra 153 {i:2997:inv_fabric_wool_03:Bolt of Woolen Cloth} (459 {i:2592:inv_fabric_wool_01:Wool Cloth}) jusqu'à 140, tu peux donc aussi tous les faire maintenant.",
  ["22x {s:2402:inv_misc_cape_10:Woolen Cape} - 22 Bolt of Woolen Cloth, 22 Fine Thread"] = "22x {s:2402:inv_misc_cape_10:Woolen Cape} - 22 Rouleau d'étoffe de laine, 22 Fil fin",
  ["If the bolts already took you past 80, just make capes until 95."] = "Si les rouleaux t'ont déjà fait dépasser 80, fais simplement des capes jusqu'à 95.",
  ["5x {s:3848:inv_shoulder_06:Double-stitched Woolen Shoulders} - 15 Bolt of Woolen Cloth, 10 Fine Thread"] = "5x {s:3848:inv_shoulder_06:Double-stitched Woolen Shoulders} - 15 Rouleau d'étoffe de laine, 10 Fil fin",
  ["54x {s:3839:inv_fabric_silk_03:Bolt of Silk Cloth} - 216 Silk Cloth"] = "54x {s:3839:inv_fabric_silk_03:Bolt of Silk Cloth} - 216 Étoffe de soie",
  ["Keep the bolts, you will need them later. In total you will need 184 {i:4305:inv_fabric_silk_03:Bolt of Silk Cloth} (736 {i:4306:inv_fabric_silk_01:Silk Cloth}) until 190, so you can also make all of them now."] = "Garde les rouleaux, tu en auras besoin plus tard. Au total, il te faudra 184 {i:4305:inv_fabric_silk_03:Bolt of Silk Cloth} (736 {i:4306:inv_fabric_silk_01:Silk Cloth}) jusqu'à 190, tu peux donc aussi tous les faire maintenant.",
  ["29x {s:3852:inv_gauntlets_05:Gloves of Meditation} - 116 Bolt of Woolen Cloth, 87 Fine Thread, 29 Elixir of Wisdom"] = "29x {s:3852:inv_gauntlets_05:Gloves of Meditation} - 116 Rouleau d'étoffe de laine, 87 Fil fin, 29 Elixir of Wisdom",
  ["You can buy {i:3383:inv_potion_06:Elixir of Wisdom} from the Auction House or ask an Alchemist."] = "Tu peux acheter l'{i:3383:inv_potion_06:Elixir of Wisdom} à l'hôtel des ventes ou le demander à un alchimiste.",
  ["Expert Tailoring (140-200)"] = "Couture (Expert) (140-200)",
  ["To train past 150, visit {n:0:horde:Josef Gregorian} in Undercity (Horde) or {n:0:alliance:Georgio Bolero} in Stormwind City (Alliance) and learn Expert Tailoring. You need {b}Tailoring 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Pour dépasser 150, va voir {n:0:horde:Josef Gregorian} à Fossoyeuse (Horde) ou {n:0:alliance:Georgio Bolero} à Hurlevent (Alliance) et apprends Couture (Expert). Il te faut {b}Couture 125{/b} et {b}niveau 20{/b}, et ça coûte 50 pièces d'argent.",
  ["23x {s:3865:inv_fabric_mageweave_03:Bolt of Mageweave} - 115 Mageweave Cloth"] = "23x {s:3865:inv_fabric_mageweave_03:Bolt of Mageweave} - 115 Tisse-mage",
  ["Keep the bolts, you will need them later. In total you will need 157 {i:4339:inv_fabric_mageweave_03:Bolt of Mageweave} (785 {i:4338:inv_fabric_mageweave_01:Mageweave Cloth}) until 225, so you can also make all of them now."] = "Garde les rouleaux, tu en auras besoin plus tard. Au total, il te faudra 157 {i:4339:inv_fabric_mageweave_03:Bolt of Mageweave} (785 {i:4338:inv_fabric_mageweave_01:Mageweave Cloth}) jusqu'à 225, tu peux donc aussi tous les faire maintenant.",
  ["20x {s:8791:inv_shirt_04:Crimson Silk Vest} - 80 Bolt of Silk Cloth, 40 Red Dye, 40 Fine Thread"] = "20x {s:8791:inv_shirt_04:Crimson Silk Vest} - 80 Rouleau d'étoffe de soie, 40 Teinture rouge, 40 Fil fin",
  ["26x {s:8799:inv_pants_06:Crimson Silk Pantaloons} - 104 Bolt of Silk Cloth, 52 Red Dye, 52 Silken Thread"] = "26x {s:8799:inv_pants_06:Crimson Silk Pantaloons} - 104 Rouleau d'étoffe de soie, 52 Teinture rouge, 52 Fil de soie",
  ["19x {s:12049:inv_pants_09:Black Mageweave Leggings} - 38 Bolt of Mageweave, 57 Silken Thread"] = "19x {s:12049:inv_pants_09:Black Mageweave Leggings} - 38 Rouleau de tisse-mage, 57 Fil de soie",
  ["Artisan Tailoring (200-300)"] = "Couture (Artisan) (200-300)",
  ["To train past 225, visit {n:0:horde:Daryl Stack} in Tarren Mill, Hillsbrad Foothills (Horde) or {n:0:alliance:Timothy Worthington} in Theramore Isle, Dustwallow Marsh (Alliance) and learn Artisan Tailoring. You need {b}Tailoring 200{/b} and {b}level 35{/b}."] = "Pour dépasser 225, va voir {n:0:horde:Daryl Stack} à Moulin-de-Tarren, dans les contreforts de Hautebrande (Horde) ou {n:0:alliance:Timothy Worthington} sur l'île de Theramore, dans le marécage d'Âprefange (Alliance) et apprends Couture (Artisan). Il te faut {b}Couture 200{/b} et {b}niveau 35{/b}.",
  ["5x {s:12074:inv_shoulder_25:Black Mageweave Shoulders} - 15 Bolt of Mageweave, 10 Heavy Silken Thread"] = "5x {s:12074:inv_shoulder_25:Black Mageweave Shoulders} - 15 Rouleau de tisse-mage, 10 Fil de soie épais",
  ["{b}The Expert trainers in Undercity and Stormwind don't teach this recipe{/b}, you can only learn it from the two trainers above."] = "{b}Les maîtres Expert de Fossoyeuse et de Hurlevent n'enseignent pas cette recette{/b}, tu ne peux l'apprendre qu'auprès des deux maîtres ci-dessus.",
  ["23x {s:18401:inv_fabric_purplefire_02:Bolt of Runecloth} - 115 Runecloth"] = "23x {s:18401:inv_fabric_purplefire_02:Bolt of Runecloth} - 115 Étoffe runique",
  ["Keep the bolts, you will need them later. In total you will need 311 {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth} (1555 {i:14047:inv_fabric_purplefire_01:Runecloth}) until 280, so you can also make all of them now."] = "Garde les rouleaux, tu en auras besoin plus tard. Au total, il te faudra 311 {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth} (1555 {i:14047:inv_fabric_purplefire_01:Runecloth}) jusqu'à 280, tu peux donc aussi tous les faire maintenant.",
  ["26x {s:12065:inv_misc_bag_10_black:Mageweave Bag} - 104 Bolt of Mageweave, 52 Silken Thread"] = "26x {s:12065:inv_misc_bag_10_black:Mageweave Bag} - 104 Rouleau de tisse-mage, 52 Fil de soie",
  ["I recommend the bags right now simply because they are more useful. You can use them yourself, sell some, give them to friends or use them in your bank."] = "Je te conseille les sacs pour l'instant simplement parce qu'ils sont plus utiles. Tu peux les utiliser toi-même, en vendre, en donner à des amis ou les mettre dans ta banque.",
  ["If you don't need the bags and don't want to sell them, make these instead."] = "Si tu n'as pas besoin des sacs et que tu ne veux pas les vendre, fais plutôt celles-ci.",
  ["10x {s:18402:inv_belt_15:Runecloth Belt} - 30 Bolt of Runecloth, 10 Rune Thread."] = "10x {s:18402:inv_belt_15:Runecloth Belt} - 30 Rouleau d'étoffe runique, 10 Fil runique.",
  ["24x {s:18402:inv_belt_15:Runecloth Belt} - 72 Bolt of Runecloth, 24 Rune Thread"] = "24x {s:18402:inv_belt_15:Runecloth Belt} - 72 Rouleau d'étoffe runique, 24 Fil runique",
  ["11x {s:18417:inv_gauntlets_25:Runecloth Gloves} - 44 Bolt of Runecloth, 44 Rugged Leather, 11 Rune Thread"] = "11x {s:18417:inv_gauntlets_25:Runecloth Gloves} - 44 Rouleau d'étoffe runique, 44 Cuir robuste, 11 Fil runique",
  ["The pattern is sold by {n:0::Qia} in Winterspring."] = "Le patron est vendu par {n:0::Qia} au Berceau-de-l'Hiver.",
  ["39x {s:1257487:inv_bracer_13:Runecloth Cuffs} - 195 Bolt of Runecloth, 39 Ironweb Spider Silk, 39 Rune Thread"] = "39x {s:1257487:inv_bracer_13:Runecloth Cuffs} - 195 Rouleau d'étoffe runique, 39 Soie d'araignée toile-de-fer, 39 Fil runique",
  ["The pattern is sold by {n:0::Pexmit} in Mount Hyjal. It's bind on pickup, so buy it with the character that levels Tailoring."] = "Le patron est vendu par {n:0::Pexmit} au mont Hyjal. Il est lié quand ramassé, alors achète-le avec le personnage qui monte la Couture.",
  ["Horde players can also get it as the reward for {q:95769::Threading a Solution}, a quest from {n:265788::Kal'tinzan} in Elderwild, Mount Hyjal. It needs level 54 and 6 Bolt of Runecloth. It's probably a Tailoring quest, but I don't know yet what skill it needs."] = "Les joueurs de la Horde peuvent aussi l'obtenir en récompense de {q:95769::Threading a Solution}, une quête de {n:265788::Kal'tinzan} à Elderwild, au mont Hyjal. Elle demande le niveau 54 et 6 Rouleau d'étoffe runique. C'est probablement une quête de Couture, mais je ne sais pas encore quelle compétence elle demande.",
  ["Make the {s:18449:inv_shoulder_21:Runecloth Shoulders} if you can get the pattern. These are all the recipes I found so far that still give points after 280. I left out the ones that aren't worth it for leveling, and there might be new ones that nobody has found yet."] = "Fais les {s:18449:inv_shoulder_21:Runecloth Shoulders} si tu peux obtenir le patron. Voici toutes les recettes que j'ai trouvées jusqu'ici qui donnent encore des points après 280. J'ai laissé de côté celles qui ne valent pas le coup pour monter, et il y en a peut-être de nouvelles que personne n'a encore trouvées.",
  ["Range"] = "Palier",
  ["Materials"] = "Matériaux",
  ["Pattern"] = "Patron",
  ["World drop, on the Auction House"] = "Butin du monde, à l'hôtel des ventes",
  ["Rare, grab it if you see it on the Auction House"] = "Rare, prends-le si tu le vois à l'hôtel des ventes",
  ["You can get a few more points with these, but they stop giving skill points before 300, so you can't reach 300 with them:"] = "Tu peux gagner quelques points de plus avec ceux-ci, mais ils ne donnent plus de points de compétence avant 300, tu ne peux donc pas atteindre 300 avec :",
  ["{n:0::Pexmit} in Mount Hyjal"] = "{n:0::Pexmit} au mont Hyjal",
  ["Recipes that need a Loom"] = "Recettes qui nécessitent un métier à tisser",
  ["{b}These recipes need a Loom, and you can only make a Loom at Tailoring 300.{/b} They could be used for leveling, but for now you would need a camp where another tailor already placed a Loom. I'm not sure if this is an oversight by Blizzard, so they might change it."] = "{b}Ces recettes nécessitent un métier à tisser, et tu ne peux en fabriquer un qu'à Couture 300.{/b} Elles pourraient servir à monter, mais pour l'instant il te faudrait un camp où un autre tailleur a déjà posé un métier à tisser. Je ne sais pas si c'est un oubli de Blizzard, ça pourrait donc changer.",
  ["These are the Cenarion Circle patterns from {n:0::Mishta} in Silithus:"] = "Voici les patrons du Cercle cénarien vendus par {n:0::Mishta} en Silithus :",
  ["Requires"] = "Prérequis",
  ["5x {s:1297123:inv_gauntlets_17:Swarmtender's Gloves} or {s:1297120:inv_gauntlets_18:Venomspew Gloves}"] = "5x {s:1297123:inv_gauntlets_17:Swarmtender's Gloves} ou {s:1297120:inv_gauntlets_18:Venomspew Gloves}",
  ["20x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "20x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} ou {i:7082:spell_nature_earthbind:Essence of Air}",
  ["Cenarion Circle Friendly"] = "Cercle cénarien Amical",
  ["5x {s:1297124:inv_belt_03:Swarmtender's Cord} or {s:1297121:inv_belt_25:Venomspew Cord}"] = "5x {s:1297124:inv_belt_03:Swarmtender's Cord} ou {s:1297121:inv_belt_25:Venomspew Cord}",
  ["30x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "30x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} ou {i:7082:spell_nature_earthbind:Essence of Air}",
  ["Cenarion Circle Honored"] = "Cercle cénarien Honoré",
  ["18x {s:1297125:inv_boots_cloth_01:Swarmtender's Footpads} or {s:1297122:inv_boots_cloth_04:Venomspew Footpads}"] = "18x {s:1297125:inv_boots_cloth_01:Swarmtender's Footpads} ou {s:1297122:inv_boots_cloth_04:Venomspew Footpads}",
  ["90x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 18x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 54x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "90x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 18x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 54x {i:7080:spell_nature_acid_01:Essence of Water} ou {i:7082:spell_nature_earthbind:Essence of Air}",
  ["This WoW Forever Mining leveling guide will show you the fastest way to level Mining from 1 to 300. You will also find every trainer location and where to train Mining past 75, 150 and 225."] = "Ce guide de montée en Minage pour WoW Forever te montre la façon la plus rapide de monter le Minage de 1 à 300. Tu y trouveras aussi l'emplacement de chaque maître et où apprendre le Minage au-delà de 75, 150 et 225.",
  ["Below you will find the Mining trainers by starting zone and capital city, and the best zones to mine in for every skill range. Mining serves two professions, Blacksmithing and Engineering, so it's really good combined with these two. Check out my Forever Blacksmithing leveling guide or my Forever Engineering leveling guide if you want to level one of them."] = "Tu trouveras ci-dessous les maîtres de Minage par zone de départ et capitale, et les meilleures zones où miner pour chaque palier de compétence. Le Minage sert deux métiers, la Forge et l'Ingénierie, il se combine donc très bien avec ces deux-là. Jette un œil à mon guide de montée en Forge pour Forever ou à mon guide de montée en Ingénierie pour Forever si tu veux monter l'un d'eux.",
  ["WoW Forever added a couple of new ores, bars and recipes. You can check them out here:"] = "WoW Forever a ajouté quelques nouveaux minerais, barres et recettes. Tu peux les découvrir ici :",
  ["Mining Trainer Locations"] = "Emplacements des maîtres de Minage",
  ["Every capital city except Darnassus has a Mining trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "Chaque capitale sauf Darnassus a un maître de Minage. Tu peux aussi demander à un garde, il sera alors marqué d'un drapeau rouge sur ta carte.",
  ["{b}Capital cities:{/b}"] = "{b}Capitales :{/b}",
  ["Orgrimmar: {n:0:horde:Makaru}"] = "Orgrimmar : {n:0:horde:Makaru}",
  ["Undercity: {n:0:horde:Brom Killian}"] = "Fossoyeuse : {n:0:horde:Brom Killian}",
  ["Thunder Bluff: {n:0:horde:Brek Stonehoof}"] = "Les Pitons-du-Tonnerre : {n:0:horde:Brek Stonehoof}",
  ["{b}Starting zones:{/b}"] = "{b}Zones de départ :{/b}",
  ["{n:0:horde:Norzsh} in the Valley of Trials (only up to 75) {n:0:horde:Krunn} in Razor Hill"] = "{n:0:horde:Norzsh} dans la vallée des Épreuves (seulement jusqu'à 75) {n:0:horde:Krunn} à Tranchecolline",
  ["{n:0:horde:Vartha Rockmane} in Camp Narache (only up to 75) {n:0:horde:Brek Stonehoof} in Thunder Bluff"] = "{n:0:horde:Vartha Rockmane} au camp Narache (seulement jusqu'à 75) {n:0:horde:Brek Stonehoof} aux Pitons-du-Tonnerre",
  ["{n:0:horde:Walter Mason} in Deathknell (only up to 75) {n:0:horde:Brom Killian} in Undercity"] = "{n:0:horde:Walter Mason} au Glas (seulement jusqu'à 75) {n:0:horde:Brom Killian} à Fossoyeuse",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} as your reward, it teaches you Mining. The trainers on the island are {n:0::Halavuul Cragwind} in Valanaar and {n:0::Messana Crestwind} in Shen'dar Village."] = "Il n'y a pas de maître au village de Thendal, où tu commences, mais tu n'en as pas besoin. {q:93552::Harvesting Windstones} est l'une des premières quêtes que tu reçois au village de Thendal. Choisis {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} comme récompense, il t'apprend le Minage. Les maîtres de l'île sont {n:0::Halavuul Cragwind} à Valanaar et {n:0::Messana Crestwind} au village de Shen'dar.",
  ["Stormwind City: {n:0:alliance:Gelman Stonehand}"] = "Hurlevent : {n:0:alliance:Gelman Stonehand}",
  ["Ironforge: {n:0:alliance:Geofram Bouldertoe}"] = "Forgefer : {n:0:alliance:Geofram Bouldertoe}",
  ["Darnassus: no trainer, the closest one is {n:0:alliance:Kurdram Stonehammer} in Auberdine, Darkshore"] = "Darnassus : pas de maître, le plus proche est {n:0:alliance:Kurdram Stonehammer} à Auberdine, en Sombrivage",
  ["{n:0:alliance:Kelsey Fargo} (only up to 75) {n:0:alliance:Gelman Stonehand} in Stormwind City"] = "{n:0:alliance:Kelsey Fargo} (seulement jusqu'à 75) {n:0:alliance:Gelman Stonehand} à Hurlevent",
  ["{n:0:alliance:Sally Swiftwrench} (only up to 75) {n:0:alliance:Yarr Hammerstone} at Steelgrill's Depot {n:0:alliance:Dank Drizzlecut} at Gol'Bolar Quarry"] = "{n:0:alliance:Sally Swiftwrench} (seulement jusqu'à 75) {n:0:alliance:Yarr Hammerstone} au dépôt de Steelgrill {n:0:alliance:Dank Drizzlecut} à la carrière de Gol'Bolar",
  ["{n:0:alliance:Fanorran Stilloak} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Kurdram Stonehammer} in Auberdine, Darkshore"] = "{n:0:alliance:Fanorran Stilloak} à Aldrassil, à Sombrevallon (seulement jusqu'à 75) {n:0:alliance:Kurdram Stonehammer} à Auberdine, en Sombrivage",
  ["You can find every Mining trainer for Horde and Alliance on my WoW Forever Mining Trainers page."] = "Tu trouveras tous les maîtres de Minage de la Horde et de l'Alliance sur ma page WoW Forever Mining Trainers.",
  ["Track Ore on Your Minimap"] = "Repérer les minerais sur ta minicarte",
  ["You can only track one thing at a time, so {b}you can't track minerals and herbs together{/b}."] = "Tu ne peux repérer qu'une seule chose à la fois, donc {b}tu ne peux pas repérer les minerais et les herbes en même temps{/b}.",
  ["You learn {s:2580:spell_nature_earthquake:Find Minerals} together with Mining, but it's not turned on by default:"] = "Tu apprends {s:2580:spell_nature_earthquake:Find Minerals} en même temps que le Minage, mais ce n'est pas activé par défaut :",
  ["Open the Professions window with the hammer and pick button, the 2nd button in the menu at the bottom of your screen."] = "Ouvre la fenêtre des métiers avec le bouton marteau et pioche, le 2e bouton du menu en bas de ton écran.",
  ["Click Find Minerals in the Mining box. {b}I recommend dragging it to your action bar, close to the buffs you use after you die.{/b} This way you make a habit out of it and you are less likely to forget it."] = "Clique sur Découverte de gisements dans le cadre Minage. {b}Je te conseille de le glisser sur ta barre d'action, près des améliorations que tu utilises après une mort.{/b} Comme ça, tu en prends l'habitude et tu risques moins de l'oublier.",
  ["The Find Minerals buff shows up next to your minimap. {b}Your tracking turns off every time you die, so don't forget to turn it back on!{/b}"] = "L'amélioration Découverte de gisements apparaît à côté de ta minicarte. {b}Ton repérage se désactive à chaque mort, alors n'oublie pas de le réactiver !{/b}",
  ["The Find Minerals button in the WoW Forever Professions window"] = "Le bouton Découverte de gisements dans la fenêtre des métiers de WoW Forever",
  ["Mining Skill Bonuses"] = "Bonus de compétence de Minage",
  ["You don't need these, but they help when you are stuck between two ores. With +5 you can mine Iron Deposits from 120 instead of 125, so you can skip the last few slow points of Tin."] = "Tu n'en as pas besoin, mais ils aident quand tu es bloqué entre deux minerais. Avec +5, tu peux miner les gisements de fer dès 120 au lieu de 125, et ainsi sauter les derniers points lents de l'étain.",
  ["Item"] = "Objet",
  ["Mining"] = "Minage",
  ["How to get it"] = "Comment l'obtenir",
  ["An enchanter"] = "Un enchanteur",
  ["Made by Engineers, you need Engineering 205 to wear it"] = "Fabriqué par les ingénieurs, il te faut Ingénierie 205 pour le porter",
  ["Reward of A Miner Problem, an Alliance quest in the Riverglades"] = "Récompense de A Miner Problem, une quête de l'Alliance dans les Riverglades",
  ["Drops from Miner Johnson in The Deadmines"] = "Butin du Mineur Johnson dans les Mortemines",
  ["Smelting to 105"] = "Fonte jusqu'à 105",
  ["You can skip the first 105 skill points by buying ores on the Auction House and smelting them. If you prefer leveling Mining the normal way, scroll down to the mining routes. But I would recommend smelting if you have the gold, as it saves a lot of time. Sometimes the bars even sell for more than the ores or they are very close in price, so it's not like you are losing much by doing this."] = "Tu peux sauter les 105 premiers points de compétence en achetant du minerai à l'hôtel des ventes et en le fondant. Si tu préfères monter le Minage de façon classique, descends jusqu'aux itinéraires de minage. Mais je te conseille la fonte si tu as l'or, car elle fait gagner beaucoup de temps. Parfois, les barres se vendent même plus cher que le minerai ou à un prix très proche, donc tu ne perds pas grand-chose.",
  ["Buy around 140 {i:2770:inv_ore_copper_01:Copper Ore} and 70 {i:2771:inv_ore_tin_01:Tin Ore}. Smelting is mostly yellow and green, so you might need a few more if you are unlucky."] = "Achète environ 140 {i:2770:inv_ore_copper_01:Copper Ore} et 70 {i:2771:inv_ore_tin_01:Tin Ore}. La fonte est surtout jaune et verte, il t'en faudra donc peut-être un peu plus si tu n'as pas de chance.",
  ["Notes"] = "Remarques",
  ["120-140x {s:2657:inv_ingot_02:Smelt Copper} until you reach 65. Keep 70 Copper Bars, you will need them for Bronze."] = "120-140x {s:2657:inv_ingot_02:Smelt Copper} jusqu'à atteindre 65. Garde 70 Barre de cuivre, tu en auras besoin pour le bronze.",
  ["Learn Journeyman Mining, Smelt Tin and Smelt Bronze from your trainer. Make 70x {s:3304:inv_ingot_05:Smelt Tin}. It turns grey at 75, but you need all 70 Tin Bars for Bronze anyway."] = "Apprends Minage (Compagnon), Fondre de l'étain et Fondre du bronze auprès de ton maître. Fais 70x {s:3304:inv_ingot_05:Smelt Tin}. Ça devient gris à 75, mais il te faut de toute façon les 70 barres d'étain pour le bronze.",
  ["Make 70x {s:2659:inv_ingot_bronze:Smelt Bronze} from the Copper Bars and Tin Bars you made. You will end up somewhere between 100 and 110, so you might need a few more."] = "Fais 70x {s:2659:inv_ingot_bronze:Smelt Bronze} avec les barres de cuivre et d'étain que tu as faites. Tu finiras quelque part entre 100 et 110, il t'en faudra donc peut-être quelques-unes de plus.",
  ["Learn Smelt Silver from your trainer. Check the price of Silver Ore and Silver Bar first, because this part can get expensive. If you don't mind the cost, make 35-45x {s:2658:inv_ingot_01:Smelt Silver} until you reach 120. The last 5 points to 125 could take around 50 more Silver Ore, so I recommend mining from 120. (or keep smelting if you have the gold) Iron Deposits need Mining 125, but with +5 from the Mining Skill Bonuses above you can mine them from 120, so you can skip Tin and go straight to Iron."] = "Apprends Fondre de l'argent auprès de ton maître. Vérifie d'abord le prix du minerai d'argent et de la barre d'argent, car cette partie peut coûter cher. Si le coût ne te dérange pas, fais 35-45x {s:2658:inv_ingot_01:Smelt Silver} jusqu'à atteindre 120. Les 5 derniers points jusqu'à 125 pourraient demander environ 50 minerais d'argent de plus, je te conseille donc de miner à partir de 120. (ou continue la fonte si tu as l'or) Les gisements de fer demandent Minage 125, mais avec le +5 des bonus de compétence de Minage ci-dessus, tu peux les miner dès 120 : tu peux donc sauter l'étain et passer directement au fer.",
  ["{b}Don't forget to buy{/b} a {i:2901:inv_pick_02:Mining Pick} from the Mining Supplier near your trainer or from the trainer!"] = "{b}N'oublie pas d'acheter{/b} une {i:2901:inv_pick_02:Mining Pick} auprès du fournisseur de minage près de ton maître ou auprès du maître !",
  ["You can buy one from these vendors:"] = "Tu peux en acheter une auprès de ces marchands :",
  ["{n:0:horde:Norzsh} in the Valley of Trials, {n:0:horde:Flakk} in Razor Hill"] = "{n:0:horde:Norzsh} dans la vallée des Épreuves, {n:0:horde:Flakk} à Tranchecolline",
  ["{n:0:horde:Vartha Rockmane} in Camp Narache, {n:0:horde:Wunna Darkmane} in Bloodhoof Village"] = "{n:0:horde:Vartha Rockmane} au camp Narache, {n:0:horde:Wunna Darkmane} au village de Sabot-de-Sang",
  ["{n:0:horde:Walter Mason} in Deathknell, {n:0:horde:Abigail Shiel} in Brill"] = "{n:0:horde:Walter Mason} au Glas, {n:0:horde:Abigail Shiel} à Brill",
  ["{n:0::Uualia Suncrest} in Thendal Village, {n:0::Belandiel Farflight} in Shen'dar Village"] = "{n:0::Uualia Suncrest} au village de Thendal, {n:0::Belandiel Farflight} au village de Shen'dar",
  ["{n:0:horde:Gorina} in the Valley of Honor"] = "{n:0:horde:Gorina} dans la vallée de l'Honneur",
  ["{n:0:horde:Elizabeth Van Talen} in the Rogues' Quarter"] = "{n:0:horde:Elizabeth Van Talen} dans le quartier des Voleurs",
  ["{n:0:alliance:Brother Danil} in Northshire Valley, {n:0:alliance:Tharynn Bouden} in Goldshire"] = "{n:0:alliance:Brother Danil} dans la vallée de Comté-du-Nord, {n:0:alliance:Tharynn Bouden} à Comté-de-l'Or",
  ["{n:0:alliance:Thrawn Boltar} in Kharanos"] = "{n:0:alliance:Thrawn Boltar} à Kharanos",
  ["{n:0:alliance:Fanorran Stilloak} at Aldrassil in Shadowglen, {n:0:alliance:Narret Shadowgrove} in Dolanaar"] = "{n:0:alliance:Fanorran Stilloak} à Aldrassil, à Sombrevallon, {n:0:alliance:Narret Shadowgrove} à Dolanaar",
  ["{n:0:alliance:Brooke Stonebraid} in the Dwarven District"] = "{n:0:alliance:Brooke Stonebraid} dans le quartier des Nains",
  ["{n:0:alliance:Thurgrum Deepforge} in The Great Forge"] = "{n:0:alliance:Thurgrum Deepforge} à la Grande Forge",
  ["Like I said above, for most high level players I think it's best to skip this part and smelt your way up to at least 105. But if you prefer mining and you can choose your zone, I think {b}Durotar{/b} is the best for Horde and {b}Elwynn Forest{/b} for Alliance."] = "Comme je l'ai dit plus haut, pour la plupart des joueurs de haut niveau, je pense qu'il vaut mieux sauter cette partie et monter par la fonte jusqu'à au moins 105. Mais si tu préfères miner et que tu peux choisir ta zone, je pense que {b}Durotar{/b} est la meilleure pour la Horde et la {b}forêt d'Elwynn{/b} pour l'Alliance.",
  ["One or two laps around the zone will get you enough Copper Ore to reach 65 with smelting."] = "Un ou deux tours de la zone te donneront assez de minerai de cuivre pour atteindre 65 avec la fonte.",
  ["After you do one lap, {b}stop at Razor Hill and smelt your Copper Ore{/b} into Copper Bars."] = "Après un tour, {b}arrête-toi à Tranchecolline et fonds ton minerai de cuivre{/b} en barres de cuivre.",
  ["Mining route in Durotar"] = "Itinéraire de minage à Durotar",
  ["The cave marked with the red circle has 5 Copper Veins inside, {b}the respawn rate is so fast that you can basically stay inside the cave and level there{/b}. The cave layout is also very good because there is a drop down at the end, so you can quickly return to the start and continue mining. If the respawn rate is not enough for you or there is competition, just run outside, mine a couple of Copper Veins and go back to the cave."] = "La grotte entourée en rouge contient 5 filons de cuivre, {b}la réapparition est si rapide que tu peux pratiquement rester dans la grotte et monter là{/b}. La disposition de la grotte est aussi très pratique car il y a un saut à la fin, tu peux donc revenir rapidement au début et continuer à miner. Si la réapparition ne te suffit pas ou s'il y a de la concurrence, sors simplement, mine quelques filons de cuivre et retourne dans la grotte.",
  ["You can also just do a full lap in Mulgore, the route is very easy to follow, it's basically a loop around the edge of the zone. But I found the cave to be better without a mount."] = "Tu peux aussi simplement faire un tour complet de Mulgore, l'itinéraire est très facile à suivre, c'est en gros une boucle le long du bord de la zone. Mais j'ai trouvé la grotte meilleure sans monture.",
  ["{b}You can smelt your ore at the Bael'dun Digsite{/b}, the dwarf camp just north of the cave has a forge and an anvil. (marked on the map) The dwarves there are hostile."] = "{b}Tu peux fondre ton minerai au site de fouilles de Bael'dun{/b}, le camp de nains juste au nord de la grotte a une forge et une enclume. (marquées sur la carte) Les nains là-bas sont hostiles.",
  ["Mining route in Mulgore with the forge and anvil at the Bael'dun Digsite"] = "Itinéraire de minage en Mulgore avec la forge et l'enclume du site de fouilles de Bael'dun",
  ["Both routes are good. The route on the east side of the zone will probably have fewer people, because there are fewer quest hubs there."] = "Les deux itinéraires sont bons. Celui à l'est de la zone aura probablement moins de monde, car il y a moins de pôles de quêtes là-bas.",
  ["{b}Stop at Brill after one lap{/b} to smelt your Copper Ore."] = "{b}Arrête-toi à Brill après un tour{/b} pour fondre ton minerai de cuivre.",
  ["Mining route in Tirisfal Glades"] = "Itinéraire de minage dans les clairières de Tirisfal",
  ["{q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} as your reward, it teaches you Mining."] = "{q:93552::Harvesting Windstones} est l'une des premières quêtes que tu reçois au village de Thendal. Choisis {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} comme récompense, il t'apprend le Minage.",
  ["The respawn rate is very fast around this area, sometimes the veins spawned right on top of me. You can do a larger route, but without a mount and with the fast respawn rate I found it wasn't needed."] = "La réapparition est très rapide dans ce secteur, parfois les filons apparaissaient juste sous mes pieds. Tu peux faire un itinéraire plus large, mais sans monture et avec une réapparition aussi rapide, je n'en ai pas vu l'utilité.",
  ["{b}Stop at Shen'dar Village after one lap{/b} to smelt your Copper Ore."] = "{b}Arrête-toi au village de Shen'dar après un tour{/b} pour fondre ton minerai de cuivre.",
  ["Mining route on Zephras Isle"] = "Itinéraire de minage sur Zephras Isle",
  ["Just move back and forth along the marked route, and clear the cave if you are high enough level. The respawn rate is quite fast inside the cave, so you might not even have to leave it, it depends on your level. You can also just skip the cave, the respawn rate seems to be fast enough on the route, but then do the small detour to the north too."] = "Fais simplement des allers-retours le long de l'itinéraire marqué, et nettoie la grotte si ton niveau est assez élevé. La réapparition est assez rapide dans la grotte, tu n'auras peut-être même pas besoin d'en sortir, ça dépend de ton niveau. Tu peux aussi sauter la grotte, la réapparition semble assez rapide sur l'itinéraire, mais fais alors aussi le petit détour au nord.",
  ["{b}Stop at Goldshire after one lap{/b} to smelt your Copper Ore."] = "{b}Arrête-toi à Comté-de-l'Or après un tour{/b} pour fondre ton minerai de cuivre.",
  ["Mining route in Elwynn Forest"] = "Itinéraire de minage dans la forêt d'Elwynn",
  ["Not much to say about this one, just do loops around this area. You don't have to go inside the cave, it's optional and the respawn rate outside is quite fast."] = "Pas grand-chose à dire sur celui-ci, fais simplement des boucles dans ce secteur. Tu n'es pas obligé d'entrer dans la grotte, c'est facultatif et la réapparition dehors est assez rapide.",
  ["{b}Stop at Kharanos after one lap{/b} to smelt your Copper Ore."] = "{b}Arrête-toi à Kharanos après un tour{/b} pour fondre ton minerai de cuivre.",
  ["Mining route in Dun Morogh"] = "Itinéraire de minage à Dun Morogh",
  ["These two caves have an insanely fast respawn rate. I don't know if it stays like this, but right now you can just stay inside the caves and level there."] = "Ces deux grottes ont une réapparition incroyablement rapide. Je ne sais pas si ça va durer, mais pour l'instant tu peux simplement rester dans les grottes et monter là.",
  ["There is no forge in Teldrassil, {b}the closest one is at the Warrior's Terrace in Darnassus{/b}."] = "Il n'y a pas de forge à Teldrassil, {b}la plus proche est à la terrasse des Guerriers à Darnassus{/b}.",
  ["Mining route in Teldrassil"] = "Itinéraire de minage à Teldrassil",
  ["Visit your trainer and learn Journeyman Mining, it requires Mining 50. The new Junior Mining Trainers in the starting areas won't teach you Journeyman Mining."] = "Va voir ton maître et apprends Minage (Compagnon), ça demande Minage 50. Les nouveaux maîtres de Minage débutants des zones de départ ne t'apprendront pas Minage (Compagnon).",
  ["If you have any Copper Ore or Tin Ore at this point, smelt them and make Bronze Bars before you head out, because Bronze stops giving skill points around 105."] = "S'il te reste du minerai de cuivre ou d'étain à ce stade, fonds-le et fais des barres de bronze avant de partir, car le bronze ne donne plus de points de compétence vers 105.",
  ["For Alliance, the {b}Wetlands{/b} is the best one by far if you can manage the cave. For Horde it's the {b}Silverpine Forest{/b} cave or {b}Hillsbrad Foothills{/b}. The rest are pretty even, hard to judge."] = "Pour l'Alliance, {b}les Paluns{/b} sont de loin la meilleure zone si tu peux gérer la grotte. Pour la Horde, c'est la grotte de la {b}forêt des Pins-Argentés{/b} ou les {b}contreforts de Hautebrande{/b}. Les autres se valent à peu près, difficile de trancher.",
  ["Ores in these zones: {i:2771:inv_ore_tin_01:Tin Ore}, {i:2770:inv_ore_copper_01:Copper Ore}, {i:2775:inv_stone_16:Silver Ore}"] = "Minerais dans ces zones : {i:2771:inv_ore_tin_01:Tin Ore}, {i:2770:inv_ore_copper_01:Copper Ore}, {i:2775:inv_stone_16:Silver Ore}",
  ["Tin Veins need Mining 65 and Silver Veins 75."] = "Les filons d'étain demandent Minage 65 et les filons d'argent 75.",
  ["Wetlands"] = "Les Paluns",
  ["Silverpine Forest"] = "Forêt des Pins-Argentés",
  ["Westfall"] = "Marche de l'Ouest",
  ["Hillsbrad Foothills"] = "Contreforts de Hautebrande",
  ["The Barrens"] = "Les Tarides",
  ["Ashenvale"] = "Orneval",
  ["Stonetalon Mountains"] = "Les Serres-Rocheuses",
  ["This cave in the Wetlands is the best place for Alliance players to level Mining. The cave is full of Tin Veins and Incendicite Mineral Veins with a very fast respawn time."] = "Cette grotte des Paluns est le meilleur endroit pour monter le Minage côté Alliance. Elle est pleine de filons d'étain et de filons d'incendicite avec une réapparition très rapide.",
  ["The mobs are around level 20 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "Les monstres sont autour du niveau 20 et {b}dans Forever ils réapparaissent beaucoup plus vite, il te faut donc les dépasser de pas mal de niveaux{/b}, sinon ils vont réapparaître sans arrêt juste sur toi.",
  ["Mining route in the Wetlands"] = "Itinéraire de minage dans les Paluns",
  ["This cave has 3 vein spawn points with a very fast respawn time, just mine the veins and wait for the respawn. (around 2 minutes)"] = "Cette grotte a 3 points d'apparition de filons avec une réapparition très rapide, mine simplement les filons et attends qu'ils réapparaissent. (environ 2 minutes)",
  ["The mobs are around level 21-22 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "Les monstres sont autour du niveau 21-22 et {b}dans Forever ils réapparaissent beaucoup plus vite, il te faut donc les dépasser de pas mal de niveaux{/b}, sinon ils vont réapparaître sans arrêt juste sur toi.",
  ["Mining route in Silverpine Forest"] = "Itinéraire de minage dans la forêt des Pins-Argentés",
  ["This cave has several Tin Veins that respawn very fast. There are also veins outside, so if you clear it too fast you can just run outside and mine a few there too."] = "Cette grotte a plusieurs filons d'étain qui réapparaissent très vite. Il y a aussi des filons dehors, donc si tu la vides trop vite, tu peux simplement sortir et en miner quelques-uns là aussi.",
  ["The mobs are around level 13-15 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "Les monstres sont autour du niveau 13-15 et {b}dans Forever ils réapparaissent beaucoup plus vite, il te faut donc les dépasser de pas mal de niveaux{/b}, sinon ils vont réapparaître sans arrêt juste sur toi.",
  ["Mining route in Westfall"] = "Itinéraire de minage dans la marche de l'Ouest",
  ["This is the best if you prefer mining the normal way, but you might have more competition from other players because this is a popular area. The route goes around a Horde town, so I'm not sure how it works for Alliance. I think you can probably avoid the guards, but I only tested this one with a Horde character."] = "C'est le meilleur si tu préfères miner de façon classique, mais tu risques d'avoir plus de concurrence car c'est un secteur populaire. L'itinéraire fait le tour d'une ville de la Horde, je ne sais donc pas trop comment ça se passe côté Alliance. Je pense que tu peux probablement éviter les gardes, mais je ne l'ai testé qu'avec un personnage de la Horde.",
  ["Mining route in Hillsbrad Foothills"] = "Itinéraire de minage dans les contreforts de Hautebrande",
  ["The mobs are around level 22-26 here, so it's best to farm here if you are above those levels. But the respawn rate is fast."] = "Les monstres sont autour du niveau 22-26 ici, il vaut donc mieux farmer ici si tu es au-dessus de ces niveaux. Mais la réapparition est rapide.",
  ["Mining route in The Barrens"] = "Itinéraire de minage dans les Tarides",
  ["A very straightforward route that is easy to follow. This is the best if you prefer mining the normal way, but you might have more competition from other players because this is a popular area."] = "Un itinéraire très simple et facile à suivre. C'est le meilleur si tu préfères miner de façon classique, mais tu risques d'avoir plus de concurrence car c'est un secteur populaire.",
  ["Mining route in Ashenvale"] = "Itinéraire de minage en Orneval",
  ["This route might not work if more than one player is leveling Mining there, because when I tested it there were very few people around. But this place usually has fewer people, so I think it's a good alternative if you don't want to level in caves. The only downside is that sometimes an Iron Deposit spawns instead of a Tin Vein, and you can't mine it yet."] = "Cet itinéraire risque de ne pas fonctionner si plus d'un joueur y monte le Minage, car quand je l'ai testé il y avait très peu de monde. Mais cet endroit est généralement moins fréquenté, je pense donc que c'est une bonne alternative si tu ne veux pas monter dans des grottes. Le seul défaut, c'est que parfois un gisement de fer apparaît à la place d'un filon d'étain, et tu ne peux pas encore le miner.",
  ["Mining route in Stonetalon Mountains"] = "Itinéraire de minage dans les Serres-Rocheuses",
  ["From this point the guide follows the standard Classic Mining routes. The beta cap was 30, so I couldn't properly test Arathi and Desolace. I'll revise this section once I level my character higher on live, but the main change is the ore respawn rate, so most routes should work and you can probably take shorter routes in most zones."] = "À partir d'ici, le guide suit les itinéraires de minage standard de Classic. La limite de la bêta était 30, je n'ai donc pas pu tester correctement Arathi et Désolace. Je réviserai cette section une fois mon personnage monté plus haut sur le live, mais le principal changement est la vitesse de réapparition du minerai, donc la plupart des itinéraires devraient fonctionner et tu pourras probablement prendre des itinéraires plus courts dans la plupart des zones.",
  ["{b}Visit your trainer and learn Expert Mining{/b}, it requires Mining 125."] = "{b}Va voir ton maître et apprends Minage (Expert){/b}, ça demande Minage 125.",
  ["Smelting Iron and Gold (optional)"] = "Fonte du fer et de l'or (facultatif)",
  ["If you want to save some time and have the gold, buy around 20 {i:2772:inv_ore_iron_01:Iron Ore} and make {s:3307:inv_ingot_iron:Smelt Iron} until 135 before you head out mining. After 135 it rarely gives a point, so don't count on reaching 140."] = "Si tu veux gagner du temps et que tu as l'or, achète environ 20 {i:2772:inv_ore_iron_01:Iron Ore} et fais {s:3307:inv_ingot_iron:Smelt Iron} jusqu'à 135 avant de partir miner. Après 135, ça donne rarement un point, ne compte donc pas atteindre 140.",
  ["At 155 you can learn {s:3308:inv_ingot_03:Smelt Gold} from your trainer. It gives a point every time until 170, so around 22 Gold Ore takes you from 155 to 175 and you can start on Mithril right away. I recommend checking the price of Gold Ore and Gold Bar first."] = "À 155, tu peux apprendre {s:3308:inv_ingot_03:Smelt Gold} auprès de ton maître. Ça donne un point à chaque fois jusqu'à 170, donc environ 22 minerais d'or te font passer de 155 à 175 et tu peux commencer le mithril tout de suite. Je te conseille de vérifier d'abord le prix du minerai d'or et de la barre d'or.",
  ["If you have a {b}lower level character{/b} around level 30, stick to the {b}Thousand Needles{/b} route, that's the safest. If you have a {b}higher level character or a mount{/b} already, I recommend {b}Arathi Highlands{/b}."] = "Si tu as un {b}personnage de plus bas niveau{/b}, autour du niveau 30, reste sur l'itinéraire de {b}Mille pointes{/b}, c'est le plus sûr. Si tu as déjà un {b}personnage de plus haut niveau ou une monture{/b}, je te conseille les {b}hautes-terres d'Arathi{/b}.",
  ["Ores in these zones: {i:2772:inv_ore_iron_01:Iron Ore}, {i:2771:inv_ore_tin_01:Tin Ore}, {i:2776:inv_ore_gold_01:Gold Ore}"] = "Minerais dans ces zones : {i:2772:inv_ore_iron_01:Iron Ore}, {i:2771:inv_ore_tin_01:Tin Ore}, {i:2776:inv_ore_gold_01:Gold Ore}",
  ["Iron Deposits need Mining 125 and Gold Veins 155."] = "Les gisements de fer demandent Minage 125 et les filons d'or 155.",
  ["Arathi Highlands"] = "Hautes-terres d'Arathi",
  ["Thousand Needles"] = "Mille pointes",
  ["Desolace"] = "Désolace",
  ["There are 4 caves marked with red circles on the map. Make sure to go all the way to the end of each cave because you won't see all the mining veins from the entrance."] = "Il y a 4 grottes entourées en rouge sur la carte. Va bien jusqu'au fond de chaque grotte, car tu ne verras pas tous les filons depuis l'entrée.",
  ["Low level players should skip all 4 caves, and low level Alliance players should take a detour and go south of Hammerfall!"] = "Les joueurs de bas niveau devraient sauter les 4 grottes, et les joueurs de l'Alliance de bas niveau devraient faire un détour par le sud de Trépas-d'Orgrim !",
  ["Mining route in Arathi Highlands"] = "Itinéraire de minage dans les hautes-terres d'Arathi",
  ["Mining route in Thousand Needles"] = "Itinéraire de minage à Mille pointes",
  ["Mining route in Desolace"] = "Itinéraire de minage en Désolace",
  ["To train past 225, visit your trainer and learn Artisan Mining, it requires Mining 200."] = "Pour dépasser 225, va voir ton maître et apprends Minage (Artisan), ça demande Minage 200.",
  ["Ores in these zones: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}"] = "Minerais dans ces zones : {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}",
  ["Mithril Deposits need Mining 175 and Truesilver Deposits 230."] = "Les gisements de mithril demandent Minage 175 et les gisements de vrai-argent 230.",
  ["The Hinterlands"] = "Les Hinterlands",
  ["The red route should be skipped by lower level players because the area is filled with level 62 elites. Lower level players might also want to consider skipping the cave marked with a red circle on the map. (depends on your gear/class)"] = "Les joueurs de plus bas niveau devraient sauter l'itinéraire rouge, car le secteur est rempli d'élites de niveau 62. Les joueurs de plus bas niveau peuvent aussi envisager de sauter la grotte entourée en rouge sur la carte. (selon ton équipement et ta classe)",
  ["Mining route in The Hinterlands"] = "Itinéraire de minage dans les Hinterlands",
  ["Players below level 60 should skip the 4 caves marked with red circles."] = "Les joueurs en dessous du niveau 60 devraient sauter les 4 grottes entourées en rouge.",
  ["Mining route in Tanaris"] = "Itinéraire de minage à Tanaris",
  ["Ores in these zones: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}, {i:10620:inv_ore_thorium_02:Thorium Ore}"] = "Minerais dans ces zones : {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}, {i:10620:inv_ore_thorium_02:Thorium Ore}",
  ["Small Thorium Veins need Mining 245."] = "Les petits filons de thorium demandent Minage 245.",
  ["Un'Goro Crater"] = "Cratère d'Un'Goro",
  ["Blasted Lands"] = "Terres foudroyées",
  ["Felwood"] = "Gangrebois",
  ["You will find 2-3 veins in the two caves marked with red circles on the map."] = "Tu trouveras 2-3 filons dans les deux grottes entourées en rouge sur la carte.",
  ["Lower level players should probably skip the cave to the south. It really depends on your level, gear and class."] = "Les joueurs de plus bas niveau devraient probablement sauter la grotte au sud. Ça dépend vraiment de ton niveau, de ton équipement et de ta classe.",
  ["Mining route in Un'Goro Crater"] = "Itinéraire de minage dans le cratère d'Un'Goro",
  ["Both caves marked with red circles have a lot of mobs inside, so I only recommend this zone to level 60 players with good gear, or to Druids and Rogues with stealth."] = "Les deux grottes entourées en rouge contiennent beaucoup de monstres, je ne recommande donc cette zone qu'aux joueurs de niveau 60 bien équipés, ou aux druides et voleurs avec le camouflage.",
  ["It's really hard to navigate inside the Garrison Armory mine, so I included a small map. {b}Alliance{/b} players can't mine inside the Garrison Armory!"] = "Il est vraiment difficile de s'orienter dans la mine de l'armurerie de la garnison, j'ai donc ajouté une petite carte. Les joueurs de l'{b}Alliance{/b} ne peuvent pas miner dans l'armurerie de la garnison !",
  ["Mining route in the Blasted Lands"] = "Itinéraire de minage dans les terres foudroyées",
  ["There are usually 2 veins inside the cave marked with a red circle. It's worth going in because the cave is small and there aren't many mobs inside, and if you are high level, you can pass some of them without aggro."] = "Il y a généralement 2 filons dans la grotte entourée en rouge. Ça vaut le coup d'y entrer car la grotte est petite et il n'y a pas beaucoup de monstres, et si tu es de haut niveau, tu peux passer à côté de certains sans les attirer.",
  ["I recommend skipping the other two caves at Jaedenar, especially Shadow Hold. (if you have stealth, they might be worth going into)"] = "Je te conseille de sauter les deux autres grottes de Jaedenar, surtout Shadow Hold. (si tu as le camouflage, elles peuvent valoir le coup)",
  ["Mining route in Felwood"] = "Itinéraire de minage en Gangrebois",
  ["Ores in these zones: {i:10620:inv_ore_thorium_02:Thorium Ore}, {i:3858:inv_ore_mithril_02:Mithril Ore}"] = "Minerais dans ces zones : {i:10620:inv_ore_thorium_02:Thorium Ore}, {i:3858:inv_ore_mithril_02:Mithril Ore}",
  ["At 275 you can mine Rich Thorium Veins too."] = "À 275, tu peux aussi miner les riches filons de thorium.",
  ["Eastern Plaguelands"] = "Maleterres de l'Est",
  ["Winterspring"] = "Berceau-de-l'Hiver",
  ["Burning Steppes"] = "Steppes ardentes",
  ["Almost the same as the previous Un'Goro route, but now it includes Rich Thorium Veins."] = "Presque le même que l'itinéraire d'Un'Goro précédent, mais il inclut maintenant les riches filons de thorium.",
  ["Mining route with Rich Thorium Veins in Un'Goro Crater"] = "Itinéraire de minage avec les riches filons de thorium dans le cratère d'Un'Goro",
  ["The red line is full of level 57-58 elites, so if your gear is bad, you should probably skip that part unless you have stealth. With some practice you can usually get through and only pull a few of them."] = "La ligne rouge est pleine d'élites de niveau 57-58, donc si ton équipement est faible, tu devrais probablement sauter cette partie, sauf si tu as le camouflage. Avec un peu de pratique, tu arrives généralement à passer en n'en attirant que quelques-uns.",
  ["Mining route in the Eastern Plaguelands"] = "Itinéraire de minage dans les Maleterres de l'Est",
  ["The mobs in this cave are not that hard, so most classes can clear it. (depends on your gear)"] = "Les monstres de cette grotte ne sont pas si durs, la plupart des classes peuvent la nettoyer. (selon ton équipement)",
  ["Most classes can get into at least the first part of the cave without pulling aggro. You can try going deeper depending on your gear."] = "La plupart des classes peuvent entrer au moins dans la première partie de la grotte sans attirer les monstres. Tu peux essayer d'aller plus loin selon ton équipement.",
  ["A lot of elites patrol this gorge, but you can usually pass most of them without pulling aggro. Sometimes you have to kill 1 or 2."] = "Beaucoup d'élites patrouillent dans cette gorge, mais tu peux généralement passer à côté de la plupart sans les attirer. Parfois, tu dois en tuer 1 ou 2.",
  ["I don't recommend this area for most players because it's hard to farm here without dying. It really depends on your class and how good you are at avoiding mobs."] = "Je ne recommande pas ce secteur à la plupart des joueurs car il est difficile d'y farmer sans mourir. Ça dépend vraiment de ta classe et de ton habileté à éviter les monstres.",
  ["Mining route in Winterspring"] = "Itinéraire de minage au Berceau-de-l'Hiver",
  ["The two caves marked with red circles are full of level 50 mobs, so lower level players might want to skip them. (depends on your gear and level)"] = "Les deux grottes entourées en rouge sont pleines de monstres de niveau 50, les joueurs de plus bas niveau peuvent donc vouloir les sauter. (selon ton équipement et ton niveau)",
  ["Mining route in the Burning Steppes"] = "Itinéraire de minage dans les steppes Ardentes",
  ["This WoW Forever Herbalism leveling guide will show you the fastest way to level Herbalism from 1 to 300. You will also find a route map for every zone, every trainer location and where to train Herbalism past 75, 150 and 225."] = "Ce guide de montée en Herboristerie pour WoW Forever te montre la façon la plus rapide de monter l'Herboristerie de 1 à 300. Tu y trouveras aussi une carte d'itinéraire pour chaque zone, l'emplacement de chaque maître et où apprendre l'Herboristerie au-delà de 75, 150 et 225.",
  ["Below you will find the Herbalism trainers by starting zone and capital city, and the best zones to pick herbs in for every skill range. Herbalism goes well with Alchemy because you can use the herbs you pick to make potions and elixirs, so check out my Forever Alchemy leveling guide if you want to level Alchemy. But keep in mind, this guide is made to level Herbalism as fast as possible, so sometimes the herbs you pick are not the best ones for Alchemy."] = "Tu trouveras ci-dessous les maîtres d'Herboristerie par zone de départ et capitale, et les meilleures zones où cueillir des herbes pour chaque palier de compétence. L'Herboristerie va bien avec l'Alchimie car tu peux utiliser les herbes cueillies pour faire des potions et des élixirs, alors jette un œil à mon guide de montée en Alchimie pour Forever si tu veux monter l'Alchimie. Mais garde en tête que ce guide est fait pour monter l'Herboristerie le plus vite possible, donc les herbes que tu cueilles ne sont pas toujours les meilleures pour l'Alchimie.",
  ["WoW Forever added a couple of new herbs, seeds and recipes. You can check them out here:"] = "WoW Forever a ajouté quelques nouvelles herbes, graines et recettes. Tu peux les découvrir ici :",
  ["Herbalism Trainer Locations"] = "Emplacements des maîtres d'Herboristerie",
  ["Every capital city has a Herbalism trainer. You can also ask a guard where the herbalist is, then it will be marked with a red flag on your map."] = "Chaque capitale a un maître d'Herboristerie. Tu peux aussi demander à un garde où se trouve l'herboriste, il sera alors marqué d'un drapeau rouge sur ta carte.",
  ["Orgrimmar: {n:0:horde:Jandi}"] = "Orgrimmar : {n:0:horde:Jandi}",
  ["Undercity: {n:0:horde:Martha Alliestar}"] = "Fossoyeuse : {n:0:horde:Martha Alliestar}",
  ["Thunder Bluff: {n:0:horde:Komin Winterhoof}"] = "Les Pitons-du-Tonnerre : {n:0:horde:Komin Winterhoof}",
  ["{n:0:horde:Zor'la} in the Valley of Trials (only up to 75) {n:0:horde:Mishiki} in Sen'jin Village"] = "{n:0:horde:Zor'la} dans la vallée des Épreuves (seulement jusqu'à 75) {n:0:horde:Mishiki} au village de Sen'jin",
  ["{n:0:horde:Garan Sunstrider} in Camp Narache (only up to 75) {n:0:horde:Komin Winterhoof} in Thunder Bluff"] = "{n:0:horde:Garan Sunstrider} au camp Narache (seulement jusqu'à 75) {n:0:horde:Komin Winterhoof} aux Pitons-du-Tonnerre",
  ["{n:0:horde:Florence Nightshade} in Deathknell (only up to 75) {n:0:horde:Faruza} in Brill"] = "{n:0:horde:Florence Nightshade} au Glas (seulement jusqu'à 75) {n:0:horde:Faruza} à Brill",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} as your reward, it teaches you Herbalism. The trainers on the island are {n:0::Syriel Nightrain} in Valanaar and {n:0::Halassa Fernbreeze} in Shen'dar Village."] = "Il n'y a pas de maître au village de Thendal, où tu commences, mais tu n'en as pas besoin. {q:93552::Harvesting Windstones} est l'une des premières quêtes que tu reçois au village de Thendal. Choisis {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} comme récompense, il t'apprend l'Herboristerie. Les maîtres de l'île sont {n:0::Syriel Nightrain} à Valanaar et {n:0::Halassa Fernbreeze} au village de Shen'dar.",
  ["Stormwind City: {n:0:alliance:Tannysa}"] = "Hurlevent : {n:0:alliance:Tannysa}",
  ["Ironforge: {n:0:alliance:Reyna Stonebranch}"] = "Forgefer : {n:0:alliance:Reyna Stonebranch}",
  ["Darnassus: {n:0:alliance:Firodren Mooncaller}"] = "Darnassus : {n:0:alliance:Firodren Mooncaller}",
  ["{n:0:alliance:Nancy Songflower} (only up to 75) {n:0:alliance:Herbalist Pomeroy}"] = "{n:0:alliance:Nancy Songflower} (seulement jusqu'à 75) {n:0:alliance:Herbalist Pomeroy}",
  ["{n:0:alliance:Emrys Flintbeard} (only up to 75) {n:0:alliance:Reyna Stonebranch} in Ironforge"] = "{n:0:alliance:Emrys Flintbeard} (seulement jusqu'à 75) {n:0:alliance:Reyna Stonebranch} à Forgefer",
  ["{n:0:alliance:Eleyna Duskbreeze} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Malorne Bladeleaf} in Dolanaar"] = "{n:0:alliance:Eleyna Duskbreeze} à Aldrassil, à Sombrevallon (seulement jusqu'à 75) {n:0:alliance:Malorne Bladeleaf} à Dolanaar",
  ["You can find every Herbalism trainer for Horde and Alliance on my WoW Forever Herbalism Trainers page."] = "Tu trouveras tous les maîtres d'Herboristerie de la Horde et de l'Alliance sur ma page WoW Forever Herbalism Trainers.",
  ["Track Herbs on Your Minimap"] = "Repérer les herbes sur ta minicarte",
  ["You can only track one thing at a time, so {b}you can't track herbs and minerals together{/b}."] = "Tu ne peux repérer qu'une seule chose à la fois, donc {b}tu ne peux pas repérer les herbes et les minerais en même temps{/b}.",
  ["You learn {s:2383:inv_misc_flower_02:Find Herbs} together with Herbalism, but it's not turned on by default:"] = "Tu apprends {s:2383:inv_misc_flower_02:Find Herbs} en même temps que l'Herboristerie, mais ce n'est pas activé par défaut :",
  ["Click Find Herbs in the Herbalism box. {b}I recommend dragging it to your action bar, close to the buffs you use after you die.{/b} This way you make a habit out of it and you are less likely to forget it."] = "Clique sur Découverte d'herbes dans le cadre Herboristerie. {b}Je te conseille de le glisser sur ta barre d'action, près des améliorations que tu utilises après une mort.{/b} Comme ça, tu en prends l'habitude et tu risques moins de l'oublier.",
  ["The Find Herbs buff shows up next to your minimap. {b}Your tracking turns off every time you die, so don't forget to turn it back on!{/b}"] = "L'amélioration Découverte d'herbes apparaît à côté de ta minicarte. {b}Ton repérage se désactive à chaque mort, alors n'oublie pas de le réactiver !{/b}",
  ["Herbalism Skill Bonuses"] = "Bonus de compétence d'Herboristerie",
  ["You don't need these, but they help when you are stuck between two herbs. With +5 you can pick Kingsblood from 120 instead of 125, so you can move on earlier."] = "Tu n'en as pas besoin, mais ils aident quand tu es bloqué entre deux herbes. Avec +5, tu peux cueillir le Sang-royal dès 120 au lieu de 125, et donc passer à la suite plus tôt.",
  ["Herbalism"] = "Herboristerie",
  ["A world drop, check the Auction House"] = "Un butin du monde, regarde à l'hôtel des ventes",
  ["Henry Stern in Razorfen Downs teaches the recipe, it {b}requires Cooking 175{/b}. Take the left path at the start of the instance and go all the way to the end, to the stables, knock down the walls and talk to him."] = "Henry Stern dans les Souilles de Tranchebauge enseigne la recette, elle {b}demande Cuisine 175{/b}. Prends le chemin de gauche au début de l'instance et va tout au bout, jusqu'aux étables, abats les murs et parle-lui.",
  ["can be very handy when you find a herb you can't pick yet and you are only a few points short. It will probably be pretty expensive early on because of the Goldthorn prices, but it's worth keeping a few with you while you level Herbalism."] = "peut être très pratique quand tu trouves une herbe que tu ne peux pas encore cueillir et qu'il ne te manque que quelques points. Ce sera sans doute assez cher au début à cause du prix de la Dorépine, mais ça vaut le coup d'en garder quelques-uns sur toi pendant que tu montes l'Herboristerie.",
  ["Every starting zone is full of herbs, so it doesn't really matter which one you choose. The respawn rate is so fast that without a mount you often can't even finish a full lap, you just run around in circles and pick the herbs as you see them."] = "Chaque zone de départ est pleine d'herbes, peu importe donc laquelle tu choisis. La réapparition est si rapide que sans monture tu n'arrives souvent même pas à finir un tour complet, tu tournes en rond et tu cueilles les herbes au fur et à mesure.",
  ["Herbs in these zones: {i:2447:inv_misc_flower_02:Peacebloom}, {i:765:inv_misc_herb_10:Silverleaf}, {i:2449:inv_misc_herb_07:Earthroot}"] = "Herbes dans ces zones : {i:2447:inv_misc_flower_02:Peacebloom}, {i:765:inv_misc_herb_10:Silverleaf}, {i:2449:inv_misc_herb_07:Earthroot}",
  ["Earthroot requires Herbalism 15."] = "La Terrestrine demande Herboristerie 15.",
  ["Herbalism route in Durotar"] = "Itinéraire d'herboristerie à Durotar",
  ["Herbalism route in Mulgore"] = "Itinéraire d'herboristerie en Mulgore",
  ["Herbalism route in Tirisfal Glades"] = "Itinéraire d'herboristerie dans les clairières de Tirisfal",
  ["{q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} as your reward, it teaches you Herbalism."] = "{q:93552::Harvesting Windstones} est l'une des premières quêtes que tu reçois au village de Thendal. Choisis {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} comme récompense, il t'apprend l'Herboristerie.",
  ["Herbalism route on Zephras Isle"] = "Itinéraire d'herboristerie sur Zephras Isle",
  ["Herbalism route in Elwynn Forest"] = "Itinéraire d'herboristerie dans la forêt d'Elwynn",
  ["Herbalism route in Dun Morogh"] = "Itinéraire d'herboristerie à Dun Morogh",
  ["Herbalism route in Teldrassil"] = "Itinéraire d'herboristerie à Teldrassil",
  ["Visit your trainer and learn Journeyman Herbalism, it requires Herbalism 50. The new Junior Herbalism Trainers in the starting areas won't teach you Journeyman Herbalism."] = "Va voir ton maître et apprends Herboristerie (Compagnon), ça demande Herboristerie 50. Les nouveaux maîtres d'Herboristerie débutants des zones de départ ne t'apprendront pas Herboristerie (Compagnon).",
  ["Herbs in these zones: {i:785:inv_jewelry_talisman_03:Mageroyal}, {i:2450:inv_misc_root_01:Briarthorn}, {i:3820:inv_misc_herb_11:Stranglekelp}"] = "Herbes dans ces zones : {i:785:inv_jewelry_talisman_03:Mageroyal}, {i:2450:inv_misc_root_01:Briarthorn}, {i:3820:inv_misc_herb_11:Stranglekelp}",
  ["Stranglekelp requires Herbalism 85, so you can't pick it right away."] = "L'Étouffante demande Herboristerie 85, tu ne peux donc pas la cueillir tout de suite.",
  ["The respawn rate in the lower part of Silverpine Forest is fast enough that you can basically run in small circles in the marked area. I tested this without a mount, so with a mount it might be different, but then running up and down the main road to the loop should work fine as well."] = "La réapparition dans la partie basse de la forêt des Pins-Argentés est assez rapide pour que tu puisses pratiquement tourner en petits cercles dans le secteur marqué. Je l'ai testé sans monture, avec une monture ce sera peut-être différent, mais dans ce cas faire des allers-retours sur la route principale jusqu'à la boucle devrait aussi bien marcher.",
  ["Herbalism route in Silverpine Forest"] = "Itinéraire d'herboristerie dans la forêt des Pins-Argentés",
  ["A very easy route to follow, but there might be a bit fewer herbs than in Darkshore."] = "Un itinéraire très facile à suivre, mais il y a peut-être un peu moins d'herbes qu'en Sombrivage.",
  ["Herbalism route in Loch Modan"] = "Itinéraire d'herboristerie au Loch Modan",
  ["Darkshore has herbs everywhere. I used this loop, but you can also expand it to the upper part of the map. The respawn rate is fast, so you can do smaller circles in different areas. I just found this route pretty easy and chill to follow."] = "Il y a des herbes partout en Sombrivage. J'ai utilisé cette boucle, mais tu peux aussi l'étendre à la partie haute de la carte. La réapparition est rapide, tu peux donc faire de plus petits cercles dans différents secteurs. J'ai juste trouvé cet itinéraire facile et tranquille à suivre.",
  ["Herbalism route in Darkshore"] = "Itinéraire d'herboristerie en Sombrivage",
  ["To train past 150, visit your trainer and learn Expert Herbalism, it requires Herbalism 125."] = "Pour dépasser 150, va voir ton maître et apprends Herboristerie (Expert), ça demande Herboristerie 125.",
  ["Herbs in these zones: {i:2453:inv_misc_herb_01:Bruiseweed}, {i:3355:inv_misc_flower_01:Wild Steelbloom}, {i:3820:inv_misc_herb_11:Stranglekelp}, {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}"] = "Herbes dans ces zones : {i:2453:inv_misc_herb_01:Bruiseweed}, {i:3355:inv_misc_flower_01:Wild Steelbloom}, {i:3820:inv_misc_herb_11:Stranglekelp}, {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}",
  ["Kingsblood requires Herbalism 125 and Liferoot 150, so you can't pick them right away."] = "Le Sang-royal demande Herboristerie 125 et la Vietérule 150, tu ne peux donc pas les cueillir tout de suite.",
  ["Running this loop in Hillsbrad Foothills gives the herbs enough time to respawn, but I tested it without a mount, so with a mount it might be different."] = "Faire cette boucle dans les contreforts de Hautebrande laisse aux herbes le temps de réapparaître, mais je l'ai testée sans monture, avec une monture ce sera peut-être différent.",
  ["Herbalism route in Hillsbrad Foothills"] = "Itinéraire d'herboristerie dans les contreforts de Hautebrande",
  ["All three areas are good here:"] = "Les trois secteurs sont bons ici :",
  ["The mobs here are only around level 14-15, so this is the lowest level area where you can safely farm these herbs."] = "Les monstres ici ne sont qu'autour du niveau 14-15, c'est donc le secteur de plus bas niveau où tu peux farmer ces herbes en sécurité.",
  ["A good alternative if someone is already farming the first area. The mobs are higher level here, around 25."] = "Une bonne alternative si quelqu'un farme déjà le premier secteur. Les monstres sont de plus haut niveau ici, autour de 25.",
  ["This area is usually pretty crowded and full of mobs. {b}I only recommend it if you are over 125 already{/b}, because there is more Kingsblood here."] = "Ce secteur est généralement assez fréquenté et plein de monstres. {b}Je ne le recommande que si tu es déjà au-dessus de 125{/b}, car il y a plus de Sang-royal ici.",
  ["Herbalism route in Stonetalon Mountains"] = "Itinéraire d'herboristerie dans les Serres-Rocheuses",
  ["From this point the guide follows the standard Classic Herbalism routes. The beta cap was 30, so I couldn't test the higher level routes. I'll revise this section once I level my character higher on live, but the main change is the herb respawn rate, so most routes should work."] = "À partir d'ici, le guide suit les itinéraires d'herboristerie standard de Classic. La limite de la bêta était 30, je n'ai donc pas pu tester les itinéraires de plus haut niveau. Je réviserai cette section une fois mon personnage monté plus haut sur le live, mais le principal changement est la vitesse de réapparition des herbes, donc la plupart des itinéraires devraient fonctionner.",
  ["Herbs in these zones: {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}, {i:3818:inv_misc_herb_12:Fadeleaf}, {i:3821:inv_misc_herb_15:Goldthorn}, {i:3358:inv_misc_herb_08:Khadgar's Whisker}"] = "Herbes dans ces zones : {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}, {i:3818:inv_misc_herb_12:Fadeleaf}, {i:3821:inv_misc_herb_15:Goldthorn}, {i:3358:inv_misc_herb_08:Khadgar's Whisker}",
  ["Khadgar's Whisker requires Herbalism 185, so you can't pick it right away."] = "La Moustache de Khadgar demande Herboristerie 185, tu ne peux donc pas la cueillir tout de suite.",
  ["Stranglethorn Vale"] = "Vallée de Strangleronce",
  ["Herbalism route in Stranglethorn Vale"] = "Itinéraire d'herboristerie dans la vallée de Strangleronce",
  ["Herbalism route in Arathi Highlands"] = "Itinéraire d'herboristerie dans les hautes-terres d'Arathi",
  ["{b}Learn Artisan Herbalism before you leave for these zones{/b}, it requires Herbalism 200. There is no trainer in Tanaris or Searing Gorge, so if you skip it, you have to fly back at 225."] = "{b}Apprends Herboristerie (Artisan) avant de partir dans ces zones{/b}, ça demande Herboristerie 200. Il n'y a pas de maître à Tanaris ni dans la gorge des Vents brûlants, donc si tu oublies, tu devras revenir en vol à 225.",
  ["Herbs in these zones: {i:8831:inv_misc_herb_17:Purple Lotus}, {i:4625:inv_misc_herb_19:Firebloom}"] = "Herbes dans ces zones : {i:8831:inv_misc_herb_17:Purple Lotus}, {i:4625:inv_misc_herb_19:Firebloom}",
  ["Searing Gorge"] = "Gorge des Vents brûlants",
  ["Herbalism route in Tanaris"] = "Itinéraire d'herboristerie à Tanaris",
  ["Herbalism route in Searing Gorge"] = "Itinéraire d'herboristerie dans la gorge des Vents brûlants",
  ["Herbs in The Hinterlands: {i:8838:inv_misc_herb_18:Sungrass}, {i:8831:inv_misc_herb_17:Purple Lotus}, {i:8845:inv_mushroom_08:Ghost Mushroom}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}"] = "Herbes dans les Hinterlands : {i:8838:inv_misc_herb_18:Sungrass}, {i:8831:inv_misc_herb_17:Purple Lotus}, {i:8845:inv_mushroom_08:Ghost Mushroom}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}",
  ["I marked a cave with a red X, there are a lot of Ghost Mushrooms in the cave, but you can only pick them with Herbalism 245."] = "J'ai marqué une grotte d'un X rouge, il y a beaucoup de Champignons fantômes dans la grotte, mais tu ne peux les cueillir qu'avec Herboristerie 245.",
  ["Herbalism route in The Hinterlands"] = "Itinéraire d'herboristerie dans les Hinterlands",
  ["Herbs in Felwood: {i:8838:inv_misc_herb_18:Sungrass}, {i:8846:inv_misc_herb_16:Gromsblood}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}, {i:13463:inv_misc_herb_dreamfoil:Dreamfoil}, {i:13465:inv_misc_herb_mountainsilversage:Mountain Silversage}, {i:13466:inv_misc_herb_plaguebloom:Plaguebloom}"] = "Herbes en Gangrebois : {i:8838:inv_misc_herb_18:Sungrass}, {i:8846:inv_misc_herb_16:Gromsblood}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}, {i:13463:inv_misc_herb_dreamfoil:Dreamfoil}, {i:13465:inv_misc_herb_mountainsilversage:Mountain Silversage}, {i:13466:inv_misc_herb_plaguebloom:Plaguebloom}",
  ["Herbalism route in Felwood"] = "Itinéraire d'herboristerie en Gangrebois",
  ["This WoW Forever Skinning leveling guide will show you the fastest way to level Skinning from 1 to 300. You will also find every trainer location and the best places to skin for each skill range."] = "Ce guide de montée en Dépeçage pour WoW Forever te montre la façon la plus rapide de monter le Dépeçage de 1 à 300. Tu y trouveras aussi l'emplacement de chaque maître et les meilleurs endroits où dépecer pour chaque palier de compétence.",
  ["This guide is aimed at higher level players who want to switch their profession, but it's good for lower level players too. Leveling Skinning is easy but really boring, you will have to run around and skin hundreds of mobs. Skinning goes well with Leatherworking because you can use the leather you skin, so check out my Forever Leatherworking leveling guide if you want to level Leatherworking."] = "Ce guide s'adresse aux joueurs de plus haut niveau qui veulent changer de métier, mais il convient aussi aux joueurs de plus bas niveau. Monter le Dépeçage est facile mais vraiment ennuyeux, tu vas devoir courir partout et dépecer des centaines de monstres. Le Dépeçage va bien avec le Travail du cuir car tu peux utiliser le cuir que tu dépèces, alors jette un œil à mon guide de montée en Travail du cuir pour Forever si tu veux monter le Travail du cuir.",
  ["Skinning Trainer Locations"] = "Emplacements des maîtres de Dépeçage",
  ["Every capital city has a Skinning trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "Chaque capitale a un maître de Dépeçage. Tu peux aussi demander à un garde, il sera alors marqué d'un drapeau rouge sur ta carte.",
  ["Orgrimmar: {n:0:horde:Thuwd}"] = "Orgrimmar : {n:0:horde:Thuwd}",
  ["Undercity: {n:0:horde:Killian Hagey}"] = "Fossoyeuse : {n:0:horde:Killian Hagey}",
  ["Thunder Bluff: {n:0:horde:Mooranta}"] = "Les Pitons-du-Tonnerre : {n:0:horde:Mooranta}",
  ["{n:0:horde:Kagil} in the Valley of Trials (only up to 75) {n:0:horde:Thuwd} in Orgrimmar"] = "{n:0:horde:Kagil} dans la vallée des Épreuves (seulement jusqu'à 75) {n:0:horde:Thuwd} à Orgrimmar",
  ["{n:0:horde:Nawka Wildsong} in Camp Narache (only up to 75) {n:0:horde:Yonn Deepcut} in Bloodhoof Village"] = "{n:0:horde:Nawka Wildsong} au camp Narache (seulement jusqu'à 75) {n:0:horde:Yonn Deepcut} au village de Sabot-de-Sang",
  ["{n:0:horde:Margaret Weaver} in Deathknell (only up to 75) {n:0:horde:Rand Rhobart} in Tirisfal Glades"] = "{n:0:horde:Margaret Weaver} au Glas (seulement jusqu'à 75) {n:0:horde:Rand Rhobart} dans les clairières de Tirisfal",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247846:inv_10_specialization_professionbook_skinning_color1:Pelt Collecting for Beginners} as your reward, it teaches you Skinning. The trainers on the island are {n:0::Ishlee Breezewhisper} in Valanaar and {n:0::Mendalass Tattermend} in Shen'dar Village."] = "Il n'y a pas de maître au village de Thendal, où tu commences, mais tu n'en as pas besoin. {q:93552::Harvesting Windstones} est l'une des premières quêtes que tu reçois au village de Thendal. Choisis {i:247846:inv_10_specialization_professionbook_skinning_color1:Pelt Collecting for Beginners} comme récompense, il t'apprend le Dépeçage. Les maîtres de l'île sont {n:0::Ishlee Breezewhisper} à Valanaar et {n:0::Mendalass Tattermend} au village de Shen'dar.",
  ["Stormwind City: {n:0:alliance:Maris Granger}"] = "Hurlevent : {n:0:alliance:Maris Granger}",
  ["Ironforge: {n:0:alliance:Balthus Stoneflayer}"] = "Forgefer : {n:0:alliance:Balthus Stoneflayer}",
  ["Darnassus: {n:0:alliance:Eladriel}"] = "Darnassus : {n:0:alliance:Eladriel}",
  ["{n:0:alliance:Riley Peltskinner} in Northshire Valley (only up to 75) {n:0:alliance:Helene Peltskinner} in Goldshire"] = "{n:0:alliance:Riley Peltskinner} dans la vallée de Comté-du-Nord (seulement jusqu'à 75) {n:0:alliance:Helene Peltskinner} à Comté-de-l'Or",
  ["{n:0:alliance:Brighid Stormflayer} (only up to 75) {n:0:alliance:Balthus Stoneflayer} in Ironforge"] = "{n:0:alliance:Brighid Stormflayer} (seulement jusqu'à 75) {n:0:alliance:Balthus Stoneflayer} à Forgefer",
  ["{n:0:alliance:Terunne Bearshaper} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Radnaal Maneweaver} in Teldrassil"] = "{n:0:alliance:Terunne Bearshaper} à Aldrassil, à Sombrevallon (seulement jusqu'à 75) {n:0:alliance:Radnaal Maneweaver} à Teldrassil",
  ["You can find every Skinning trainer for Horde and Alliance on my WoW Forever Skinning Trainers page."] = "Tu trouveras tous les maîtres de Dépeçage de la Horde et de l'Alliance sur ma page WoW Forever Skinning Trainers.",
  ["Skinning Skill Requirements"] = "Compétence de Dépeçage requise",
  ["You need 5 times the mob's level in Skinning to skin it, so a level 30 mob needs Skinning 150. Below level 20 it's less, if you follow the guide you don't have to worry about this."] = "Il te faut 5 fois le niveau du monstre en Dépeçage pour le dépecer, donc un monstre de niveau 30 demande Dépeçage 150. En dessous du niveau 20 c'est moins, si tu suis le guide tu n'as pas à t'en soucier.",
  ["Mob level"] = "Niveau du monstre",
  ["Skinning needed"] = "Dépeçage requis",
  ["10 for a level 11 mob, 10 more for every level (level 15 needs 50, level 19 needs 90)"] = "10 pour un monstre de niveau 11, 10 de plus par niveau (le niveau 15 demande 50, le niveau 19 demande 90)",
  ["20 and up"] = "20 et plus",
  ["5 times the level"] = "5 fois le niveau",
  ["If you enchant your gloves with {s:13698:spell_holy_greaterheal:Enchant Gloves - Skinning}, you can skin mobs 1 level higher than normal."] = "Si tu enchantes tes gants avec {s:13698:spell_holy_greaterheal:Enchant Gloves - Skinning}, tu peux dépecer des monstres d'un niveau de plus que la normale.",
  ["Horde players can also pick the {i:269716:inv_weapon_shortblade_05:Keen Skinning Knife} (+3 Skinning) as a reward from Unwelcome Guests in The Barrens."] = "Les joueurs de la Horde peuvent aussi choisir le {i:269716:inv_weapon_shortblade_05:Keen Skinning Knife} (+3 en Dépeçage) en récompense de Unwelcome Guests dans les Tarides.",
  ["In WoW Forever you can skin the mobs in the starting areas, and they give skill points all the way up to 75."] = "Dans WoW Forever, tu peux dépecer les monstres des zones de départ, et ils donnent des points de compétence jusqu'à 75.",
  ["{b}Any starting zone is good{/b} for this. If you are leveling a new character, you can skin any mob in your starting zone, so you don't need a recommendation until around level 10, when you leave the zone. The two places below are for players who already have a higher level character and want to catch up on Skinning. A lot of players will be leveling new characters there, so there is always something to skin."] = "{b}N'importe quelle zone de départ convient{/b} pour ça. Si tu montes un nouveau personnage, tu peux dépecer n'importe quel monstre de ta zone de départ, tu n'as donc pas besoin de recommandation avant le niveau 10 environ, quand tu quittes la zone. Les deux endroits ci-dessous sont pour les joueurs qui ont déjà un personnage de plus haut niveau et veulent rattraper le Dépeçage. Beaucoup de joueurs y montent de nouveaux personnages, il y a donc toujours quelque chose à dépecer.",
  ["{b}Don't forget to buy a {i:7005:inv_weapon_shortblade_01:Skinning Knife}!{/b} The Leatherworking Supply vendors near your trainer and most General Goods vendors sell it. You don't have to equip it, but you can't skin without one in your bags."] = "{b}N'oublie pas d'acheter un {i:7005:inv_weapon_shortblade_01:Skinning Knife} !{/b} Les marchands de fournitures du travail du cuir près de ton maître et la plupart des marchands généraux le vendent. Tu n'as pas besoin de l'équiper, mais tu ne peux pas dépecer sans en avoir un dans tes sacs.",
  ["Skin the {n:3098::Mottled Boars} in the Valley of Trials in Durotar."] = "Dépèce les {n:3098::Mottled Boars} dans la vallée des Épreuves à Durotar.",
  ["{b}Mob level:{/b} 1-2"] = "{b}Niveau des monstres :{/b} 1-2",
  ["The Mottled Boars in the Valley of Trials in Durotar"] = "Les Mottled Boars dans la vallée des Épreuves à Durotar",
  ["Skin the {n:299::Young Wolves} and {n:69::Timber Wolves} in Northshire Valley in Elwynn Forest."] = "Dépèce les {n:299::Young Wolves} et les {n:69::Timber Wolves} dans la vallée de Comté-du-Nord, dans la forêt d'Elwynn.",
  ["The wolves in Northshire Valley in Elwynn Forest"] = "Les loups de la vallée de Comté-du-Nord, dans la forêt d'Elwynn",
  ["Visit your trainer and learn Journeyman Skinning if you haven't yet, it requires Skinning 50. The new Junior Skinning Trainers in the starting areas won't teach you Journeyman Skinning."] = "Va voir ton maître et apprends Dépeçage (Compagnon) si ce n'est pas déjà fait, ça demande Dépeçage 50. Les nouveaux maîtres de Dépeçage débutants des zones de départ ne t'apprendront pas Dépeçage (Compagnon).",
  ["To train past 150, visit your trainer again and learn Expert Skinning when you reach 125."] = "Pour dépasser 150, retourne voir ton maître et apprends Dépeçage (Expert) quand tu atteins 125.",
  ["Kill and skin {n:3256::Sunscale Scytheclaw}, {n:3426::Zhevra Charger}, {n:3245::Ornery Plainstrider}."] = "Tue et dépèce les {n:3256::Sunscale Scytheclaw}, {n:3426::Zhevra Charger}, {n:3245::Ornery Plainstrider}.",
  ["Go to the small raptor camp just west of Northwatch Hold. Skin the level 16-17 ones until 80, from 80 you can skin the level 18 ones too. Stay here until 150, the last 10 points are green but the respawn is fast."] = "Va au petit camp de raptors juste à l'ouest du fort de Guet-du-Nord. Dépèce ceux de niveau 16-17 jusqu'à 80, à partir de 80 tu peux aussi dépecer ceux de niveau 18. Reste ici jusqu'à 150, les 10 derniers points sont verts mais la réapparition est rapide.",
  ["{b}Mob level:{/b} 16-18"] = "{b}Niveau des monstres :{/b} 16-18",
  ["The Sunscale Scytheclaws west of Northwatch Hold in the Barrens"] = "Les Sunscale Scytheclaws à l'ouest du fort de Guet-du-Nord dans les Tarides",
  ["Kill and skin {n:1192::Elder Mountain Boar}, {n:1189::Black Bear Patriarch}."] = "Tue et dépèce les {n:1192::Elder Mountain Boar}, {n:1189::Black Bear Patriarch}.",
  ["{n:1693::Loch Crocolisk} are also skinnable, make sure to pull them when you get to the shore."] = "Les {n:1693::Loch Crocolisk} se dépècent aussi, pense à les attirer quand tu arrives sur la rive.",
  ["Stay here until around 125, then head north to the Wetlands, it is on the way to Hillsbrad."] = "Reste ici jusqu'à environ 125, puis file au nord vers les Paluns, c'est sur la route de Hautebrande.",
  ["{b}Mob level:{/b} 16-17"] = "{b}Niveau des monstres :{/b} 16-17",
  ["Skinning spot in Loch Modan"] = "Spot de dépeçage au Loch Modan",
  ["125-150 Wetlands"] = "125-150 Les Paluns",
  ["Kill and skin {n:1022::Mottled Scytheclaw}, {n:1023::Mottled Razormaw}."] = "Tue et dépèce les {n:1022::Mottled Scytheclaw}, {n:1023::Mottled Razormaw}.",
  ["There are always a few of them at Whelgar's Excavation Site, so you never run out of mobs to kill."] = "Il y en a toujours quelques-uns au site d'excavation de Whelgar, tu ne seras donc jamais à court de monstres à tuer.",
  ["{b}Mob level:{/b} 25-27"] = "{b}Niveau des monstres :{/b} 25-27",
  ["Whelgar's Excavation Site in the Wetlands"] = "Le site d'excavation de Whelgar dans les Paluns",
  ["From 150, go to the Foothill Caverns in Hillsbrad Foothills, the yeti cave on the border of Alterac Mountains, or to the Rotting Orchard in Duskwood."] = "À partir de 150, va aux cavernes des Contreforts dans les contreforts de Hautebrande, la grotte des yétis à la frontière des montagnes d'Alterac, ou au verger Pourrissant dans le bois de la Pénombre.",
  ["Duskwood"] = "Bois de la Pénombre",
  ["Both factions can get there, Horde from Tarren Mill and Alliance from Southshore."] = "Les deux factions peuvent y aller, la Horde depuis Moulin-de-Tarren et l'Alliance depuis Austrivage.",
  ["Kill and skin {n:2248::Cave Yeti}, {n:2249::Ferocious Yeti}."] = "Tue et dépèce les {n:2248::Cave Yeti}, {n:2249::Ferocious Yeti}.",
  ["The yetis respawn so fast that you can stay inside the cave the whole time."] = "Les yétis réapparaissent si vite que tu peux rester dans la grotte tout le temps.",
  ["{b}Mob level:{/b} 30-32"] = "{b}Niveau des monstres :{/b} 30-32",
  ["The Foothill Caverns in Hillsbrad Foothills"] = "Les cavernes des Contreforts dans les contreforts de Hautebrande",
  ["Duskwood is an Alliance zone, but Grom'gol is close, so Horde players can get there too."] = "Le bois de la Pénombre est une zone de l'Alliance, mais Grom'gol est tout près, donc les joueurs de la Horde peuvent y aller aussi.",
  ["Kill and skin {n:898::Nightbane Worgen}, {n:533::Nightbane Shadow Weaver}, {n:205::Nightbane Dark Runner}."] = "Tue et dépèce les {n:898::Nightbane Worgen}, {n:533::Nightbane Shadow Weaver}, {n:205::Nightbane Dark Runner}.",
  ["Start at the area marked with 1, clear the mobs outside and inside Roland's Doom cave, then go to the Rotting Orchard until the mobs respawn."] = "Commence au secteur marqué 1, nettoie les monstres dehors et dans la grotte de Roland's Doom, puis va au verger Pourrissant en attendant que les monstres réapparaissent.",
  ["{b}Mob level:{/b} 26-29"] = "{b}Niveau des monstres :{/b} 26-29",
  ["Roland's Doom and the Rotting Orchard in Duskwood"] = "Roland's Doom et le verger Pourrissant dans le bois de la Pénombre",
  ["Visit your trainer and learn Artisan Skinning, it requires Skinning 200."] = "Va voir ton maître et apprends Dépeçage (Artisan), ça demande Dépeçage 200.",
  ["Mount up and go to the yeti cave at Feral Scar Vale in the south of Feralas. Both factions can get there, Horde from Camp Mojache and Alliance from Feathermoon Stronghold."] = "Monte en selle et va à la grotte des yétis de Feral Scar Vale, au sud de Féralas. Les deux factions peuvent y aller, la Horde depuis le camp Mojache et l'Alliance depuis le bastion de Plumelune.",
  ["Kill and skin {n:5292::Feral Scar Yeti}, {n:5295::Enraged Feral Scar}, {n:5293::Hulking Feral Scar}."] = "Tue et dépèce les {n:5292::Feral Scar Yeti}, {n:5295::Enraged Feral Scar}, {n:5293::Hulking Feral Scar}.",
  ["{b}Mob level:{/b} 43-46"] = "{b}Niveau des monstres :{/b} 43-46",
  ["The yeti cave at Feral Scar Vale in Feralas"] = "La grotte des yétis de Feral Scar Vale à Féralas",
  ["From 280, fly to Marshal's Refuge and skin the dinosaurs in the western part of Un'Goro Crater."] = "À partir de 280, prends le vol jusqu'au refuge des Marshal et dépèce les dinosaures dans la partie ouest du cratère d'Un'Goro.",
  ["Kill and skin {n:9163::Diemetradon}, {n:9166::Pterrordax}, {n:9164::Elder Diemetradon}, {n:9167::Frenzied Pterrordax}."] = "Tue et dépèce les {n:9163::Diemetradon}, {n:9166::Pterrordax}, {n:9164::Elder Diemetradon}, {n:9167::Frenzied Pterrordax}.",
  ["{b}Mob level:{/b} 50-55"] = "{b}Niveau des monstres :{/b} 50-55",
  ["The dinosaur area in the west of Un'Goro Crater"] = "Le secteur des dinosaures à l'ouest du cratère d'Un'Goro",
  ["This WoW Forever Fishing and Cooking leveling guide will show you the fastest way to level Fishing and Cooking together from 1 to 300."] = "Ce guide de montée en Pêche et Cuisine pour WoW Forever te montre la façon la plus rapide de monter la Pêche et la Cuisine ensemble de 1 à 300.",
  ["Leveling Fishing takes a long time, so it's best to level these two together, because every fish you catch is also a Cooking recipe and your Cooking goes up for free while you fish. You will still need a lot of patience because you have to catch a lot of fish to get from start to finish. If you only want one of them, use my Fishing guide or my Cooking guide instead."] = "Monter la Pêche prend beaucoup de temps, il vaut donc mieux monter ces deux métiers ensemble : chaque poisson que tu attrapes est aussi une recette de Cuisine, et ta Cuisine monte gratuitement pendant que tu pêches. Il te faudra quand même beaucoup de patience, car tu dois attraper beaucoup de poissons pour aller du début à la fin. Si tu ne veux que l'un des deux, utilise plutôt mon guide de Pêche ou mon guide de Cuisine.",
  ["Level Fishing to 75"] = "Monter la Pêche jusqu'à 75",
  ["If you can choose, {b}level Fishing in Mulgore{/b}, because everything is close together there. {n:0::Harn Longcast} in Bloodhoof Village sells both recipes and the pole, and the Fishing trainer stands at Stonebull Lake. Thunder Bluff, where you fish after 75, is right next to it."] = "Si tu as le choix, {b}monte la Pêche en Mulgore{/b}, car tout y est proche. {n:0::Harn Longcast} au village de Sabot-de-Sang vend les deux recettes et la canne, et le maître de Pêche se trouve au lac Taureau-de-pierre. Les Pitons-du-Tonnerre, où tu pêches après 75, sont juste à côté.",
  ["If you haven't learned Fishing yet, learn it from {n:0::Lau'Tiki} on the coast south of Sen'jin Village."] = "Si tu n'as pas encore appris la Pêche, apprends-la auprès de {n:0::Lau'Tiki} sur la côte au sud du village de Sen'jin.",
  ["Buy {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} from {n:0::Zansoa} in Sen'jin Village. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Achète {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} auprès de {n:0::Zansoa} au village de Sen'jin. Achète aussi une {i:6256:inv_fishingpole_02:Fishing Pole} et un {i:6529:inv_misc_orb_03:Shiny Bauble} là-bas. (Achète tous les {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que tu vois et garde-les pour plus tard.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish on the coast next to {n:0::Lau'Tiki}, south of Sen'jin Village, until your Fishing skill reaches 75. Almost everything you catch there is {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}, about 70 of them."] = "Équipe ta canne à pêche, fixe-y un {i:6529:inv_misc_orb_03:Shiny Bauble}, et pêche sur la côte à côté de {n:0::Lau'Tiki}, au sud du village de Sen'jin, jusqu'à ce que ta compétence de Pêche atteigne 75. Presque tout ce que tu y attrapes est du {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}, environ 70.",
  ["Learn Journeyman Fishing from {n:0::Lau'Tiki}, it requires level 10."] = "Apprends Pêche (Compagnon) auprès de {n:0::Lau'Tiki}, ça demande le niveau 10.",
  ["The coast south of Sen'jin Village in Durotar, where to fish from 1 to 75"] = "La côte au sud du village de Sen'jin à Durotar, où pêcher de 1 à 75",
  ["If you haven't learned Fishing yet, learn it from {n:0::Uthan Stillwater} at Stonebull Lake."] = "Si tu n'as pas encore appris la Pêche, apprends-la auprès de {n:0::Uthan Stillwater} au lac Taureau-de-pierre.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Harn Longcast} in Bloodhoof Village. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Achète {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} et {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} auprès de {n:0::Harn Longcast} au village de Sabot-de-Sang. Achète aussi une {i:6256:inv_fishingpole_02:Fishing Pole} et un {i:6529:inv_misc_orb_03:Shiny Bauble} là-bas. (Achète tous les {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que tu vois et garde-les pour plus tard.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Stonebull Lake until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Équipe ta canne à pêche, fixe-y un {i:6529:inv_misc_orb_03:Shiny Bauble}, et pêche dans le lac Taureau-de-pierre jusqu'à ce que ta compétence de Pêche atteigne 75. Tu attraperas environ 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} et 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Uthan Stillwater}, it requires level 10."] = "Apprends Pêche (Compagnon) auprès de {n:0::Uthan Stillwater}, ça demande le niveau 10.",
  ["Stonebull Lake around Bloodhoof Village in Mulgore, where to fish from 1 to 75"] = "Le lac Taureau-de-pierre autour du village de Sabot-de-Sang en Mulgore, où pêcher de 1 à 75",
  ["If you haven't learned Fishing yet, learn it from {n:0::Clyde Kellen} at Brightwater Lake."] = "Si tu n'as pas encore appris la Pêche, apprends-la auprès de {n:0::Clyde Kellen} au lac Brightwater.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Martine Tramblay} at the Death's Watch Waystation, south-east of Brill. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Achète {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} auprès de {n:0::Martine Tramblay} au relais de Death's Watch, au sud-est de Brill. Achète aussi une {i:6256:inv_fishingpole_02:Fishing Pole} et un {i:6529:inv_misc_orb_03:Shiny Bauble} là-bas. (Achète tous les {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que tu vois et garde-les pour plus tard.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Brightwater Lake until your Fishing skill reaches 75. You will catch about 30 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 20 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, plus some {i:6299:inv_misc_fish_28:Sickly Looking Fish} and junk."] = "Équipe ta canne à pêche, fixe-y un {i:6529:inv_misc_orb_03:Shiny Bauble}, et pêche dans le lac Brightwater jusqu'à ce que ta compétence de Pêche atteigne 75. Tu attraperas environ 30 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} et 20 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, plus quelques {i:6299:inv_misc_fish_28:Sickly Looking Fish} et des déchets.",
  ["Learn Journeyman Fishing from {n:0::Clyde Kellen}, it requires level 10."] = "Apprends Pêche (Compagnon) auprès de {n:0::Clyde Kellen}, ça demande le niveau 10.",
  ["Brightwater Lake east of Brill in Tirisfal Glades, where to fish from 1 to 75"] = "Le lac Brightwater à l'est de Brill dans les clairières de Tirisfal, où pêcher de 1 à 75",
  ["If you haven't learned Fishing yet, learn it from {n:0::Fenn Fairweather} in Shen'dar Village or {n:0::Baelann Swiftcurrent} in Valanaar."] = "Si tu n'as pas encore appris la Pêche, apprends-la auprès de {n:0::Fenn Fairweather} au village de Shen'dar ou de {n:0::Baelann Swiftcurrent} à Valanaar.",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} from {n:0::Belandiel Farflight} in Shen'dar Village or {n:0::Baelann Swiftcurrent} in Valanaar. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Achète une {i:6256:inv_fishingpole_02:Fishing Pole} et un {i:6529:inv_misc_orb_03:Shiny Bauble} auprès de {n:0::Belandiel Farflight} au village de Shen'dar ou de {n:0::Baelann Swiftcurrent} à Valanaar. (Achète tous les {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que tu vois et garde-les pour plus tard.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in any lake or river on Zephras Isle until your Fishing skill reaches 75, for example next to the Fishing trainers in Shen'dar Village and Valanaar. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}. Keep all the fish you catch."] = "Équipe ta canne à pêche, fixe-y un {i:6529:inv_misc_orb_03:Shiny Bauble}, et pêche dans n'importe quel lac ou rivière de Zephras Isle jusqu'à ce que ta compétence de Pêche atteigne 75, par exemple à côté des maîtres de Pêche du village de Shen'dar et de Valanaar. Tu attraperas environ 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} et 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}. Garde tous les poissons que tu attrapes.",
  ["Learn Journeyman Fishing from {n:0::Fenn Fairweather} or {n:0::Baelann Swiftcurrent}, it requires level 10."] = "Apprends Pêche (Compagnon) auprès de {n:0::Fenn Fairweather} ou de {n:0::Baelann Swiftcurrent}, ça demande le niveau 10.",
  ["When you get to Thunder Bluff, buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Sewa Mistrunner} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Naal Mistrunner}. They stand next to each other."] = "Quand tu arrives aux Pitons-du-Tonnerre, achète {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} auprès de {n:0::Sewa Mistrunner} et {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} auprès de {n:0::Naal Mistrunner}. Ils se tiennent l'un à côté de l'autre.",
  ["The water at Shen'dar Village and Valanaar on Zephras Isle, where to fish from 1 to 75"] = "L'eau au village de Shen'dar et à Valanaar sur Zephras Isle, où pêcher de 1 à 75",
  ["If you can choose, {b}level Fishing in Elwynn Forest{/b}, because everything is close together there. {n:0::Tharynn Bouden} in Goldshire sells both recipes and the pole, and the Fishing trainer stands at Crystal Lake. Stormwind City, where you fish after 75, is right next to it."] = "Si tu as le choix, {b}monte la Pêche dans la forêt d'Elwynn{/b}, car tout y est proche. {n:0::Tharynn Bouden} à Comté-de-l'Or vend les deux recettes et la canne, et le maître de Pêche se trouve au lac de Cristal. Hurlevent, où tu pêches après 75, est juste à côté.",
  ["If you haven't learned Fishing yet, learn it from {n:0::Lee Brown} at Crystal Lake."] = "Si tu n'as pas encore appris la Pêche, apprends-la auprès de {n:0::Lee Brown} au lac de Cristal.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Tharynn Bouden} in Goldshire. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Achète {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} et {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} auprès de {n:0::Tharynn Bouden} à Comté-de-l'Or. Achète aussi une {i:6256:inv_fishingpole_02:Fishing Pole} et un {i:6529:inv_misc_orb_03:Shiny Bauble} là-bas. (Achète tous les {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que tu vois et garde-les pour plus tard.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Crystal Lake, east of Goldshire, until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Équipe ta canne à pêche, fixe-y un {i:6529:inv_misc_orb_03:Shiny Bauble}, et pêche dans le lac de Cristal, à l'est de Comté-de-l'Or, jusqu'à ce que ta compétence de Pêche atteigne 75. Tu attraperas environ 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} et 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Lee Brown}, it requires level 10."] = "Apprends Pêche (Compagnon) auprès de {n:0::Lee Brown}, ça demande le niveau 10.",
  ["Crystal Lake east of Goldshire in Elwynn Forest, where to fish from 1 to 75"] = "Le lac de Cristal à l'est de Comté-de-l'Or dans la forêt d'Elwynn, où pêcher de 1 à 75",
  ["If you haven't learned Fishing yet, learn it from {n:0::Paxton Ganter} at Iceflow Lake."] = "Si tu n'as pas encore appris la Pêche, apprends-la auprès de {n:0::Paxton Ganter} au lac Iceflow.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Gretta Ganter} at Iceflow Lake. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Achète {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} auprès de {n:0::Gretta Ganter} au lac Iceflow. Achète aussi une {i:6256:inv_fishingpole_02:Fishing Pole} et un {i:6529:inv_misc_orb_03:Shiny Bauble} là-bas. (Achète tous les {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que tu vois et garde-les pour plus tard.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Iceflow Lake until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Équipe ta canne à pêche, fixe-y un {i:6529:inv_misc_orb_03:Shiny Bauble}, et pêche dans le lac Iceflow jusqu'à ce que ta compétence de Pêche atteigne 75. Tu attraperas environ 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} et 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Paxton Ganter}, it requires level 10."] = "Apprends Pêche (Compagnon) auprès de {n:0::Paxton Ganter}, ça demande le niveau 10.",
  ["Iceflow Lake in Dun Morogh, where to fish from 1 to 75"] = "Le lac Iceflow à Dun Morogh, où pêcher de 1 à 75",
  ["Learn Fishing from {n:0::Astaia} in Darnassus. There is no Fishing trainer in Dolanaar."] = "Apprends la Pêche auprès de {n:0::Astaia} à Darnassus. Il n'y a pas de maître de Pêche à Dolanaar.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Nyoma} in Dolanaar."] = "Achète {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} et {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} auprès de {n:0::Nyoma} à Dolanaar.",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} from {n:0::Narret Shadowgrove} in Dolanaar. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Achète une {i:6256:inv_fishingpole_02:Fishing Pole} et un {i:6529:inv_misc_orb_03:Shiny Bauble} auprès de {n:0::Narret Shadowgrove} à Dolanaar. (Achète tous les {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que tu vois et garde-les pour plus tard.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Lake Al'Ameth, south of Dolanaar, until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Équipe ta canne à pêche, fixe-y un {i:6529:inv_misc_orb_03:Shiny Bauble}, et pêche dans le lac Al'Ameth, au sud de Dolanaar, jusqu'à ce que ta compétence de Pêche atteigne 75. Tu attraperas environ 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} et 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Astaia} in Darnassus, it requires level 10."] = "Apprends Pêche (Compagnon) auprès de {n:0::Astaia} à Darnassus, ça demande le niveau 10.",
  ["Lake Al'Ameth south of Dolanaar in Teldrassil, where to fish from 1 to 75"] = "Le lac Al'Ameth au sud de Dolanaar à Teldrassil, où pêcher de 1 à 75",
  ["When you get to Stormwind City, buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Tharynn Bouden} in Goldshire, right outside the city."] = "Quand tu arrives à Hurlevent, achète {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} et {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} auprès de {n:0::Tharynn Bouden} à Comté-de-l'Or, juste à l'extérieur de la ville.",
  ["Fishing (75-130) and Cooking (1-100)"] = "Pêche (75-130) et Cuisine (1-100)",
  ["Fishing"] = "Pêche",
  ["Fish in the capital city closest to you until your Fishing skill reaches 130. From 75 no fish gets away in any of them. You should catch about 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Pêche dans la capitale la plus proche jusqu'à ce que ta compétence de Pêche atteigne 130. À partir de 75, aucun poisson ne s'échappe dans aucune d'elles. Tu devrais attraper environ 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} et 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["{b}Thunder Bluff:{/b} the pond near the Auction House."] = "{b}Les Pitons-du-Tonnerre :{/b} l'étang près de l'hôtel des ventes.",
  ["{b}Undercity:{/b} the canals. About a third of what you catch here is junk, so you get fewer fish."] = "{b}Fossoyeuse :{/b} les canaux. Environ un tiers de ce que tu y attrapes est des déchets, tu obtiens donc moins de poissons.",
  ["{b}Orgrimmar:{/b} the pond in the Valley of Honor, where the Fishing trainer stands."] = "{b}Orgrimmar :{/b} l'étang de la vallée de l'Honneur, où se trouve le maître de Pêche.",
  ["Recipes to buy"] = "Recettes à acheter",
  ["Buy {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} from {n:0::Naal Mistrunner} in Thunder Bluff or {n:0::Ronald Burch} in Undercity, you need it in the next part."] = "Achète {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} auprès de {n:0::Naal Mistrunner} aux Pitons-du-Tonnerre ou de {n:0::Ronald Burch} à Fossoyeuse, tu en as besoin dans la partie suivante.",
  ["If you don't have {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} yet, buy it from {n:0::Naal Mistrunner} in Thunder Bluff or {n:0::Lizbeth Cromwell} in Undercity."] = "Si tu n'as pas encore {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}, achète-la auprès de {n:0::Naal Mistrunner} aux Pitons-du-Tonnerre ou de {n:0::Lizbeth Cromwell} à Fossoyeuse.",
  ["Nobody sells them in Orgrimmar, so buy them on the Auction House or in Thunder Bluff."] = "Personne ne les vend à Orgrimmar, achète-les donc à l'hôtel des ventes ou aux Pitons-du-Tonnerre.",
  ["Cooking"] = "Cuisine",
  ["If you haven't learned Cooking yet, learn it from {n:0::Aska Mistrunner} in Thunder Bluff, {n:0::Eunice Burch} in Undercity or {n:0::Zamja} in Orgrimmar. Then learn {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and cook all your {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} into {s:7751:inv_misc_fish_07:Brilliant Smallfish}. If you caught {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel} in your starting zone, learn {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} and cook them into {s:7752:inv_misc_fish_24:Slitherskin Mackerel} instead. This should take your Cooking skill to 50."] = "Si tu n'as pas encore appris la Cuisine, apprends-la auprès de {n:0::Aska Mistrunner} aux Pitons-du-Tonnerre, {n:0::Eunice Burch} à Fossoyeuse ou {n:0::Zamja} à Orgrimmar. Ensuite, apprends {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} et cuisine tous tes {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} en {s:7751:inv_misc_fish_07:Brilliant Smallfish}. Si tu as attrapé des {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel} dans ta zone de départ, apprends plutôt {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} et cuisine-les en {s:7752:inv_misc_fish_24:Slitherskin Mackerel}. Ça devrait faire monter ta Cuisine à 50.",
  ["If you are a few points short of 50, catch and cook a few more."] = "S'il te manque quelques points pour 50, pêches-en et cuisines-en quelques-uns de plus.",
  ["Learn Journeyman Cooking from the same trainer. Then learn {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} and cook all your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Your Cooking skill should go above 100."] = "Apprends Cuisine (Compagnon) auprès du même maître. Ensuite, apprends {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} et cuisine tous tes {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} en {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Ta Cuisine devrait dépasser 100.",
  ["Don't worry if you don't reach 100 Cooking with Longjaw Mud Snapper, you will catch more Raw Longjaw Mud Snapper later."] = "Ne t'inquiète pas si tu n'atteins pas 100 en Cuisine avec le Longjaw Mud Snapper, tu attraperas d'autres Raw Longjaw Mud Snapper plus tard.",
  ["Fish in the canals of Stormwind City until your skill reaches 130. You should catch about 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, and 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Pêche dans les canaux de Hurlevent jusqu'à ce que ta compétence atteigne 130. Tu devrais attraper environ 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} et 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["Find {n:0::Catherine Leland} in Stormwind City and buy {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}. If you don't have {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} yet, buy it from {n:0::Tharynn Bouden} in Goldshire."] = "Trouve {n:0::Catherine Leland} à Hurlevent et achète {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}. Si tu n'as pas encore {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}, achète-la auprès de {n:0::Tharynn Bouden} à Comté-de-l'Or.",
  ["You should also find {n:0::Ben Trias} and buy 20 {i:8932:inv_misc_food_37:Alterac Swiss} from him. You will need these later for the Artisan Cooking quest."] = "Trouve aussi {n:0::Ben Trias} et achète-lui 20 {i:8932:inv_misc_food_37:Alterac Swiss}. Tu en auras besoin plus tard pour la quête de Cuisine (Artisan).",
  ["Learn Cooking from {n:0::Stephen Ryback} if you haven't yet. Then learn {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and cook all your {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} into {s:7751:inv_misc_fish_07:Brilliant Smallfish}. This should take your Cooking skill to 50."] = "Apprends la Cuisine auprès de {n:0::Stephen Ryback} si ce n'est pas déjà fait. Ensuite, apprends {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} et cuisine tous tes {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} en {s:7751:inv_misc_fish_07:Brilliant Smallfish}. Ça devrait faire monter ta Cuisine à 50.",
  ["Learn Journeyman Cooking from {n:0::Stephen Ryback} in Stormwind City. Then learn {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} and cook all your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Your Cooking skill should go above 100."] = "Apprends Cuisine (Compagnon) auprès de {n:0::Stephen Ryback} à Hurlevent. Ensuite, apprends {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} et cuisine tous tes {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} en {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Ta Cuisine devrait dépasser 100.",
  ["Fishing (130-205) and Cooking (100-175)"] = "Pêche (130-205) et Cuisine (100-175)",
  ["Expert Fishing needs {b}level 20{/b} and {b}Fishing 125{/b}, Expert Cooking needs {b}Cooking 125{/b}."] = "Pêche (Expert) demande {b}niveau 20{/b} et {b}Pêche 125{/b}, Cuisine (Expert) demande {b}Cuisine 125{/b}.",
  ["Booty Bay"] = "Baie-du-Butin",
  ["Go to Ratchet in The Barrens and take the boat to Booty Bay in Stranglethorn Vale."] = "Va à Cabestan dans les Tarides et prends le bateau pour Baie-du-Butin, dans la vallée de Strangleronce.",
  ["Find {n:0::Old Man Heming} in Booty Bay, buy {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} from him and read it."] = "Trouve {n:0::Old Man Heming} à Baie-du-Butin, achète-lui {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} et lis-le.",
  ["Find {n:0::Kelsey Yance} and buy these two recipes: {i:17062:inv_scroll_03:Recipe: Mithril Head Trout}, {i:13941:inv_scroll_03:Recipe: Filet of Redgill}."] = "Trouve {n:0::Kelsey Yance} et achète ces deux recettes : {i:17062:inv_scroll_03:Recipe: Mithril Head Trout}, {i:13941:inv_scroll_03:Recipe: Filet of Redgill}.",
  ["Go back to The Barrens, then fly from Ratchet to Sun Rock Retreat in Stonetalon Mountains and buy 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0::Kulwia}. You need 2 until 150, keep the other 5 for later."] = "Retourne dans les Tarides, puis prends le vol de Cabestan jusqu'à la retraite du Roc-Soleil, dans les Serres-Rocheuses, et achète 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} auprès de {n:0::Kulwia}. Il t'en faut 2 jusqu'à 150, garde les 5 autres pour plus tard.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the open water until your Fishing skill reaches 205. You will catch about 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Fixe un {i:6530:inv_misc_monstertail_03:Nightcrawler} et pêche en eau libre jusqu'à ce que ta compétence de Pêche atteigne 205. Tu attraperas environ 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} et 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["Fly to Shadowprey Village in Desolace."] = "Prends le vol jusqu'au village de Shadowprey, en Désolace.",
  ["Find {n:0::Wulan} and buy the {i:16072:inv_misc_book_08:Expert Cookbook}. He is on the top floor of the eastern-most building in the village."] = "Trouve {n:0::Wulan} et achète l'{i:16072:inv_misc_book_08:Expert Cookbook}. Il se trouve au dernier étage du bâtiment le plus à l'est du village.",
  ["Buy 20 {i:8932:inv_misc_food_37:Alterac Swiss} from {n:0::Innkeeper Sikewa}. You will need them for the Artisan Cooking quest."] = "Achète 20 {i:8932:inv_misc_food_37:Alterac Swiss} auprès de {n:0::Innkeeper Sikewa}. Tu en auras besoin pour la quête de Cuisine (Artisan).",
  ["Leveling Cooking to 175"] = "Monter la Cuisine jusqu'à 175",
  ["Cook your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper} if your Cooking skill is still below 100."] = "Cuisine tes {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} en {s:7753:inv_misc_fish_32:Longjaw Mud Snapper} si ta Cuisine est encore en dessous de 100.",
  ["{b}Read the {i:16072:inv_misc_book_08:Expert Cookbook} as soon as you reach 125{/b}, especially if you go AFK while cooking. Without it you stop getting skill points at 150 and keep cooking for nothing."] = "{b}Lis l'{i:16072:inv_misc_book_08:Expert Cookbook} dès que tu atteins 125{/b}, surtout si tu pars en AFK pendant la cuisine. Sans lui, tu ne gagnes plus de points de compétence à 150 et tu continues à cuisiner pour rien.",
  ["Learn {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} and cook all your {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} into {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}. Your Cooking skill will hopefully get close to 175."] = "Apprends {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} et cuisine tous tes {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} en {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}. Ta Cuisine devrait normalement approcher 175.",
  ["Don't worry if you don't reach 175 Cooking with Bristle Whisker Catfish, you will catch more Raw Bristle Whisker Catfish later."] = "Ne t'inquiète pas si tu n'atteins pas 175 en Cuisine avec le Bristle Whisker Catfish, tu attraperas d'autres Raw Bristle Whisker Catfish plus tard.",
  ["Go to Booty Bay in Stranglethorn Vale."] = "Va à Baie-du-Butin, dans la vallée de Strangleronce.",
  ["Go to The Barrens, then fly from Ratchet to Astranaar in Ashenvale. Ride south-east to Mystral Lake and buy the {i:16072:inv_misc_book_08:Expert Cookbook} and 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0::Shandrina}. You need 2 until 150, keep the other 5 for later."] = "Va dans les Tarides, puis prends le vol de Cabestan jusqu'à Astranaar, en Orneval. Chevauche vers le sud-est jusqu'au lac Mystral et achète l'{i:16072:inv_misc_book_08:Expert Cookbook} et 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} auprès de {n:0::Shandrina}. Il t'en faut 2 jusqu'à 150, garde les 5 autres pour plus tard.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the open water of Mystral Lake until your Fishing skill reaches 205. You will catch about 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Fixe un {i:6530:inv_misc_monstertail_03:Nightcrawler} et pêche en eau libre dans le lac Mystral jusqu'à ce que ta compétence de Pêche atteigne 205. Tu attraperas environ 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} et 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["Artisan Fishing Quest"] = "Quête de Pêche (Artisan)",
  ["If you have no {i:6530:inv_misc_monstertail_03:Nightcrawlers} left, buy 5 from {n:0::Kilxx} in The Barrens or {n:0:alliance:Helenia Olden} in Dustwallow Marsh."] = "S'il ne te reste plus de {i:6530:inv_misc_monstertail_03:Nightcrawlers}, achètes-en 5 auprès de {n:0::Kilxx} dans les Tarides ou de {n:0:alliance:Helenia Olden} dans le marécage d'Âprefange.",
  ["Go to Dustwallow Marsh and {b}fish anywhere in the swamp until your skill reaches 225{/b}. {b}Don't fish in the ocean.{/b} Keep a {i:6530:inv_misc_monstertail_03:Nightcrawler} on your pole until 225, otherwise a few fish get away."] = "Va dans le marécage d'Âprefange et {b}pêche n'importe où dans le marais jusqu'à ce que ta compétence atteigne 225{/b}. {b}Ne pêche pas dans l'océan.{/b} Garde un {i:6530:inv_misc_monstertail_03:Nightcrawler} sur ta canne jusqu'à 225, sinon quelques poissons s'échappent.",
  ["Find {n:0::Nat Pagle} and accept the quest {q:6607::Nat Pagle, Angler Extreme}. It requires {b}level 35{/b} and {b}Fishing 225{/b}, and you need it to learn Artisan Fishing."] = "Trouve {n:0::Nat Pagle} et accepte la quête {q:6607::Nat Pagle, Angler Extreme}. Elle demande {b}niveau 35{/b} et {b}Pêche 225{/b}, et tu en as besoin pour apprendre Pêche (Artisan).",
  ["Tidefury Cove, Dustwallow Marsh"] = "Tidefury Cove, marécage d'Âprefange",
  ["To complete the quest you have to catch 4 quest fish in four different zones:"] = "Pour terminer la quête, tu dois attraper 4 poissons de quête dans quatre zones différentes :",
  ["{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Feralas (attach the {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you kept, or {i:6532:inv_misc_gem_variety_02:Bright Baubles} from {n:0::Sheendra Tallgrass} / {n:0::Vivianna} in Feralas, otherwise most of them get away)"] = "{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Féralas (fixe l'{i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} que tu as gardé, ou des {i:6532:inv_misc_gem_variety_02:Bright Baubles} de {n:0::Sheendra Tallgrass} / {n:0::Vivianna} à Féralas, sinon la plupart s'échappent)",
  ["{i:16970:inv_misc_fish_21:Misty Reed Mahi Mahi} - Swamp of Sorrows"] = "{i:16970:inv_misc_fish_21:Misty Reed Mahi Mahi} - marais des Chagrins",
  ["{i:16968:inv_misc_fish_32:Sar'theris Striker} - Desolace"] = "{i:16968:inv_misc_fish_32:Sar'theris Striker} - Désolace",
  ["{i:16969:inv_misc_fish_08:Savage Coast Blue Sailfin} - Stranglethorn Vale"] = "{i:16969:inv_misc_fish_08:Savage Coast Blue Sailfin} - vallée de Strangleronce",
  ["Nat Pagle, Angler Extreme Quest Fishes"] = "Poissons de la quête Nat Pagle, Angler Extreme",
  ["Where to catch the four Nat Pagle quest fish"] = "Où attraper les quatre poissons de la quête de Nat Pagle",
  ["Leveling Fishing to 255 and Cooking to 225"] = "Monter la Pêche jusqu'à 255 et la Cuisine jusqu'à 225",
  ["After you completed the quest, {b}keep fishing in the swamp in Dustwallow Marsh until your Fishing skill reaches 255.{/b} {b}Don't fish in the ocean{/b}, because there you catch Raw Rockscale Cod instead of the Raw Mithril Head Trout you cook next."] = "Une fois la quête terminée, {b}continue à pêcher dans le marais du marécage d'Âprefange jusqu'à ce que ta compétence de Pêche atteigne 255.{/b} {b}Ne pêche pas dans l'océan{/b}, car tu y attrapes du Raw Rockscale Cod au lieu de la Raw Mithril Head Trout que tu cuisines ensuite.",
  ["Go back to Brackenwall Village (Horde) / Theramore Isle (Alliance) to cook your fish, or put down a campfire if you have one."] = "Retourne au village de Mur-de-Fougères (Horde) / sur l'île de Theramore (Alliance) pour cuisiner ton poisson, ou pose un feu de camp si tu en as un.",
  ["Cook your {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} into {s:7755:inv_misc_fish_30:Bristle Whisker Catfish} if your Cooking skill is still below 175."] = "Cuisine tes {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} en {s:7755:inv_misc_fish_30:Bristle Whisker Catfish} si ta Cuisine est encore en dessous de 175.",
  ["Learn {i:17062:inv_scroll_03:Recipe: Mithril Head Trout} and cook your {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} into {s:20916:inv_misc_fish_02:Mithril Headed Trout} until 225. Keep the rest, you cook them after the Artisan Cooking quest."] = "Apprends {i:17062:inv_scroll_03:Recipe: Mithril Head Trout} et cuisine tes {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} en {s:20916:inv_misc_fish_02:Mithril Headed Trout} jusqu'à 225. Garde le reste, tu le cuisines après la quête de Cuisine (Artisan).",
  ["Artisan Cooking Quest"] = "Quête de Cuisine (Artisan)",
  ["Fly to Gadgetzan in Tanaris and pick up the quest {q:6610::Clamlette Surprise} from {n:0::Dirge Quikcleave}. The reward is Artisan Cooking. The quest requires {b}level 35{/b} and {b}Cooking 225{/b}. You will need these to complete the quest:"] = "Prends le vol jusqu'à Gadgetzan, à Tanaris, et prends la quête {q:6610::Clamlette Surprise} auprès de {n:0::Dirge Quikcleave}. La récompense est Cuisine (Artisan). La quête demande {b}niveau 35{/b} et {b}Cuisine 225{/b}. Il te faudra ceci pour la terminer :",
  ["12x {i:12207:inv_egg_03:Giant Egg} - dropped by the {n:5428::Rocs}, {n:5429::Fire Rocs} and {n:5430::Searing Rocs} in Tanaris."] = "12x {i:12207:inv_egg_03:Giant Egg} - butin des {n:5428::Rocs}, {n:5429::Fire Rocs} et {n:5430::Searing Rocs} à Tanaris.",
  ["10x {i:7974:inv_misc_food_51:Zesty Clam Meat} - from Big-mouth Clams, dropped by {n:14123::Steeljaw Snappers} and {n:5431::Surf Gliders} in Tanaris."] = "10x {i:7974:inv_misc_food_51:Zesty Clam Meat} - dans les Big-mouth Clams, butin des {n:14123::Steeljaw Snappers} et des {n:5431::Surf Gliders} à Tanaris.",
  ["20x {i:8932:inv_misc_food_37:Alterac Swiss} - you bought these earlier."] = "20x {i:8932:inv_misc_food_37:Alterac Swiss} - tu les as achetés plus tôt.",
  ["Find {n:0::Gikkix} at Steamwheedle Port in Tanaris and buy {i:13945:inv_scroll_03:Recipe: Nightfin Soup}."] = "Trouve {n:0::Gikkix} à Port Gentepression, à Tanaris, et achète {i:13945:inv_scroll_03:Recipe: Nightfin Soup}.",
  ["Fishing to 300 in Feralas"] = "Pêche jusqu'à 300 à Féralas",
  ["Fly to Camp Mojache (Horde) / Feathermoon Stronghold (Alliance) in Feralas."] = "Prends le vol jusqu'au camp Mojache (Horde) / au bastion de Plumelune (Alliance), à Féralas.",
  ["Buy 12 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0:horde:Sheendra Tallgrass} / {n:0:alliance:Vivianna}."] = "Achète 12 {i:6530:inv_misc_monstertail_03:Nightcrawlers} auprès de {n:0:horde:Sheendra Tallgrass} / {n:0:alliance:Vivianna}.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the marked lake until you reach Fishing 300, use a new one every 10 minutes. Any other lake or river in Feralas works too, {b}except Jademir Lake{/b}."] = "Fixe un {i:6530:inv_misc_monstertail_03:Nightcrawler} et pêche dans le lac marqué jusqu'à atteindre Pêche 300, utilises-en un nouveau toutes les 10 minutes. N'importe quel autre lac ou rivière de Féralas fonctionne aussi, {b}sauf le lac Jademir{/b}.",
  ["Where to fish in Feralas from 255 to 300"] = "Où pêcher à Féralas de 255 à 300",
  ["Leveling Cooking to 300"] = "Monter la Cuisine jusqu'à 300",
  ["Cook your remaining {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} into {s:20916:inv_misc_fish_02:Mithril Headed Trout} until 250."] = "Cuisine tes {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} restantes en {s:20916:inv_misc_fish_02:Mithril Headed Trout} jusqu'à 250.",
  ["Learn {i:13941:inv_scroll_03:Recipe: Filet of Redgill} and cook your {i:13758:inv_misc_fish_06:Raw Redgill} into {s:18241:inv_misc_fish_06:Filet of Redgill} until 285."] = "Apprends {i:13941:inv_scroll_03:Recipe: Filet of Redgill} et cuisine tes {i:13758:inv_misc_fish_06:Raw Redgill} en {s:18241:inv_misc_fish_06:Filet of Redgill} jusqu'à 285.",
  ["Learn {i:13945:inv_scroll_03:Recipe: Nightfin Soup} and cook all your {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} into {s:18243:inv_drink_17:Nightfin Soup}. You also need a {i:159:inv_drink_07:Refreshing Spring Water} for each soup, buy 20 from the innkeeper."] = "Apprends {i:13945:inv_scroll_03:Recipe: Nightfin Soup} et cuisine tous tes {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} en {s:18243:inv_drink_17:Nightfin Soup}. Il te faut aussi une {i:159:inv_drink_07:Refreshing Spring Water} par soupe, achètes-en 20 à l'aubergiste.",
  ["{i:13759:inv_misc_fish_23:Raw Nightfin Snapper} don't bite in the afternoon (12:00-18:00 game time). If you fished in the afternoon, you will probably not have enough, so cook the rest of your {i:13758:inv_misc_fish_06:Raw Redgill} into {s:18241:inv_misc_fish_06:Filet of Redgill} too, you might reach 300 with them."] = "Les {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} ne mordent pas l'après-midi (12h00-18h00, heure du jeu). Si tu as pêché l'après-midi, tu n'en auras probablement pas assez, alors cuisine aussi le reste de tes {i:13758:inv_misc_fish_06:Raw Redgill} en {s:18241:inv_misc_fish_06:Filet of Redgill}, tu pourrais atteindre 300 avec.",
  ["If you still don't reach 300, fish a bit more outside the afternoon, or buy a few {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} on the Auction House."] = "Si tu n'atteins toujours pas 300, pêche encore un peu en dehors de l'après-midi, ou achète quelques {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} à l'hôtel des ventes.",
  ["This WoW Forever Cooking leveling guide will show you the fastest way to level your Cooking skill from 1 to 300 as cheaply as possible. You will also find every trainer location, how the campfire works in Forever and where to train Cooking past 150 and 225."] = "Ce guide de montée en Cuisine pour WoW Forever te montre la façon la plus rapide de monter ta compétence de Cuisine de 1 à 300 pour le moins cher possible. Tu y trouveras aussi l'emplacement de chaque maître, le fonctionnement du feu de camp dans Forever et où apprendre la Cuisine au-delà de 150 et 225.",
  ["Cooking doesn't take up one of your two profession slots, so every character can learn it. Most of the recipes below only need the meat or fish that drops while you level, so the guide lists a few recipes for every skill range and you can make the one you have the ingredients for. If you also want to level Fishing but haven't leveled it yet, use my Fishing and Cooking leveling guide instead:"] = "La Cuisine n'occupe pas l'un de tes deux emplacements de métier, chaque personnage peut donc l'apprendre. La plupart des recettes ci-dessous ne demandent que la viande ou le poisson que tu ramasses en montant de niveau, le guide liste donc quelques recettes par palier de compétence et tu peux faire celle dont tu as les ingrédients. Si tu veux aussi monter la Pêche mais que tu ne l'as pas encore montée, utilise plutôt mon guide de montée en Pêche et Cuisine :",
  ["You need level 35 to go past 225, so I split the list in two. Buy this part first."] = "Il te faut le niveau 35 pour dépasser 225, j'ai donc séparé la liste en deux. Achète d'abord cette partie.",
  ["The Giant Eggs and the Zesty Clam Meat are for the Artisan Cooking quest."] = "Les Giant Egg et la Zesty Clam Meat sont pour la quête de Cuisine (Artisan).",
  ["Cooking Trainer Locations"] = "Emplacements des maîtres de Cuisine",
  ["Apprentice Cooking has no level requirement, so you can learn it on a fresh character. Every trainer also teaches Journeyman Cooking, so you don't have to find a different trainer at 50."] = "La Cuisine (Apprenti) n'a aucun niveau requis, tu peux donc l'apprendre sur un personnage tout neuf. Chaque maître enseigne aussi Cuisine (Compagnon), tu n'as donc pas à chercher un autre maître à 50.",
  ["Orgrimmar: {n:0:horde:Zamja}"] = "Orgrimmar : {n:0:horde:Zamja}",
  ["Undercity: {n:0:horde:Eunice Burch}"] = "Fossoyeuse : {n:0:horde:Eunice Burch}",
  ["Thunder Bluff: {n:0:horde:Aska Mistrunner}"] = "Les Pitons-du-Tonnerre : {n:0:horde:Aska Mistrunner}",
  ["Every starting zone has a Cooking trainer, most of them are inside the inn."] = "Chaque zone de départ a un maître de Cuisine, la plupart sont dans l'auberge.",
  ["{n:0:horde:Cook Torka} in Razor Hill"] = "{n:0:horde:Cook Torka} à Tranchecolline",
  ["{n:0:horde:Pyall Silentstride} inside the big tent in Bloodhoof Village"] = "{n:0:horde:Pyall Silentstride} dans la grande tente du village de Sabot-de-Sang",
  ["{n:0:horde:William Pickman} inside the inn in Brill"] = "{n:0:horde:William Pickman} dans l'auberge de Brill",
  ["{n:0::Nyalah Brightfire} in Valanaar, {n:0::Zerril Softbreeze} in Shen'dar Village"] = "{n:0::Nyalah Brightfire} à Valanaar, {n:0::Zerril Softbreeze} au village de Shen'dar",
  ["Stormwind City: {n:0:alliance:Stephen Ryback}"] = "Hurlevent : {n:0:alliance:Stephen Ryback}",
  ["Ironforge: {n:0:alliance:Daryl Riknussun}"] = "Forgefer : {n:0:alliance:Daryl Riknussun}",
  ["Darnassus: {n:0:alliance:Alegorn}"] = "Darnassus : {n:0:alliance:Alegorn}",
  ["{n:0:alliance:Tomas} in the kitchen of the inn in Goldshire"] = "{n:0:alliance:Tomas} dans la cuisine de l'auberge de Comté-de-l'Or",
  ["{n:0:alliance:Gremlock Pilsnor} in the Thunderbrew Distillery in Kharanos"] = "{n:0:alliance:Gremlock Pilsnor} dans la distillerie Brasse-Tonnerre à Kharanos",
  ["{n:0:alliance:Zarrin} in Dolanaar"] = "{n:0:alliance:Zarrin} à Dolanaar",
  ["You can find every Cooking trainer for Horde and Alliance on my WoW Forever Cooking Trainers page."] = "Tu trouveras tous les maîtres de Cuisine de la Horde et de l'Alliance sur ma page WoW Forever Cooking Trainers.",
  ["Campfire"] = "Feu de camp",
  ["You need a campfire to cook. There is often one burning next to the Cooking trainer, so look around before you make your own."] = "Il te faut un feu de camp pour cuisiner. Il y en a souvent un qui brûle à côté du maître de Cuisine, alors regarde autour de toi avant de faire le tien.",
  ["In Forever the campfire is an item. You learn the {s:1229737:inv_camelot_camping_welcomingcampfire:Basic Campfire Kit} together with Cooking and place the fire from your bags, so you can make a stack of kits in advance. Other players can add their own camp items to your fire, you can read about the whole camping system in my WoW Forever Camping Guide."] = "Dans Forever, le feu de camp est un objet. Tu apprends le {s:1229737:inv_camelot_camping_welcomingcampfire:Basic Campfire Kit} en même temps que la Cuisine et tu poses le feu depuis tes sacs, tu peux donc préparer une pile de kits à l'avance. Les autres joueurs peuvent ajouter leurs propres objets de camp à ton feu, tu peux lire tout le système de camping dans mon WoW Forever Camping Guide.",
  ["To craft the kits you need {i:4470:inv_tradeskillitem_01:Simple Wood} and a {i:4471:inv_stone_11:Flint and Tinder}. The Flint and Tinder is only for crafting the kits, you don't need it to place the fire. Open your faction below to see who sells them near your trainer:"] = "Pour fabriquer les kits, il te faut du {i:4470:inv_tradeskillitem_01:Simple Wood} et un {i:4471:inv_stone_11:Flint and Tinder}. Le silex et amadou ne sert qu'à fabriquer les kits, tu n'en as pas besoin pour poser le feu. Ouvre ta faction ci-dessous pour voir qui les vend près de ton maître :",
  ["{n:0:horde:Xen'to}, next to the trainer"] = "{n:0:horde:Xen'to}, à côté du maître",
  ["{n:0:horde:Ronald Burch}, next to the trainer"] = "{n:0:horde:Ronald Burch}, à côté du maître",
  ["{n:0:horde:Naal Mistrunner}, next to the trainer"] = "{n:0:horde:Naal Mistrunner}, à côté du maître",
  ["{n:0:horde:Jark} in the Razor Hill barracks"] = "{n:0:horde:Jark} dans la caserne de Tranchecolline",
  ["{n:0:horde:Moorat Longstride} in Bloodhoof Village"] = "{n:0:horde:Moorat Longstride} au village de Sabot-de-Sang",
  ["{n:0:horde:Mrs. Winters} in Brill"] = "{n:0:horde:Mrs. Winters} à Brill",
  ["{n:0::Antelariaa Cloudgaze} in Valanaar {n:0::Zerril Softbreeze}, the Cooking trainer in Shen'dar Village"] = "{n:0::Antelariaa Cloudgaze} à Valanaar {n:0::Zerril Softbreeze}, le maître de Cuisine du village de Shen'dar",
  ["{n:0:alliance:Erika Tate}, next to the trainer"] = "{n:0:alliance:Erika Tate}, à côté du maître",
  ["{n:0:alliance:Emrul Riknussun}, next to the trainer"] = "{n:0:alliance:Emrul Riknussun}, à côté du maître",
  ["{n:0:alliance:Fyldan}, next to the trainer"] = "{n:0:alliance:Fyldan}, à côté du maître",
  ["{n:0:alliance:Brog Hamfist} in Goldshire"] = "{n:0:alliance:Brog Hamfist} à Comté-de-l'Or",
  ["{n:0:alliance:Kreg Bilmn} in the Thunderbrew Distillery"] = "{n:0:alliance:Kreg Bilmn} dans la distillerie Brasse-Tonnerre",
  ["{n:0:alliance:Nyoma} in Dolanaar"] = "{n:0:alliance:Nyoma} à Dolanaar",
  ["Apprentice Cooking (1-50)"] = "Cuisine (Apprenti) (1-50)",
  ["{b}These are sold by Cooking Supply vendors near your trainer, don't buy them from the Auction House:{/b}"] = "{b}Ceux-ci sont vendus par les marchands de fournitures de cuisine près de ton maître, ne les achète pas à l'hôtel des ventes :{/b}",
  ["Make around 55 from one of these recipes. The two fish are usually the cheapest."] = "Fais-en environ 55 avec l'une de ces recettes. Les deux poissons sont généralement les moins chers.",
  ["Food"] = "Nourriture",
  ["Ingredients"] = "Ingrédients",
  ["Recipe Source"] = "Source de la recette",
  ["Mulgore: {n:0:horde:Harn Longcast} Thunder Bluff: {n:0:horde:Sewa Mistrunner} Tirisfal Glades: {n:0:horde:Martine Tramblay} Undercity: {n:0:horde:Lizbeth Cromwell} Dun Morogh: {n:0:alliance:Gretta Ganter} Elwynn Forest: {n:0:alliance:Tharynn Bouden} Loch Modan: {n:0:alliance:Khara Deepwater} Stormwind City: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nyoma}"] = "Mulgore : {n:0:horde:Harn Longcast} Les Pitons-du-Tonnerre : {n:0:horde:Sewa Mistrunner} Clairières de Tirisfal : {n:0:horde:Martine Tramblay} Fossoyeuse : {n:0:horde:Lizbeth Cromwell} Dun Morogh : {n:0:alliance:Gretta Ganter} Forêt d'Elwynn : {n:0:alliance:Tharynn Bouden} Loch Modan : {n:0:alliance:Khara Deepwater} Hurlevent : {n:0:alliance:Catherine Leland} Teldrassil : {n:0:alliance:Nyoma}",
  ["Durotar: {n:0:horde:Zansoa} Tirisfal Glades: {n:0:horde:Martine Tramblay} Ironforge: {n:0:alliance:Tansy Puddlefizz} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone}"] = "Durotar : {n:0:horde:Zansoa} Clairières de Tirisfal : {n:0:horde:Martine Tramblay} Forgefer : {n:0:alliance:Tansy Puddlefizz} Teldrassil : {n:0:alliance:Nessa Shadowsong} Marche de l'Ouest : {n:0:alliance:Kriggon Talsone}",
  ["Trainer"] = "Maître",
  ["(Horde only) Make {s:15935:inv_misc_food_46:Crispy Bat Wing} if you have some {i:12223:inv_misc_pelt_bear_ruin_05:Meaty Bat Wing}. The recipe is sold by {n:0:horde:Abigail Shiel} in Tirisfal Glades."] = "(Horde uniquement) Fais des {s:15935:inv_misc_food_46:Crispy Bat Wing} si tu as des {i:12223:inv_misc_pelt_bear_ruin_05:Meaty Bat Wing}. La recette est vendue par {n:0:horde:Abigail Shiel} dans les clairières de Tirisfal.",
  ["(Horde only) Make {s:6413:inv_misc_food_10:Scorpid Surprise} if you have some {i:5466:spell_nature_nullifypoison:Scorpid Stinger}. The recipe is sold by {n:0:horde:Grimtak} in Durotar."] = "(Horde uniquement) Fais des {s:6413:inv_misc_food_10:Scorpid Surprise} si tu as des {i:5466:spell_nature_nullifypoison:Scorpid Stinger}. La recette est vendue par {n:0:horde:Grimtak} à Durotar.",
  ["(Alliance only) Make {s:6412:inv_misc_food_68:Kaldorei Spider Kabob} if you have some {i:5465:inv_misc_monsterspidercarapace_01:Small Spider Leg}. The recipe is a reward from {q:4161::Recipe of the Kaldorei}. You can get the quest from {n:0:alliance:Zarrin} in Teldrassil."] = "(Alliance uniquement) Fais des {s:6412:inv_misc_food_68:Kaldorei Spider Kabob} si tu as des {i:5465:inv_misc_monsterspidercarapace_01:Small Spider Leg}. La recette est une récompense de {q:4161::Recipe of the Kaldorei}. Tu peux obtenir la quête auprès de {n:0:alliance:Zarrin} à Teldrassil.",
  ["Journeyman Cooking (50-150)"] = "Cuisine (Compagnon) (50-150)",
  ["{b}Visit your trainer again and learn Journeyman Cooking{/b}, it requires Cooking 50."] = "{b}Retourne voir ton maître et apprends Cuisine (Compagnon){/b}, ça demande Cuisine 50.",
  ["{b}Make sure to learn Journeyman Cooking before you start the next part{/b}, especially if you go AFK while cooking. Without it you stop getting skill points at 75 and keep cooking for nothing."] = "{b}Veille à apprendre Cuisine (Compagnon) avant de commencer la partie suivante{/b}, surtout si tu pars en AFK pendant la cuisine. Sans elle, tu ne gagnes plus de points de compétence à 75 et tu continues à cuisiner pour rien.",
  ["Make around 55 from any of the recipes below. The two fish are usually the cheapest. {s:8607:inv_misc_food_13:Smoked Bear Meat} turns yellow sooner than the rest, so make more of it, or cook it first if you have more than one type of meat."] = "Fais-en environ 55 avec n'importe laquelle des recettes ci-dessous. Les deux poissons sont généralement les moins chers. La {s:8607:inv_misc_food_13:Smoked Bear Meat} devient jaune plus tôt que les autres, alors fais-en davantage, ou cuisine-la en premier si tu as plusieurs types de viande.",
  ["Mulgore: {n:0:horde:Harn Longcast} Silverpine Forest: {n:0:horde:Killian Sanatha} Thunder Bluff: {n:0:horde:Naal Mistrunner} Undercity: {n:0:horde:Lizbeth Cromwell} Elwynn Forest: {n:0:alliance:Tharynn Bouden} Ironforge: {n:0:alliance:Tansy Puddlefizz} Loch Modan: {n:0:alliance:Khara Deepwater} Teldrassil: {n:0:alliance:Nyoma}"] = "Mulgore : {n:0:horde:Harn Longcast} Forêt des Pins-Argentés : {n:0:horde:Killian Sanatha} Les Pitons-du-Tonnerre : {n:0:horde:Naal Mistrunner} Fossoyeuse : {n:0:horde:Lizbeth Cromwell} Forêt d'Elwynn : {n:0:alliance:Tharynn Bouden} Forgefer : {n:0:alliance:Tansy Puddlefizz} Loch Modan : {n:0:alliance:Khara Deepwater} Teldrassil : {n:0:alliance:Nyoma}",
  ["Durotar: {n:0:horde:Zansoa} Orgrimmar: {n:0:horde:Shankys} Silverpine Forest: {n:0:horde:Killian Sanatha} Undercity: {n:0:horde:Ronald Burch} Darkshore: {n:0:alliance:Heldan Galesong} Stormwind City: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone} Wetlands: {n:0:alliance:Stuart Fleming} The Barrens: {n:0::Kilxx}"] = "Durotar : {n:0:horde:Zansoa} Orgrimmar : {n:0:horde:Shankys} Forêt des Pins-Argentés : {n:0:horde:Killian Sanatha} Fossoyeuse : {n:0:horde:Ronald Burch} Sombrivage : {n:0:alliance:Heldan Galesong} Hurlevent : {n:0:alliance:Catherine Leland} Teldrassil : {n:0:alliance:Nessa Shadowsong} Marche de l'Ouest : {n:0:alliance:Kriggon Talsone} Les Paluns : {n:0:alliance:Stuart Fleming} Les Tarides : {n:0::Kilxx}",
  ["Silverpine Forest: {n:0:horde:Andrew Hilbert} Loch Modan: {n:0:alliance:Drac Roughcut}"] = "Forêt des Pins-Argentés : {n:0:horde:Andrew Hilbert} Loch Modan : {n:0:alliance:Drac Roughcut}",
  ["55x {i:5469:inv_misc_food_16:Strider Meat} 55x {i:4536:inv_misc_food_19:Shiny Red Apple} (Vendor)"] = "55x {i:5469:inv_misc_food_16:Strider Meat} 55x {i:4536:inv_misc_food_19:Shiny Red Apple} (Marchand)",
  ["The Barrens: {n:0:horde:Tari'qa} (Horde only) Reward from {q:2178::Easy Strider Living} (Alliance only)"] = "Les Tarides : {n:0:horde:Tari'qa} (Horde uniquement) Récompense de {q:2178::Easy Strider Living} (Alliance uniquement)",
  ["Make around 30-35 from one of these two."] = "Fais-en environ 30-35 avec l'une de ces deux recettes.",
  ["30x {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} (buy around 55, you will need 25 more at 130-150)"] = "30x {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} (achètes-en environ 55, il t'en faudra 25 de plus à 130-150)",
  ["Hillsbrad Foothills: {n:0:horde:Derak Nightfall} Thunder Bluff: {n:0:horde:Naal Mistrunner} Thunder Bluff: {n:0:horde:Sewa Mistrunner} Undercity: {n:0:horde:Ronald Burch} Hillsbrad Foothills: {n:0:alliance:Lindea Rabonne} Stormwind City: {n:0:alliance:Catherine Leland} The Barrens: {n:0::Kilxx}"] = "Contreforts de Hautebrande : {n:0:horde:Derak Nightfall} Les Pitons-du-Tonnerre : {n:0:horde:Naal Mistrunner} Les Pitons-du-Tonnerre : {n:0:horde:Sewa Mistrunner} Fossoyeuse : {n:0:horde:Ronald Burch} Contreforts de Hautebrande : {n:0:alliance:Lindea Rabonne} Hurlevent : {n:0:alliance:Catherine Leland} Les Tarides : {n:0::Kilxx}",
  ["Stormwind City: {n:0:alliance:Kendor Kabonka} (Alliance only)"] = "Hurlevent : {n:0:alliance:Kendor Kabonka} (Alliance uniquement)",
  ["Make around 20-25 from any of the recipes below."] = "Fais-en environ 20-25 avec n'importe laquelle des recettes ci-dessous.",
  ["See above"] = "Voir ci-dessus",
  ["Stormwind City: {n:0:alliance:Kendor Kabonka} (Alliance) Arathi Highlands: {n:0:horde:Keena} (Horde)"] = "Hurlevent : {n:0:alliance:Kendor Kabonka} (Alliance) Hautes-terres d'Arathi : {n:0:horde:Keena} (Horde)",
  ["The Barrens: {n:0:horde:Zargh} (Horde only)"] = "Les Tarides : {n:0:horde:Zargh} (Horde uniquement)",
  ["Expert Cooking (150-225)"] = "Cuisine (Expert) (150-225)",
  ["To learn Expert Cooking you need to reach Cooking 125, then buy the {i:16072:inv_misc_book_08:Expert Cookbook} from {n:0:horde:Wulan} (Horde) in Desolace at Shadowprey Village or from {n:0:alliance:Shandrina} (Alliance) in Ashenvale at Mystral Lake."] = "Pour apprendre Cuisine (Expert), tu dois atteindre Cuisine 125, puis acheter l'{i:16072:inv_misc_book_08:Expert Cookbook} auprès de {n:0:horde:Wulan} (Horde) au village de Shadowprey, en Désolace, ou de {n:0:alliance:Shandrina} (Alliance) au lac Mystral, en Orneval.",
  ["Make around 25-30 from one of these three."] = "Fais-en environ 25-30 avec l'une de ces trois recettes.",
  ["You can also keep making {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}, but it's green from 160, so you need around 90 of them for these 25 points."] = "Tu peux aussi continuer le {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}, mais il est vert dès 160, il t'en faut donc environ 90 pour ces 25 points.",
  ["Make around 55 from one of these. The Roast Raptor is usually the cheapest."] = "Fais-en environ 55 avec l'une de ces recettes. Le Roast Raptor est généralement le moins cher.",
  ["Arathi Highlands: {n:0:alliance:Hammon Karwn} Arathi Highlands: {n:0:horde:Keena} Dustwallow Marsh: {n:0:horde:Ogg'marr}"] = "Hautes-terres d'Arathi : {n:0:alliance:Hammon Karwn} Hautes-terres d'Arathi : {n:0:horde:Keena} Marécage d'Âprefange : {n:0:horde:Ogg'marr}",
  ["Ashenvale: {n:0:horde:Wik'Tar} Orgrimmar: {n:0:horde:Shankys} Stranglethorn Vale: {n:0::Kelsey Yance} Undercity: {n:0:horde:Lizbeth Cromwell} Ironforge: {n:0:alliance:Tansy Puddlefizz} Wetlands: {n:0:alliance:Stuart Fleming} Desolace: {n:0:horde:Wulan} Darkshore: {n:0:alliance:Heldan Galesong} Hillsbrad Foothills: {n:0:alliance:Lindea Rabonne}"] = "Orneval : {n:0:horde:Wik'Tar} Orgrimmar : {n:0:horde:Shankys} Vallée de Strangleronce : {n:0::Kelsey Yance} Fossoyeuse : {n:0:horde:Lizbeth Cromwell} Forgefer : {n:0:alliance:Tansy Puddlefizz} Les Paluns : {n:0:alliance:Stuart Fleming} Désolace : {n:0:horde:Wulan} Sombrivage : {n:0:alliance:Heldan Galesong} Contreforts de Hautebrande : {n:0:alliance:Lindea Rabonne}",
  ["Reward from a quest in Hillsbrad Foothills NPC: {n:0:horde:Christoph Jeffcoat}, quest: {q:7321::Soothing Turtle Bisque} NPC: {n:0:alliance:Chef Jessen}, quest: {q:555::Soothing Turtle Bisque}"] = "Récompense d'une quête dans les contreforts de Hautebrande PNJ : {n:0:horde:Christoph Jeffcoat}, quête : {q:7321::Soothing Turtle Bisque} PNJ : {n:0:alliance:Chef Jessen}, quête : {q:555::Soothing Turtle Bisque}",
  ["Artisan Cooking (225-300)"] = "Cuisine (Artisan) (225-300)",
  ["Artisan Cooking is the reward of the {q:6610::Clamlette Surprise} quest. You need {b}level 35{/b} and {b}Cooking 225{/b} for it."] = "Cuisine (Artisan) est la récompense de la quête {q:6610::Clamlette Surprise}. Il te faut {b}niveau 35{/b} et {b}Cuisine 225{/b} pour celle-ci.",
  ["Pick up the quest that sends you to Gadgetzan: Horde players take {q:6611::To Gadgetzan You Go!} from {n:0:horde:Zamja} in Orgrimmar, Alliance players take {q:6612::I Know A Guy...} from {n:0:alliance:Daryl Riknussun} in Ironforge."] = "Prends la quête qui t'envoie à Gadgetzan : les joueurs de la Horde prennent {q:6611::To Gadgetzan You Go!} auprès de {n:0:horde:Zamja} à Orgrimmar, les joueurs de l'Alliance prennent {q:6612::I Know A Guy...} auprès de {n:0:alliance:Daryl Riknussun} à Forgefer.",
  ["Collect 12x {i:12207:inv_egg_03:Giant Egg}, 10x {i:7974:inv_misc_food_51:Zesty Clam Meat} and 20x {i:8932:inv_misc_food_37:Alterac Swiss}. {b}Don't go to Gadgetzan before you have all of them{/b}, otherwise you make the trip twice."] = "Rassemble 12x {i:12207:inv_egg_03:Giant Egg}, 10x {i:7974:inv_misc_food_51:Zesty Clam Meat} et 20x {i:8932:inv_misc_food_37:Alterac Swiss}. {b}Ne va pas à Gadgetzan avant de tous les avoir{/b}, sinon tu feras le trajet deux fois.",
  ["Find {n:0::Dirge Quikcleave} in Gadgetzan, take Clamlette Surprise from him and hand in the three items. He teaches you Artisan Cooking on the spot. While you are in Tanaris, go to Steamwheedle Port and {b}buy {i:13939:inv_scroll_03:Recipe: Spotted Yellowtail} from {n:0::Gikkix}{/b}, you need it in the next step."] = "Trouve {n:0::Dirge Quikcleave} à Gadgetzan, prends-lui Clamlette Surprise et rends les trois objets. Il t'apprend Cuisine (Artisan) sur place. Tant que tu es à Tanaris, va à Port Gentepression et {b}achète {i:13939:inv_scroll_03:Recipe: Spotted Yellowtail} auprès de {n:0::Gikkix}{/b}, tu en as besoin à l'étape suivante.",
  ["Make around 140 from one of these two, buy the fish that is cheaper."] = "Fais-en environ 140 avec l'une de ces deux recettes, achète le poisson le moins cher.",
  ["Tanaris: {n:0::Gikkix}"] = "Tanaris : {n:0::Gikkix}",
  ["Stranglethorn Vale: {n:0::Kelsey Yance}"] = "Vallée de Strangleronce : {n:0::Kelsey Yance}",
  ["This WoW Forever First Aid leveling guide will show you the fastest way to level your First Aid skill from 1 to 300. You will also find every trainer location and where to train First Aid past 150 and 225."] = "Ce guide de montée en Secourisme pour WoW Forever te montre la façon la plus rapide de monter ta compétence de Secourisme de 1 à 300. Tu y trouveras aussi l'emplacement de chaque maître et où apprendre le Secourisme au-delà de 150 et 225.",
  ["First Aid does not take up one of your two profession slots, so every character can learn it. Bandages heal you between fights, and in Forever First Aid also makes the healing potions that used to be Alchemy recipes, so it's worth leveling on every character. Below you will find the shopping list, the First Aid trainers by starting zone and capital city, and the cheapest recipes for every skill range."] = "Le Secourisme n'occupe pas l'un de tes deux emplacements de métier, chaque personnage peut donc l'apprendre. Les bandages te soignent entre les combats, et dans Forever le Secourisme fabrique aussi les potions de soins qui étaient autrefois des recettes d'Alchimie : ça vaut donc le coup de le monter sur chaque personnage. Tu trouveras ci-dessous la liste de courses, les maîtres de Secourisme par zone de départ et capitale, et les recettes les moins chères pour chaque palier de compétence.",
  ["First Aid Trainer Locations"] = "Emplacements des maîtres de Secourisme",
  ["Apprentice First Aid has no level requirement, so you can learn it on a fresh character. Every trainer also teaches Journeyman First Aid, so you don't have to find a different trainer at 50."] = "Le Secourisme (Apprenti) n'a aucun niveau requis, tu peux donc l'apprendre sur un personnage tout neuf. Chaque maître enseigne aussi Secourisme (Compagnon), tu n'as donc pas à chercher un autre maître à 50.",
  ["Orgrimmar: {n:0:horde:Arnok}"] = "Orgrimmar : {n:0:horde:Arnok}",
  ["Undercity: {n:0:horde:Mary Edras}"] = "Fossoyeuse : {n:0:horde:Mary Edras}",
  ["Thunder Bluff: {n:0:horde:Pand Stonebinder}"] = "Les Pitons-du-Tonnerre : {n:0:horde:Pand Stonebinder}",
  ["Every starting zone has a First Aid trainer, most of them are inside the inn."] = "Chaque zone de départ a un maître de Secourisme, la plupart sont dans l'auberge.",
  ["{n:0:horde:Rawrk} in the barracks in Razor Hill"] = "{n:0:horde:Rawrk} dans la caserne de Tranchecolline",
  ["{n:0:horde:Vira Younghoof} inside the inn in Bloodhoof Village"] = "{n:0:horde:Vira Younghoof} dans l'auberge du village de Sabot-de-Sang",
  ["{n:0:horde:Nurse Neela} inside the inn in Brill"] = "{n:0:horde:Nurse Neela} dans l'auberge de Brill",
  ["{n:0::Melasa Fairmend} in Valanaar, {n:0::Naleeia Tattermend} in Shen'dar Village"] = "{n:0::Melasa Fairmend} à Valanaar, {n:0::Naleeia Tattermend} au village de Shen'dar",
  ["Stormwind City: {n:0:alliance:Shaina Fuller}"] = "Hurlevent : {n:0:alliance:Shaina Fuller}",
  ["Ironforge: {n:0:alliance:Nissa Firestone}"] = "Forgefer : {n:0:alliance:Nissa Firestone}",
  ["Darnassus: {n:0:alliance:Dannelor}"] = "Darnassus : {n:0:alliance:Dannelor}",
  ["{n:0:alliance:Michelle Belle} upstairs in the inn in Goldshire"] = "{n:0:alliance:Michelle Belle} à l'étage de l'auberge de Comté-de-l'Or",
  ["{n:0:alliance:Thamner Pol} in the Thunderbrew Distillery in Kharanos"] = "{n:0:alliance:Thamner Pol} dans la distillerie Brasse-Tonnerre à Kharanos",
  ["{n:0:alliance:Byancie} in Dolanaar, in the building north of the inn"] = "{n:0:alliance:Byancie} à Dolanaar, dans le bâtiment au nord de l'auberge",
  ["You can find every First Aid trainer for Horde and Alliance on my WoW Forever First Aid Trainers page."] = "Tu trouveras tous les maîtres de Secourisme de la Horde et de l'Alliance sur ma page WoW Forever First Aid Trainers.",
  ["Apprentice First Aid (1-75)"] = "Secourisme (Apprenti) (1-75)",
  ["If you have Linen Cloth or bought some, pick the {b}Bandages{/b} tab. If you bought herbs, pick the {b}Healing Potions{/b} tab."] = "Si tu as de l'étoffe de lin ou que tu en as acheté, choisis l'onglet {b}Bandages{/b}. Si tu as acheté des herbes, choisis l'onglet {b}Potions de soins{/b}.",
  ["Healing Potions"] = "Potions de soins",
  ["86x {s:1244431:inv_potion_49:Minor Healing Potion} - 86 Peacebloom, 86 Mild Spices, 86 Empty Vial"] = "86x {s:1244431:inv_potion_49:Minor Healing Potion} - 86 Pacifique, 86 Épices douces, 86 Fiole vide",
  ["{i:2678:inv_misc_food_wheat_02:Mild Spices} are sold by Cooking supply vendors, {i:3371:inv_potion_84:Empty Vial} by Alchemy supply vendors. Open your faction below to see who sells them near your trainer:"] = "Les {i:2678:inv_misc_food_wheat_02:Mild Spices} sont vendues par les marchands de fournitures de cuisine, les {i:3371:inv_potion_84:Empty Vial} par les marchands de fournitures d'alchimie. Ouvre ta faction ci-dessous pour voir qui les vend près de ton maître :",
  ["spices: {n:0:horde:Xen'to} vials: {n:0:horde:Kor'geld}"] = "épices : {n:0:horde:Xen'to} fioles : {n:0:horde:Kor'geld}",
  ["{n:0:horde:Felicia Doan} in the Trade Quarter"] = "{n:0:horde:Felicia Doan} dans le quartier marchand",
  ["spices: {n:0:horde:Naal Mistrunner} vials: {n:0:horde:Mani Winterhoof}"] = "épices : {n:0:horde:Naal Mistrunner} fioles : {n:0:horde:Mani Winterhoof}",
  ["{n:0:horde:Wunna Darkmane} in Bloodhoof Village"] = "{n:0:horde:Wunna Darkmane} au village de Sabot-de-Sang",
  ["{n:0:horde:Abigail Shiel} in Brill"] = "{n:0:horde:Abigail Shiel} à Brill",
  ["{n:0::Iallion Featherfall} in Valanaar {n:0::Belandiel Farflight} in Shen'dar Village"] = "{n:0::Iallion Featherfall} à Valanaar {n:0::Belandiel Farflight} au village de Shen'dar",
  ["{n:0:alliance:Edna Mullby} in the Trade District"] = "{n:0:alliance:Edna Mullby} dans le quartier commerçant",
  ["spices: {n:0:alliance:Emrul Riknussun} vials: {n:0:alliance:Gwina Stonebranch}, right next to the trainer"] = "épices : {n:0:alliance:Emrul Riknussun} fioles : {n:0:alliance:Gwina Stonebranch}, juste à côté du maître",
  ["{n:0:alliance:Golorn Frostbeard} in Kharanos"] = "{n:0:alliance:Golorn Frostbeard} à Kharanos",
  ["{n:0:alliance:Narret Shadowgrove} in Dolanaar"] = "{n:0:alliance:Narret Shadowgrove} à Dolanaar",
  ["50x {s:3275:inv_misc_bandage_15:Linen Bandage} - 50 Linen Cloth"] = "50x {s:3275:inv_misc_bandage_15:Linen Bandage} - 50 Étoffe de lin",
  ["49x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 98 Linen Cloth"] = "49x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 98 Étoffe de lin",
  ["Journeyman First Aid (75-150)"] = "Secourisme (Compagnon) (75-150)",
  ["To train past 75, visit your trainer and learn Journeyman First Aid, it requires First Aid 50."] = "Pour dépasser 75, va voir ton maître et apprends Secourisme (Compagnon), ça demande Secourisme 50.",
  ["16x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 32 Linen Cloth"] = "16x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 32 Étoffe de lin",
  ["12x {s:3277:inv_misc_bandage_14:Wool Bandage} - 12 Wool Cloth"] = "12x {s:3277:inv_misc_bandage_14:Wool Bandage} - 12 Étoffe de laine",
  ["If you have Wool Cloth, pick the {b}Bandages{/b} tab. If you have to buy everything, the {b}Healing Potions{/b} tab is cheaper."] = "Si tu as de l'étoffe de laine, choisis l'onglet {b}Bandages{/b}. Si tu dois tout acheter, l'onglet {b}Potions de soins{/b} revient moins cher.",
  ["43x {s:3277:inv_misc_bandage_14:Wool Bandage} - 43 Wool Cloth"] = "43x {s:3277:inv_misc_bandage_14:Wool Bandage} - 43 Étoffe de laine",
  ["54x {s:3278:inv_misc_bandage_17:Heavy Wool Bandage} - 108 Wool Cloth"] = "54x {s:3278:inv_misc_bandage_17:Heavy Wool Bandage} - 108 Étoffe de laine",
  ["For this tab you need 54 {i:2678:inv_misc_food_wheat_02:Mild Spices}, 31 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}, 31 {i:3372:inv_potion_85:Leaded Vial} and 54 {i:2723:inv_drink_10:Bottle of Dalaran Noir}. Spices are sold by Cooking supply vendors, vials by Alchemy supply vendors and the bottles by barkeeps. The starting zone vendors don't sell Hot Spices or Leaded Vials, so buy them in a capital city. Open your faction below to see who sells them:"] = "Pour cet onglet, il te faut 54 {i:2678:inv_misc_food_wheat_02:Mild Spices}, 31 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}, 31 {i:3372:inv_potion_85:Leaded Vial} et 54 {i:2723:inv_drink_10:Bottle of Dalaran Noir}. Les épices sont vendues par les marchands de fournitures de cuisine, les fioles par les marchands de fournitures d'alchimie et les bouteilles par les taverniers. Les marchands des zones de départ ne vendent ni épices fortes ni fioles plombées, achète-les donc dans une capitale. Ouvre ta faction ci-dessous pour voir qui les vend :",
  ["{i:2678:inv_misc_food_wheat_02:Mild Spices} and {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}"] = "{i:2678:inv_misc_food_wheat_02:Mild Spices} et {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}",
  ["Orgrimmar: {n:0:horde:Xen'to} Undercity: {n:0:horde:Felicia Doan} Thunder Bluff: {n:0:horde:Naal Mistrunner}"] = "Orgrimmar : {n:0:horde:Xen'to} Fossoyeuse : {n:0:horde:Felicia Doan} Les Pitons-du-Tonnerre : {n:0:horde:Naal Mistrunner}",
  ["Orgrimmar: {n:0:horde:Kor'geld} Undercity: {n:0:horde:Felicia Doan} Thunder Bluff: {n:0:horde:Mani Winterhoof}"] = "Orgrimmar : {n:0:horde:Kor'geld} Fossoyeuse : {n:0:horde:Felicia Doan} Les Pitons-du-Tonnerre : {n:0:horde:Mani Winterhoof}",
  ["Orgrimmar: {n:5611::Barkeep Morag} Booty Bay: {n:2832::Nixxrax Fillamug}"] = "Orgrimmar : {n:5611::Barkeep Morag} Baie-du-Butin : {n:2832::Nixxrax Fillamug}",
  ["Stormwind City: {n:0:alliance:Edna Mullby} Ironforge: {n:0:alliance:Emrul Riknussun} Darnassus: {n:0:alliance:Mythrin'dir}"] = "Hurlevent : {n:0:alliance:Edna Mullby} Forgefer : {n:0:alliance:Emrul Riknussun} Darnassus : {n:0:alliance:Mythrin'dir}",
  ["Stormwind City: {n:0:alliance:Edna Mullby} Ironforge: {n:0:alliance:Gwina Stonebranch} Darnassus: {n:0:alliance:Mythrin'dir}"] = "Hurlevent : {n:0:alliance:Edna Mullby} Forgefer : {n:0:alliance:Gwina Stonebranch} Darnassus : {n:0:alliance:Mythrin'dir}",
  ["Stormwind City: {n:277::Roberto Pupellyverbos} and {n:1328::Elly Langston} Ironforge: {n:5570::Bruuk Barleybeard} Booty Bay: {n:2832::Nixxrax Fillamug}"] = "Hurlevent : {n:277::Roberto Pupellyverbos} et {n:1328::Elly Langston} Forgefer : {n:5570::Bruuk Barleybeard} Baie-du-Butin : {n:2832::Nixxrax Fillamug}",
  ["54x {s:1259342:inv_10_alchemy2_quenchingfluid_color2:Simple Poultice} - 54 Spider Ichor, 54 Mild Spices, 54 Bottle of Dalaran Noir"] = "54x {s:1259342:inv_10_alchemy2_quenchingfluid_color2:Simple Poultice} - 54 Ichor d'araignée, 54 Épices douces, 54 Bouteille de Noir de Dalaran",
  ["31x {s:1244433:inv_potion_51:Healing Potion} - 31 Bruiseweed, 31 Hot Spices, 31 Leaded Vial"] = "31x {s:1244433:inv_potion_51:Healing Potion} - 31 Doulourante, 31 Épices fortes, 31 Fiole plombée",
  ["Expert First Aid (150-225)"] = "Secourisme (Expert) (150-225)",
  ["{b}Learn {s:7928:inv_misc_bandage_01:Silk Bandage} from your trainer before you leave{/b}, it's the last recipe the trainers teach."] = "{b}Apprends {s:7928:inv_misc_bandage_01:Silk Bandage} auprès de ton maître avant de partir{/b}, c'est la dernière recette qu'enseignent les maîtres.",
  ["How to learn Expert First Aid"] = "Comment apprendre Secourisme (Expert)",
  ["To train past 150, buy the {i:16084:inv_misc_book_08:Expert First Aid - Under Wraps} book from {n:0:alliance:Deneb Walker} (Alliance) in Arathi Highlands or {n:0:horde:Balai Lok'Wein} (Horde) in Dustwallow Marsh. The book has {b}no level requirement{/b}, you only need First Aid 125."] = "Pour dépasser 150, achète le livre {i:16084:inv_misc_book_08:Expert First Aid - Under Wraps} auprès de {n:0:alliance:Deneb Walker} (Alliance) dans les hautes-terres d'Arathi ou de {n:0:horde:Balai Lok'Wein} (Horde) dans le marécage d'Âprefange. Le livre n'a {b}aucun niveau requis{/b}, il te faut seulement Secourisme 125.",
  ["They also sell the next two manuals, so {b}buy all three{/b} while you are there, or get them from the Auction House if you are low level:"] = "Ils vendent aussi les deux manuels suivants, alors {b}achète les trois{/b} pendant que tu y es, ou prends-les à l'hôtel des ventes si tu es de bas niveau :",
  ["47x {s:7928:inv_misc_bandage_01:Silk Bandage} - 47 Silk Cloth"] = "47x {s:7928:inv_misc_bandage_01:Silk Bandage} - 47 Étoffe de soie",
  ["47x {s:7929:inv_misc_bandage_02:Heavy Silk Bandage} - 94 Silk Cloth"] = "47x {s:7929:inv_misc_bandage_02:Heavy Silk Bandage} - 94 Étoffe de soie",
  ["Use the Manual: Heavy Silk Bandage first to learn the recipe."] = "Utilise d'abord le Manual: Heavy Silk Bandage pour apprendre la recette.",
  ["19x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 19 Mageweave Cloth"] = "19x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 19 Tisse-mage",
  ["Use the Manual: Mageweave Bandage first to learn the recipe."] = "Utilise d'abord le Manual: Mageweave Bandage pour apprendre la recette.",
  ["Artisan First Aid (225-300)"] = "Secourisme (Artisan) (225-300)",
  ["You can train First Aid past 225 by completing the Triage quest. It requires {b}First Aid 225{/b} and {b}level 35{/b}, even though the quest itself is level 45."] = "Tu peux dépasser 225 en Secourisme en terminant la quête Triage. Elle demande {b}Secourisme 225{/b} et {b}niveau 35{/b}, même si la quête elle-même est de niveau 45.",
  ["{b}Bring everything you need in order to skill up to 275{/b}, as you will learn the next two bandages from the same doctor, so bring around 90 Mageweave Cloth and 20 Runecloth with you."] = "{b}Emporte tout ce qu'il te faut pour monter jusqu'à 275{/b}, car tu apprendras les deux bandages suivants auprès du même docteur : prends donc environ 90 Tisse-mage et 20 Étoffe runique avec toi.",
  ["The {q:6622::Triage} quest is given by {n:0:horde:Doctor Gregory Victor} in Arathi Highlands at Hammerfall."] = "La quête {q:6622::Triage} est donnée par {n:0:horde:Doctor Gregory Victor} à Trépas-d'Orgrim, dans les hautes-terres d'Arathi.",
  ["Hammerfall, Arathi Highlands"] = "Trépas-d'Orgrim, hautes-terres d'Arathi",
  ["The {q:6624::Triage} quest is given by {n:0:alliance:Doctor Gustaf VanHowzen} in Dustwallow Marsh at Theramore."] = "La quête {q:6624::Triage} est donnée par {n:0:alliance:Doctor Gustaf VanHowzen} à Theramore, dans le marécage d'Âprefange.",
  ["Foothold Citadel, Dustwallow Marsh"] = "Foothold Citadel, marécage d'Âprefange",
  ["You get a stack of triage bandages and have to save 15 patients, heal the critically injured ones first."] = "Tu reçois une pile de bandages de triage et tu dois sauver 15 patients, soigne d'abord les blessés graves.",
  ["How to complete the Triage quest"] = "Comment terminer la quête Triage",
  ["Make sure you have about 10 minutes of spare time to do this with no interruptions."] = "Assure-toi d'avoir environ 10 minutes devant toi pour la faire sans interruption.",
  ["Press CTRL + V to show the health bars over the patients, or turn on \"Show NPC names\" in the interface options."] = "Appuie sur CTRL + V pour afficher les barres de vie au-dessus des patients, ou active « Afficher le nom des PNJ » dans les options d'interface.",
  ["Zoom the camera out to third person, so you see as much of the room as you can."] = "Dézoome la caméra en vue à la troisième personne, pour voir le plus possible de la salle.",
  ["Put the Triage Bandages the doctor gave you on your action bar and use those, not your own bandages."] = "Place les Triage Bandages que le docteur t'a donnés sur ta barre d'action et utilise-les, pas tes propres bandages.",
  ["Stand in the middle of the room."] = "Place-toi au milieu de la salle.",
  ["When you see another patient, left-click on them to pre-select them, and as soon as your current heal has finished click the bandages in your action bar and the pre-selected one will begin to heal. Saves valuable seconds this way."] = "Quand tu vois un autre patient, fais un clic gauche dessus pour le présélectionner, et dès que ton soin en cours est terminé, clique sur les bandages dans ta barre d'action : le patient présélectionné commencera à être soigné. Tu gagnes ainsi de précieuses secondes.",
  ["When you have saved 15 patients, {b}turn in the quest immediately{/b}. I failed it on my druid because I waited, six patients died in the meantime and the quest went from completed to failed."] = "Quand tu as sauvé 15 patients, {b}rends la quête immédiatement{/b}. Je l'ai ratée sur mon druide parce que j'ai attendu, six patients sont morts entre-temps et la quête est passée de terminée à échouée.",
  ["29x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 29 Mageweave Cloth"] = "29x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 29 Tisse-mage",
  ["30x {s:10841:inv_misc_bandage_20:Heavy Mageweave Bandage} - 60 Mageweave Cloth"] = "30x {s:10841:inv_misc_bandage_20:Heavy Mageweave Bandage} - 60 Tisse-mage",
  ["The doctor teaches it at 240."] = "Le docteur l'enseigne à 240.",
  ["20x {s:18629:inv_misc_bandage_11:Runecloth Bandage} - 20 Runecloth"] = "20x {s:18629:inv_misc_bandage_11:Runecloth Bandage} - 20 Étoffe runique",
  ["The doctor teaches it at 260."] = "Le docteur l'enseigne à 260.",
  ["30x {s:1244436:inv_potion_54:Major Healing Potion} - 30 Golden Sansam, 90 Soothing Spices, 30 Crystal Vial"] = "30x {s:1244436:inv_potion_54:Major Healing Potion} - 30 Sansam doré, 90 Épices apaisantes, 30 Fiole en cristal",
  ["The recipe is {i:255729:inv_misc_book_03:Manual: Major Healing Potion}. Check the Auction House first, and buy it there if it costs less than 8g."] = "La recette est {i:255729:inv_misc_book_03:Manual: Major Healing Potion}. Regarde d'abord à l'hôtel des ventes, et achète-la là-bas si elle coûte moins de 8 po.",
  ["If it costs more, you can buy it from {n:0::Pexmit} in Mount Hyjal for 8g, but he can be tricky to find."] = "Si elle coûte plus cher, tu peux l'acheter auprès de {n:0::Pexmit} au mont Hyjal pour 8 po, mais il peut être difficile à trouver.",
  ["Horde players can also get it from Ortak Lomgok in Elderwild, Mount Hyjal, as the reward for {q:96622::A Rest Without Pain}. You have to complete his {q:96616::Herbs for the Bruised and Weary} quest first."] = "Les joueurs de la Horde peuvent aussi l'obtenir auprès d'Ortak Lomgok à Elderwild, au mont Hyjal, en récompense de {q:96622::A Rest Without Pain}. Tu dois d'abord terminer sa quête {q:96616::Herbs for the Bruised and Weary}.",
  ["This WoW Forever Fishing leveling guide will show you the fastest way to level Fishing from 1 to 300. Fishing takes a lot of patience, you will have to catch a lot of fish to get from start to finish, but you don't need any materials, only a Fishing Pole and a few lures."] = "Ce guide de montée en Pêche pour WoW Forever te montre la façon la plus rapide de monter la Pêche de 1 à 300. La Pêche demande beaucoup de patience, tu devras attraper beaucoup de poissons pour aller du début à la fin, mais tu n'as besoin d'aucun matériau, seulement d'une canne à pêche et de quelques appâts.",
  ["Below you will find every Fishing trainer by starting zone and capital city, where to fish for each skill range, and how to learn Expert and Artisan Fishing. If you haven't leveled Cooking yet, use my Fishing and Cooking leveling guide instead, because the fish you catch will level your Cooking at the same time:"] = "Tu trouveras ci-dessous chaque maître de Pêche par zone de départ et capitale, où pêcher pour chaque palier de compétence, et comment apprendre Pêche (Expert) et (Artisan). Si tu n'as pas encore monté la Cuisine, utilise plutôt mon guide de montée en Pêche et Cuisine, car les poissons que tu attrapes monteront ta Cuisine en même temps :",
  ["Fishing Trainer Locations"] = "Emplacements des maîtres de Pêche",
  ["Apprentice Fishing has no level requirement in Forever, so you can learn it on a fresh character. Every trainer also teaches Journeyman Fishing, so you don't have to find a different trainer at 50."] = "La Pêche (Apprenti) n'a aucun niveau requis dans Forever, tu peux donc l'apprendre sur un personnage tout neuf. Chaque maître enseigne aussi Pêche (Compagnon), tu n'as donc pas à chercher un autre maître à 50.",
  ["Orgrimmar: {n:0:horde:Lumak}"] = "Orgrimmar : {n:0:horde:Lumak}",
  ["Undercity: {n:0:horde:Armand Cromwell}"] = "Fossoyeuse : {n:0:horde:Armand Cromwell}",
  ["Thunder Bluff: {n:0:horde:Kah Mistrunner}"] = "Les Pitons-du-Tonnerre : {n:0:horde:Kah Mistrunner}",
  ["Every starting zone has a Fishing trainer, and they all stand next to water, so you can start fishing right away."] = "Chaque zone de départ a un maître de Pêche, et ils se tiennent tous près de l'eau, tu peux donc commencer à pêcher tout de suite.",
  ["{n:0:horde:Lau'Tiki} on the coast at Sen'jin Village"] = "{n:0:horde:Lau'Tiki} sur la côte au village de Sen'jin",
  ["{n:0:horde:Uthan Stillwater} at Stonebull Lake, next to Bloodhoof Village"] = "{n:0:horde:Uthan Stillwater} au lac Taureau-de-pierre, à côté du village de Sabot-de-Sang",
  ["{n:0:horde:Clyde Kellen} at Brightwater Lake, east of Brill"] = "{n:0:horde:Clyde Kellen} au lac Brightwater, à l'est de Brill",
  ["{n:0::Baelann Swiftcurrent} in Valanaar, {n:0::Fenn Fairweather} in Shen'dar Village"] = "{n:0::Baelann Swiftcurrent} à Valanaar, {n:0::Fenn Fairweather} au village de Shen'dar",
  ["Stormwind City: {n:0:alliance:Arnold Leland}"] = "Hurlevent : {n:0:alliance:Arnold Leland}",
  ["Ironforge: {n:0:alliance:Grimnur Stonebrand}"] = "Forgefer : {n:0:alliance:Grimnur Stonebrand}",
  ["Darnassus: {n:0:alliance:Astaia}"] = "Darnassus : {n:0:alliance:Astaia}",
  ["{n:0:alliance:Lee Brown} at Crystal Lake, east of Goldshire"] = "{n:0:alliance:Lee Brown} au lac de Cristal, à l'est de Comté-de-l'Or",
  ["{n:0:alliance:Paxton Ganter} at Iceflow Lake, on the way to Gnomeregan"] = "{n:0:alliance:Paxton Ganter} au lac Iceflow, sur la route de Gnomeregan",
  ["{n:0:alliance:Androl Oakhand} in Rut'theran Village, on the shore next to the dock"] = "{n:0:alliance:Androl Oakhand} au village de Rut'theran, sur la rive à côté du quai",
  ["You can find every Fishing trainer for Horde and Alliance on my WoW Forever Fishing Trainers page."] = "Tu trouveras tous les maîtres de Pêche de la Horde et de l'Alliance sur ma page WoW Forever Fishing Trainers.",
  ["How to Fish in WoW Forever (1-75)"] = "Comment pêcher dans WoW Forever (1-75)",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a few {i:6529:inv_misc_orb_03:Shiny Bauble} from a Fishing Supply or Trade Supply vendor. In the capital cities they stand next to the trainer, for every other zone open your faction below:"] = "Achète une {i:6256:inv_fishingpole_02:Fishing Pole} et quelques {i:6529:inv_misc_orb_03:Shiny Bauble} auprès d'un marchand de fournitures de pêche ou de fournitures commerciales. Dans les capitales, ils se tiennent à côté du maître, pour toutes les autres zones ouvre ta faction ci-dessous :",
  ["{n:0:horde:Zansoa} in Sen'jin Village"] = "{n:0:horde:Zansoa} au village de Sen'jin",
  ["{n:0:horde:Martine Tramblay} at the Death's Watch Waystation, south-east of Brill"] = "{n:0:horde:Martine Tramblay} au relais de Death's Watch, au sud-est de Brill",
  ["{n:0::Baelann Swiftcurrent} in Valanaar, {n:0::Belandiel Farflight} in Shen'dar Village"] = "{n:0::Baelann Swiftcurrent} à Valanaar, {n:0::Belandiel Farflight} au village de Shen'dar",
  ["{n:0:horde:Shankys}, next to the Fishing trainer"] = "{n:0:horde:Shankys}, à côté du maître de Pêche",
  ["{n:0:horde:Lizbeth Cromwell}, next to the Fishing trainer"] = "{n:0:horde:Lizbeth Cromwell}, à côté du maître de Pêche",
  ["{n:0:horde:Sewa Mistrunner}, next to the Fishing trainer"] = "{n:0:horde:Sewa Mistrunner}, à côté du maître de Pêche",
  ["{n:0:horde:Wik'Tar} in Zoram'gar Outpost"] = "{n:0:horde:Wik'Tar} à l'avant-poste de Zoram'gar",
  ["{n:0:horde:Katoom the Angler}, the Fishing trainer in Revantusk Village"] = "{n:0:horde:Katoom the Angler}, le maître de Pêche du village des Vengebroches",
  ["{n:0:alliance:Gretta Ganter} at Iceflow Lake"] = "{n:0:alliance:Gretta Ganter} au lac Iceflow",
  ["{n:0:alliance:Nessa Shadowsong} in Rut'theran Village"] = "{n:0:alliance:Nessa Shadowsong} au village de Rut'theran",
  ["{n:0:alliance:Catherine Leland}, next to the Fishing trainer"] = "{n:0:alliance:Catherine Leland}, à côté du maître de Pêche",
  ["{n:0:alliance:Tansy Puddlefizz}, next to the Fishing trainer"] = "{n:0:alliance:Tansy Puddlefizz}, à côté du maître de Pêche",
  ["{n:0:alliance:Voloren}, next to the Fishing trainer"] = "{n:0:alliance:Voloren}, à côté du maître de Pêche",
  ["{n:0:alliance:Khara Deepwater} at the Loch"] = "{n:0:alliance:Khara Deepwater} au Loch",
  ["{n:0:alliance:Stuart Fleming} in Menethil Harbor"] = "{n:0:alliance:Stuart Fleming} à Port-de-Menethil",
  ["Redridge Mountains"] = "Les Carmines",
  ["{n:0:alliance:Vernon Hale} at Lake Everstill"] = "{n:0:alliance:Vernon Hale} au lac Placide",
  ["{n:0:alliance:Lindea Rabonne} in Southshore"] = "{n:0:alliance:Lindea Rabonne} à Austrivage",
  ["Open the Professions window."] = "Ouvre la fenêtre des métiers.",
  ["Click on the {b}hammer button{/b} in the row of buttons on the right side of your screen, {b}NOT the Fishing tab{/b}."] = "Clique sur le {b}bouton marteau{/b} dans la rangée de boutons à droite de ton écran, {b}PAS sur l'onglet Pêche{/b}.",
  ["Drag the {s:7731:trade_fishing:Fishing} button from the Fishing box to your action bar."] = "Glisse le bouton {s:7731:trade_fishing:Fishing} du cadre Pêche vers ta barre d'action.",
  ["Equip your Fishing Pole and apply the {i:6529:inv_misc_orb_03:Shiny Bauble} lure."] = "Équipe ta canne à pêche et applique l'appât {i:6529:inv_misc_orb_03:Shiny Bauble}.",
  ["Go to any starting zone and look for a lake, pond or river. Stand in front of the water and press the fishing button."] = "Va dans n'importe quelle zone de départ et cherche un lac, un étang ou une rivière. Place-toi face à l'eau et appuie sur le bouton de pêche.",
  ["Mouse over the bobber in the water, and when it splashes, right-click on it."] = "Passe la souris sur le bouchon dans l'eau, et quand il éclabousse, fais un clic droit dessus.",
  ["Fish until you reach Fishing 75."] = "Pêche jusqu'à atteindre Pêche 75.",
  ["{b}Starting zones:{/b} Dun Morogh, Durotar, Elwynn Forest, Mulgore, Teldrassil, Tirisfal Glades, Zephras Isle"] = "{b}Zones de départ :{/b} Dun Morogh, Durotar, forêt d'Elwynn, Mulgore, Teldrassil, clairières de Tirisfal, Zephras Isle",
  ["{b}Remember, starting zones do not include capital cities!{/b}"] = "{b}Attention, les zones de départ n'incluent pas les capitales !{/b}",
  ["If you can't find the Fishing button, I show it with pictures in my how to fish in WoW Forever guide."] = "Si tu ne trouves pas le bouton Pêche, je le montre en images dans mon guide sur comment pêcher dans WoW Forever.",
  ["Go back to your trainer and learn Journeyman Fishing. It requires {b}Fishing 50{/b} and {b}level 10{/b}."] = "Retourne voir ton maître et apprends Pêche (Compagnon). Ça demande {b}Pêche 50{/b} et {b}niveau 10{/b}.",
  ["Fish until 150 in one of the capital cities:"] = "Pêche jusqu'à 150 dans l'une des capitales :",
  ["You can fish in any of these zones too: The Barrens, Darkshore, Ironforge, Loch Modan, Silverpine Forest, Westfall."] = "Tu peux aussi pêcher dans n'importe laquelle de ces zones : les Tarides, Sombrivage, Forgefer, Loch Modan, forêt des Pins-Argentés, marche de l'Ouest.",
  ["If the fish keep getting away, buy {i:6530:inv_misc_monstertail_03:Nightcrawlers} from a Fishing Supply vendor. They need Fishing 50."] = "Si les poissons continuent de s'échapper, achète des {i:6530:inv_misc_monstertail_03:Nightcrawlers} auprès d'un marchand de fournitures de pêche. Ils demandent Pêche 50.",
  ["You can learn Expert Fishing from the {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} book (requires {b}level 20{/b} and {b}Fishing 125{/b}) sold by {n:0::Old Man Heming} at Booty Bay in Stranglethorn Vale. He is in the middle of Booty Bay at the very bottom, near the fishing sign. You can also buy the book from the Auction House."] = "Tu peux apprendre Pêche (Expert) avec le livre {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} ({b}niveau 20{/b} et {b}Pêche 125{/b} requis) vendu par {n:0::Old Man Heming} à Baie-du-Butin, dans la vallée de Strangleronce. Il se trouve au milieu de Baie-du-Butin, tout en bas, près de l'enseigne de pêche. Tu peux aussi acheter le livre à l'hôtel des ventes.",
  ["Buy a bunch of {i:6532:inv_misc_gem_variety_02:Bright Baubles} from Old Man Heming before you leave."] = "Achète un bon paquet de {i:6532:inv_misc_gem_variety_02:Bright Baubles} au vieux Heming avant de partir.",
  ["Go to {b}Dustwallow Marsh{/b}, apply {i:6532:inv_misc_gem_variety_02:Bright Baubles} to your Fishing Pole and fish until 225."] = "Va dans le {b}marécage d'Âprefange{/b}, applique des {i:6532:inv_misc_gem_variety_02:Bright Baubles} sur ta canne à pêche et pêche jusqu'à 225.",
  ["I recommend fishing in Dustwallow because the Artisan Fishing quest starts there, but you can fish in these zones too: Alterac Mountains, Arathi Highlands, Desolace, Stranglethorn Vale, Swamp of Sorrows, and Thousand Needles."] = "Je te conseille de pêcher dans le marécage d'Âprefange car la quête de Pêche (Artisan) commence là, mais tu peux aussi pêcher dans ces zones : montagnes d'Alterac, hautes-terres d'Arathi, Désolace, vallée de Strangleronce, marais des Chagrins et Mille pointes.",
  ["Learning Artisan Fishing"] = "Apprendre Pêche (Artisan)",
  ["To train Fishing past 225, you must complete the quest {q:6607::Nat Pagle, Angler Extreme} from {n:0::Nat Pagle} in Dustwallow Marsh."] = "Pour dépasser 225 en Pêche, tu dois terminer la quête {q:6607::Nat Pagle, Angler Extreme} de {n:0::Nat Pagle} dans le marécage d'Âprefange.",
  ["It requires {b}level 35{/b} and {b}Fishing 225{/b}."] = "Elle demande {b}niveau 35{/b} et {b}Pêche 225{/b}.",
  ["To complete the quest, you have to catch 4 quest fish in four different zones:"] = "Pour terminer la quête, tu dois attraper 4 poissons de quête dans quatre zones différentes :",
  ["{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Feralas"] = "{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Féralas",
  ["Use {i:6532:inv_misc_gem_variety_02:Bright Baubles} when you are fishing in {b}Feralas{/b} to stop the fish from getting away. You don't need any lures in the other zones because your Fishing skill is high enough by then."] = "Utilise des {i:6532:inv_misc_gem_variety_02:Bright Baubles} quand tu pêches à {b}Féralas{/b} pour empêcher les poissons de s'échapper. Tu n'as besoin d'aucun appât dans les autres zones car ta compétence de Pêche est alors assez élevée.",
  ["Nat Pagle, Angler Extreme quest"] = "Quête Nat Pagle, Angler Extreme",
  ["After you completed the quest, fish in any of these zones:"] = "Une fois la quête terminée, pêche dans l'une de ces zones :",
  ["Feralas"] = "Féralas",
  ["Western Plaguelands"] = "Maleterres de l'Ouest",
  ["You will have to use {i:6532:inv_misc_gem_variety_02:Bright Baubles} in these zones to stop the fish from getting away!"] = "Tu devras utiliser des {i:6532:inv_misc_gem_variety_02:Bright Baubles} dans ces zones pour empêcher les poissons de s'échapper !",
  ["This WoW Forever Lockpicking leveling guide will show you the fastest way to level Lockpicking from 1 to 300, with the best place to pick locks for each skill range."] = "Ce guide de montée en Crochetage pour WoW Forever te montre la façon la plus rapide de monter le Crochetage de 1 à 300, avec le meilleur endroit où crocheter des serrures pour chaque palier de compétence.",
  ["Max Lockpicking Skill by Level"] = "Compétence de Crochetage maximale par niveau",
  ["{b}Your Lockpicking skill can't go higher than 5 times your level{/b}, so you have to level your character to level Lockpicking. This is the level you need for each part of the guide:"] = "{b}Ta compétence de Crochetage ne peut pas dépasser 5 fois ton niveau{/b}, tu dois donc monter ton personnage en niveau pour monter le Crochetage. Voici le niveau nécessaire pour chaque partie du guide :",
  ["Your level"] = "Ton niveau",
  ["Max Lockpicking skill"] = "Crochetage max",
  ["I originally made this guide with my rogue in Classic. In WoW Forever I'm leveling a hunter, so a friend of mine checks the spots on his rogue, and he confirmed the Horde 1-100 part. Readers told me where they leveled from 150 to 300. I'm assuming the rest is the same as in Classic, but I will confirm it later. If something looks off, send me feedback."] = "J'ai d'abord fait ce guide avec mon voleur dans Classic. Dans WoW Forever, je monte un chasseur, donc un ami vérifie les spots avec son voleur, et il a confirmé la partie Horde 1-100. Des lecteurs m'ont indiqué où ils sont montés de 150 à 300. Je suppose que le reste est identique à Classic, mais je le confirmerai plus tard. Si quelque chose te semble incorrect, envoie-moi un retour.",
  ["Go to the ship near Ratchet in The Barrens. The Buccaneer's Strongboxes there respawn after a few seconds, so even two rogues can skill up there at the same time. {b}They are inside the ship{/b}, at the spot marked on the map below."] = "Va au bateau près de Cabestan, dans les Tarides. Les Coffres de boucanier là-bas réapparaissent au bout de quelques secondes, donc même deux voleurs peuvent y monter en même temps. {b}Ils sont à l'intérieur du bateau{/b}, à l'endroit marqué sur la carte ci-dessous.",
  ["There is another chest at the bottom of the ship called The Jewel of the Southsea. Don't open it if you are low level, because it spawns a mob that will kill you."] = "Il y a un autre coffre au fond du bateau, appelé le Joyau des Mers du Sud. Ne l'ouvre pas si tu es de bas niveau, car il fait apparaître un monstre qui te tuera.",
  ["There are a bunch of Practice Lockboxes in Redridge Mountains, north of Lake Everstill. They respawn really fast, so you can get to 100 there easily."] = "Il y a un tas de coffrets d'entraînement dans les Carmines, au nord du lac Placide. Ils réapparaissent très vite, tu peux donc facilement atteindre 100 là-bas.",
  ["Go to Zoram Strand in Ashenvale and look for Waterlogged Footlockers along the shore, on land."] = "Va au rivage de Zoram en Orneval et cherche des Waterlogged Footlocker le long du rivage, sur la terre ferme.",
  ["Go to Angor Fortress in Badlands. There are two kinds of footlockers there, the Battered Footlockers upstairs need 150, and the Dented Footlockers downstairs need {b}175{/b}."] = "Va à la forteresse d'Angor dans les Terres ingrates. Il y a deux sortes de coffres là-bas, les Battered Footlocker à l'étage demandent 150, et les Dented Footlocker en bas demandent {b}175{/b}.",
  ["The footlockers downstairs give a skill point every time until 215, so you can stay here until 225."] = "Les coffres d'en bas donnent un point de compétence à chaque fois jusqu'à 215, tu peux donc rester ici jusqu'à 225.",
  ["Don't bother pickpocketing the mobs there, because their boxes are too low level to give any skill."] = "Ne t'embête pas à faire les poches des monstres là-bas, car leurs coffrets sont de trop bas niveau pour donner de la compétence.",
  ["Go to The Slag Pit, the cave in the middle of Searing Gorge, and pick the footlockers there. The ones on the upper part give skill points all the way to 300. They stay yellow until 290 and turn green after that, so the last 10 points take longer."] = "Va à la Fosse aux scories, la grotte au milieu de la gorge des Vents brûlants, et crochète les coffres là-bas. Ceux de la partie haute donnent des points de compétence jusqu'à 300. Ils restent jaunes jusqu'à 290 et deviennent verts ensuite, les 10 derniers points prennent donc plus de temps.",
  ["{b}There are two kinds of Dented Footlockers in the Slag Pit{/b}, with the same name. The ones on the lower part need 200 and the ones on the upper part need 225. Pick both until the lower ones stop giving skill points, then stay on the upper part."] = "{b}Il y a deux sortes de Dented Footlocker dans la Fosse aux scories{/b}, avec le même nom. Ceux de la partie basse demandent 200 et ceux de la partie haute 225. Crochète les deux jusqu'à ce que ceux d'en bas ne donnent plus de points, puis reste dans la partie haute.",
  ["Don't bother pickpocketing the mobs there, because their boxes are too low level to give much skill."] = "Ne t'embête pas à faire les poches des monstres là-bas, car leurs coffrets sont de trop bas niveau pour donner beaucoup de compétence.",
  ["This WoW Forever camping guide will show you how camping works, how to make a campfire and every camp item and buff of every profession."] = "Ce guide du camping pour WoW Forever te montre comment fonctionne le camping, comment faire un feu de camp, ainsi que chaque objet de camp et amélioration de chaque métier.",
  ["Three night elves sitting at a campfire in Dolanaar, Teldrassil, in WoW Forever"] = "Trois elfes de la nuit assis autour d'un feu de camp à Dolanaar, Teldrassil, dans WoW Forever",
  ["How Camping Works"] = "Comment fonctionne le camping",
  ["Someone puts down a campfire, and everyone around it can place a camp item of their own profession. {b}Sit (/sit) next to the fire for a minute{/b}, you will see a buff start counting down. Then you get Camp Benefits, one buff with everything the camp items give, for an hour."] = "Quelqu'un pose un feu de camp, et tous ceux autour peuvent placer un objet de camp de leur propre métier. {b}Assieds-toi (/sit) près du feu pendant une minute{/b}, tu verras une amélioration commencer un compte à rebours. Ensuite, tu obtiens Camp Benefits, une seule amélioration avec tout ce que donnent les objets de camp, pendant une heure.",
  ["{b}Each player can place one camp item{/b}, and it puts all your camp items on a 1 hour cooldown. A campfire holds 3, 5 or 10 camp items, depending on how big it is (see How to Make a Campfire below). The buffs are weaker class buffs and don't stack with them."] = "{b}Chaque joueur peut placer un objet de camp{/b}, et ça met tous tes objets de camp en recharge pendant 1 heure. Un feu de camp accueille 3, 5 ou 10 objets de camp, selon sa taille (voir Comment faire un feu de camp ci-dessous). Les améliorations sont des versions plus faibles des améliorations de classe et ne se cumulent pas avec elles.",
  ["The intro quests in the starting zones, The Great Outdoors and Camping 101, are optional, the buffs work without them. The quest givers' fires always give the Camp Tent's rested experience."] = "Les quêtes d'introduction des zones de départ, The Great Outdoors et Camping 101, sont facultatives, les améliorations fonctionnent sans elles. Les feux des donneurs de quête donnent toujours l'expérience de repos de la Camp Tent.",
  ["How to Make a Campfire"] = "Comment faire un feu de camp",
  ["Learn Cooking from any Cooking trainer, the Basic Campfire Kit comes with it at skill 1. {i:4470:inv_tradeskillitem_01:Simple Wood} is sold by the trade and general goods vendors in most towns. Open your Professions window (the hammer and pick button in the menu bar), craft the kit from 1 Simple Wood under Cooking, then use it from your bags to place the campfire."] = "Apprends la Cuisine auprès de n'importe quel maître de Cuisine, le Basic Campfire Kit est fourni avec, à la compétence 1. Le {i:4470:inv_tradeskillitem_01:Simple Wood} est vendu par les marchands de fournitures commerciales et les marchands généraux de la plupart des villes. Ouvre ta fenêtre des métiers (le bouton marteau et pioche de la barre de menus), fabrique le kit avec 1 Bois simple dans Cuisine, puis utilise-le depuis tes sacs pour poser le feu de camp.",
  ["{b}Tip:{/b} you don't have to carry Flint and Tinder and wood around any more, craft a stack of Basic Campfire Kits at home and carry only those, they take one bag slot. You can also hand them to others."] = "{b}Astuce :{/b} tu n'as plus besoin de transporter silex, amadou et bois, fabrique une pile de Basic Campfire Kit chez toi et ne transporte que ça, ils prennent un seul emplacement de sac. Tu peux aussi en donner aux autres.",
  ["The bigger campfires hold more camp items, but they need a Blueprint."] = "Les feux de camp plus grands accueillent plus d'objets de camp, mais ils nécessitent un plan (Blueprint).",
  ["The Expert Campfire Kit needs more Cooking to use than to learn (220 against 200). It's usually the other way around, so maybe it's a bug."] = "L'Expert Campfire Kit demande plus de Cuisine pour être utilisé que pour être appris (220 contre 200). C'est d'habitude l'inverse, c'est donc peut-être un bug.",
  ["Learn at"] = "Appris à",
  ["Use at"] = "Utilisable à",
  ["Camp items"] = "Objets de camp",
  ["Made from"] = "Fabriqué avec",
  ["Comes with Cooking"] = "Fourni avec la Cuisine",
  ["{i:273087:inv_garrison_blueprints3:Blueprint: Journeyman Campfire} Dropped by: {n:3673::Lord Serpentis} in Wailing Caverns"] = "{i:273087:inv_garrison_blueprints3:Blueprint: Journeyman Campfire} Butin de : {n:3673::Lord Serpentis} dans les Cavernes des lamentations",
  ["{i:273101:inv_garrison_blueprints3:Blueprint: Expert Campfire} I don't know yet where it drops"] = "{i:273101:inv_garrison_blueprints3:Blueprint: Expert Campfire} Je ne sais pas encore où il tombe",
  ["Camp Items"] = "Objets de camp",
  ["Every profession has three camp items, at skill 20, 140 and 300 (Cooking has two), and each one replaces the one before. The tier 1 item comes from your profession trainer, {b}tier 2 and 3 need a Blueprint{/b}, a recipe item. The tier 2 and 3 blueprints drop from bosses, most of them in dungeons, the tabs show which one. Only the Herbalism one at 300 is not known yet."] = "Chaque métier a trois objets de camp, à la compétence 20, 140 et 300 (la Cuisine en a deux), et chacun remplace le précédent. L'objet de rang 1 vient du maître de ton métier, {b}les rangs 2 et 3 nécessitent un plan{/b} (Blueprint), un objet de recette. Les plans de rang 2 et 3 tombent sur des boss, la plupart en donjon, les onglets indiquent lesquels. Seul celui d'Herboristerie à 300 n'est pas encore connu.",
  ["{b}Every item also gives the buff of the tier 1 item of its profession{/b}, so you never have to choose between a buff and a crafting station. A Master Forge still gives the Strength buff of the Sharpening Wheel. Whether a tier 3 item also gives what the tier 2 item gives (an anvil from a Master Forge) is not confirmed yet. The tabs only list what each tier adds."] = "{b}Chaque objet donne aussi l'amélioration de l'objet de rang 1 de son métier{/b}, tu n'as donc jamais à choisir entre une amélioration et un poste d'artisanat. Une Master Forge donne toujours l'amélioration de Force de la Sharpening Wheel. On ne sait pas encore si un objet de rang 3 donne aussi ce que donne l'objet de rang 2 (une enclume pour la Master Forge). Les onglets ne listent que ce que chaque rang ajoute.",
  ["Alchemy"] = "Alchimie",
  ["Blacksmithing"] = "Forge",
  ["Enchanting"] = "Enchantement",
  ["Engineering"] = "Ingénierie",
  ["Leatherworking"] = "Travail du cuir",
  ["Tailoring"] = "Couture",
  ["Skinning"] = "Dépeçage",
  ["First Aid"] = "Secourisme",
  ["Camp Item"] = "Objet de camp",
  ["What It Does"] = "Effet",
  ["Mana regeneration buff, doesn't stack with Blessing of Wisdom"] = "Amélioration de régénération de mana, ne se cumule pas avec Bénédiction de sagesse",
  ["Trainer or the Camping 101 quest"] = "Maître ou quête Camping 101",
  ["A Fermenter, needed for a few Alchemy recipes"] = "Un fermenteur, nécessaire pour quelques recettes d'Alchimie",
  ["{i:273085:inv_garrison_blueprints3:Blueprint: Fermenter} Dropped by: {n:250657::Rath'mael} in the Ruins of Lordaeron"] = "{i:273085:inv_garrison_blueprints3:Blueprint: Fermenter} Butin de : {n:250657::Rath'mael} dans les ruines de Lordaeron",
  ["An Alchemy Lab, needed for some Alchemy recipes"] = "Un laboratoire d'alchimie, nécessaire pour certaines recettes d'Alchimie",
  ["{i:273112:inv_garrison_blueprints3:Blueprint: Alchemy Laboratory} Dropped by: {n:10508::Ras Frostwhisper} in Scholomance"] = "{i:273112:inv_garrison_blueprints3:Blueprint: Alchemy Laboratory} Butin de : {n:10508::Ras Frostwhisper} à Scholomance",
  ["Strength buff, doesn't stack with Strength of Earth Totem"] = "Amélioration de Force, ne se cumule pas avec Totem de force de la terre",
  ["An anvil"] = "Une enclume",
  ["{i:273086:inv_garrison_blueprints3:Blueprint: Anvil} Dropped by: {n:1763::Gilnid} in The Deadmines"] = "{i:273086:inv_garrison_blueprints3:Blueprint: Anvil} Butin de : {n:1763::Gilnid} dans les Mortemines",
  ["A Master Forge, needed for many Blacksmithing recipes"] = "Une forge de maître, nécessaire pour de nombreuses recettes de Forge",
  ["{i:273113:inv_garrison_blueprints3:Blueprint: Master Forge} Dropped by: {n:8983::Golem Lord Argelmach} in Blackrock Depths"] = "{i:273113:inv_garrison_blueprints3:Blueprint: Master Forge} Butin de : {n:8983::Golem Lord Argelmach} dans les profondeurs de Rochenoire",
  ["Armor, all stats and resistances buff, doesn't stack with Mark of the Wild"] = "Amélioration d'armure, de toutes les caractéristiques et des résistances, ne se cumule pas avec Marque du fauve",
  ["Better disenchanting"] = "Meilleur désenchantement",
  ["{i:273103:inv_garrison_blueprints3:Blueprint: Arcane Salvager} Dropped by: {n:246020::Shade of the Archmage} in the City of Dalaran"] = "{i:273103:inv_garrison_blueprints3:Blueprint: Arcane Salvager} Butin de : {n:246020::Shade of the Archmage} dans la cité de Dalaran",
  ["An Arcane Forge, needed for some Enchanting recipes"] = "Une forge arcanique, nécessaire pour certaines recettes d'Enchantement",
  ["{i:273116:inv_garrison_blueprints3:Blueprint: Arcane Forge} Dropped by: {n:261809::Nanaya} in Kalimdor"] = "{i:273116:inv_garrison_blueprints3:Blueprint: Arcane Forge} Butin de : {n:261809::Nanaya} en Kalimdor",
  ["Summons the {n:242498::Reagent Bot}, a vendor with class reagents and profession supplies for everyone at the camp"] = "Invoque le {n:242498::Reagent Bot}, un marchand de composants de classe et de fournitures de métier pour tout le monde au camp",
  ["Repairs for everyone at the camp"] = "Réparations pour tout le monde au camp",
  ["{i:273092:inv_garrison_blueprints3:Blueprint: Repair Bot} Dropped by: {n:643::Sneed} in The Deadmines"] = "{i:273092:inv_garrison_blueprints3:Blueprint: Repair Bot} Butin de : {n:643::Sneed} dans les Mortemines",
  ["An Anarchist's Workbench, needed for some Engineering recipes"] = "Un établi d'anarchiste, nécessaire pour certaines recettes d'Ingénierie",
  ["{i:273117:inv_garrison_blueprints3:Blueprint: Anarchist's Workbench} Dropped by: {n:11058::Ezra Grimm} in Stratholme"] = "{i:273117:inv_garrison_blueprints3:Blueprint: Anarchist's Workbench} Butin de : {n:11058::Ezra Grimm} à Stratholme",
  ["Rested experience up to 5% of a level, once an hour (a debuff blocks it until then)"] = "Expérience de repos jusqu'à 5 % d'un niveau, une fois par heure (un affaiblissement l'empêche d'ici là)",
  ["A Tanning Rack, needed for many Leatherworking recipes"] = "Un râtelier de tannage, nécessaire pour de nombreuses recettes du Travail du cuir",
  ["{i:273096:inv_garrison_blueprints3:Blueprint: Tanning Rack} Dropped by: {n:3886::Razorclaw the Butcher} in Shadowfang Keep"] = "{i:273096:inv_garrison_blueprints3:Blueprint: Tanning Rack} Butin de : {n:3886::Razorclaw the Butcher} au donjon d'Ombrecroc",
  ["A Sewing Machine, needed for many Leatherworking recipes"] = "Une machine à coudre, nécessaire pour de nombreuses recettes du Travail du cuir",
  ["{i:273121:inv_garrison_blueprints3:Blueprint: Sewing Machine} Dropped by: {n:10432::Vectus} in Scholomance"] = "{i:273121:inv_garrison_blueprints3:Blueprint: Sewing Machine} Butin de : {n:10432::Vectus} à Scholomance",
  ["Spirit buff for players of your faction, doesn't stack with Divine Spirit. Horde and Alliance each have their own banner"] = "Amélioration d'Esprit pour les joueurs de ta faction, ne se cumule pas avec Esprit divin. La Horde et l'Alliance ont chacune leur propre bannière",
  ["A Spinning Wheel, needed for many Tailoring recipes"] = "Un rouet, nécessaire pour de nombreuses recettes de Couture",
  ["{i:273099:inv_garrison_blueprints3:Blueprint: Spinning Wheel} Dropped by: {n:246017::Unstable Sentinel} in the City of Dalaran"] = "{i:273099:inv_garrison_blueprints3:Blueprint: Spinning Wheel} Butin de : {n:246017::Unstable Sentinel} dans la cité de Dalaran",
  ["A Loom, needed for many Tailoring recipes"] = "Un métier à tisser, nécessaire pour de nombreuses recettes de Couture",
  ["{i:273124:inv_garrison_blueprints3:Blueprint: Loom} Dropped by: {n:10436::Baroness Anastari} in Stratholme"] = "{i:273124:inv_garrison_blueprints3:Blueprint: Loom} Butin de : {n:10436::Baroness Anastari} à Stratholme",
  ["Intellect buff, doesn't stack with Arcane Intellect"] = "Amélioration d'Intelligence, ne se cumule pas avec Intelligence des Arcanes",
  ["A Greenhouse that grows herbs from seeds you plant"] = "Une serre qui fait pousser des herbes à partir des graines que tu plantes",
  ["{i:273106:inv_garrison_blueprints3:Blueprint: Greenhouse} Dropped by: {n:260325::Shadetooth} in Excavation Site: Wetlands"] = "{i:273106:inv_garrison_blueprints3:Blueprint: Greenhouse} Butin de : {n:260325::Shadetooth} dans Excavation Site: Wetlands",
  ["A Seed Hybridizer that multiplies seeds or combines them into rarer ones"] = "Un hybrideur de graines qui multiplie les graines ou les combine en graines plus rares",
  ["Melee Attack Power buff, doesn't stack with Blessing of Might"] = "Amélioration de puissance d'attaque en mêlée, ne se cumule pas avec Bénédiction de puissance",
  ["Spawns a common mining node over time, and gives the Lodestone buff too"] = "Fait apparaître un gisement commun au fil du temps, et donne aussi l'amélioration Lodestone",
  ["{i:273097:inv_garrison_blueprints3:Blueprint: Rock Garden} Dropped by: {n:260326::Relic Guardian} in Excavation Site: Wetlands"] = "{i:273097:inv_garrison_blueprints3:Blueprint: Rock Garden} Butin de : {n:260326::Relic Guardian} dans Excavation Site: Wetlands",
  ["A Molten Foundry, needed for Smelt Heavy Thorium"] = "Une fonderie en fusion, nécessaire pour Smelt Heavy Thorium",
  ["{i:273122:inv_garrison_blueprints3:Blueprint: Molten Foundry} Dropped by: {n:9156::Ambassador Flamelash} in Blackrock Depths"] = "{i:273122:inv_garrison_blueprints3:Blueprint: Molten Foundry} Butin de : {n:9156::Ambassador Flamelash} dans les profondeurs de Rochenoire",
  ["+2% crit chance, doesn't stack with Moonkin Aura"] = "+2 % de chances de coup critique, ne se cumule pas avec Aura de sélénien",
  ["A book anyone can read to learn Track Beasts"] = "Un livre que tout le monde peut lire pour apprendre Pistage des bêtes",
  ["{i:273098:inv_garrison_blueprints3:Blueprint: Field Guide} Dropped by: {n:3671::Lady Anacondra} in Wailing Caverns"] = "{i:273098:inv_garrison_blueprints3:Blueprint: Field Guide} Butin de : {n:3671::Lady Anacondra} dans les Cavernes des lamentations",
  ["A workbench with 1 trap"] = "Un établi avec 1 piège",
  ["{i:273109:inv_garrison_blueprints3:Blueprint: Trapper's Workbench} Dropped by: {n:10430::The Beast} in Upper Blackrock Spire and {n:3974::Houndmaster Loksey} in Scarlet Monastery"] = "{i:273109:inv_garrison_blueprints3:Blueprint: Trapper's Workbench} Butin de : {n:10430::The Beast} au pic Rochenoire supérieur et {n:3974::Houndmaster Loksey} au Monastère écarlate",
  ["Cooking has no tier 1 camp item, its first one is the campfire (see How to Make a Campfire above)."] = "La Cuisine n'a pas d'objet de camp de rang 1, son premier est le feu de camp (voir Comment faire un feu de camp ci-dessus).",
  ["Stamina food for everyone at the camp"] = "Nourriture d'Endurance pour tout le monde au camp",
  ["{i:273102:inv_garrison_blueprints3:Blueprint: Cookie's Feast} Dropped by: {n:645::Cookie} in The Deadmines"] = "{i:273102:inv_garrison_blueprints3:Blueprint: Cookie's Feast} Butin de : {n:645::Cookie} dans les Mortemines",
  ["An Iron Oven, needed for the most advanced Cooking recipes"] = "Un four en fer, nécessaire pour les recettes de Cuisine les plus avancées",
  ["{i:273115:inv_garrison_blueprints3:Blueprint: Iron Oven} Dropped by: {n:9736::Quartermaster Zigris} in Lower Blackrock Spire"] = "{i:273115:inv_garrison_blueprints3:Blueprint: Iron Oven} Butin de : {n:9736::Quartermaster Zigris} au pic Rochenoire inférieur",
  ["Stamina buff, doesn't stack with Power Word: Fortitude"] = "Amélioration d'Endurance, ne se cumule pas avec Mot de pouvoir : Robustesse",
  ["Healing potions and anti-venom"] = "Potions de soins et anti-venin",
  ["{i:273105:inv_garrison_blueprints3:Blueprint: Toxin Study} Dropped by: {n:4278::Commander Springvale} in Shadowfang Keep"] = "{i:273105:inv_garrison_blueprints3:Blueprint: Toxin Study} Butin de : {n:4278::Commander Springvale} au donjon d'Ombrecroc",
  ["Healing potions and poultices"] = "Potions de soins et cataplasmes",
  ["{i:273118:inv_garrison_blueprints3:Blueprint: Plague Doctor's Laboratory} Dropped by: {n:11261::Doctor Theolen Krastinov} in Scholomance"] = "{i:273118:inv_garrison_blueprints3:Blueprint: Plague Doctor's Laboratory} Butin de : {n:11261::Doctor Theolen Krastinov} à Scholomance",
  ["+8% all stats, doesn't stack with Blessing of Kings"] = "+8 % à toutes les caractéristiques, ne se cumule pas avec Bénédiction des rois",
  ["Uncommon fish for 1 hour and Fishing lures"] = "Poissons inhabituels pendant 1 heure et appâts de pêche",
  ["{i:273141:inv_garrison_blueprints3:Blueprint: Fishing Rack} Dropped by: {n:6243::Gelihast} in Blackfathom Deeps"] = "{i:273141:inv_garrison_blueprints3:Blueprint: Fishing Rack} Butin de : {n:6243::Gelihast} dans les profondeurs de Brassenoire",
  ["Rare fish for 1 hour and Fishing lures"] = "Poissons rares pendant 1 heure et appâts de pêche",
  ["{i:273119:inv_garrison_blueprints3:Blueprint: Fishing Hut} Dropped by: {n:5710::Jammal'an the Prophet} in the Sunken Temple"] = "{i:273119:inv_garrison_blueprints3:Blueprint: Fishing Hut} Butin de : {n:5710::Jammal'an the Prophet} dans le Temple englouti",
  ["Crafting Stations: Tanning Rack, Loom and More"] = "Postes d'artisanat : râtelier de tannage, métier à tisser et plus",
  ["A lot of recipes in WoW Forever need a crafting station nearby, like a Tanning Rack, a Spinning Wheel or a Loom. {b}I haven't found any of them out in the world{/b}, they only come from camps, so for a lot of higher level crafting you need a camp. The easiest way is a camp that already has the station, anyone at the fire can use it."] = "Beaucoup de recettes dans WoW Forever nécessitent un poste d'artisanat à proximité, comme un râtelier de tannage, un rouet ou un métier à tisser. {b}Je n'en ai trouvé aucun dans le monde{/b}, ils ne viennent que des camps, donc pour beaucoup de fabrications de plus haut niveau il te faut un camp. Le plus simple est un camp qui a déjà le poste, tout le monde près du feu peut l'utiliser.",
  ["To place one yourself:"] = "Pour en placer un toi-même :",
  ["Get your profession to the skill in the table below."] = "Monte ton métier jusqu'à la compétence indiquée dans le tableau ci-dessous.",
  ["Get the station's Blueprint and learn it. The table shows where it drops, if we know it."] = "Obtiens le plan (Blueprint) du poste et apprends-le. Le tableau indique où il tombe, si on le sait.",
  ["Craft the station, put down a campfire and use the station from your bags next to it."] = "Fabrique le poste, pose un feu de camp et utilise le poste depuis tes sacs à côté.",
  ["Station"] = "Poste",
  ["Profession"] = "Métier",
  ["Blueprint"] = "Plan",
  ["Dropped by: {n:250657::Rath'mael} in the Ruins of Lordaeron"] = "Butin de : {n:250657::Rath'mael} dans les ruines de Lordaeron",
  ["Dropped by: {n:10508::Ras Frostwhisper} in Scholomance"] = "Butin de : {n:10508::Ras Frostwhisper} à Scholomance",
  ["Dropped by: {n:8983::Golem Lord Argelmach} in Blackrock Depths"] = "Butin de : {n:8983::Golem Lord Argelmach} dans les profondeurs de Rochenoire",
  ["Dropped by: {n:261809::Nanaya} in Kalimdor"] = "Butin de : {n:261809::Nanaya} en Kalimdor",
  ["Dropped by: {n:11058::Ezra Grimm} in Stratholme"] = "Butin de : {n:11058::Ezra Grimm} à Stratholme",
  ["Dropped by: {n:3886::Razorclaw the Butcher} in Shadowfang Keep"] = "Butin de : {n:3886::Razorclaw the Butcher} au donjon d'Ombrecroc",
  ["Dropped by: {n:10432::Vectus} in Scholomance"] = "Butin de : {n:10432::Vectus} à Scholomance",
  ["Dropped by: {n:246017::Unstable Sentinel} in the City of Dalaran"] = "Butin de : {n:246017::Unstable Sentinel} dans la cité de Dalaran",
  ["Dropped by: {n:10436::Baroness Anastari} in Stratholme"] = "Butin de : {n:10436::Baroness Anastari} à Stratholme",
  ["Dropped by: {n:9156::Ambassador Flamelash} in Blackrock Depths"] = "Butin de : {n:9156::Ambassador Flamelash} dans les profondeurs de Rochenoire",
  ["Dropped by: {n:9736::Quartermaster Zigris} in Lower Blackrock Spire"] = "Butin de : {n:9736::Quartermaster Zigris} au pic Rochenoire inférieur",
  ["Merchant's Favor is a new currency in WoW Forever. You get it by filling Waylaid Crates with materials and handing them in at your faction's camp, Durotar Supply and Logistics for Horde and the Azeroth Commerce Authority for Alliance, and you spend it on the recipes, mount, pet, tabard and titles the camp vendors sell. Many recipes and the mount, pet and tabard also need reputation with the camp, which you get from Craftsman's Writs. This WoW Forever Merchant's Favor guide will show you where the camps are, how to earn Merchant's Favor and reputation, and every recipe the vendors sell."] = "Merchant's Favor est une nouvelle monnaie de WoW Forever. Tu l'obtiens en remplissant des Waylaid Crates de matériaux et en les rendant au camp de ta faction, Durotar Supply and Logistics pour la Horde et l'Azeroth Commerce Authority pour l'Alliance, et tu la dépenses pour les recettes, la monture, la mascotte, le tabard et les titres vendus par les marchands du camp. Beaucoup de recettes ainsi que la monture, la mascotte et le tabard demandent aussi de la réputation auprès du camp, que tu obtiens avec les Craftsman's Writs. Ce guide Merchant's Favor pour WoW Forever te montre où se trouvent les camps, comment gagner du Merchant's Favor et de la réputation, et toutes les recettes vendues par les marchands.",
  ["How It Works"] = "Fonctionnement",
  ["Waylaid Crates drop randomly in the open world and in dungeons, and you can also buy them on the Auction House. You fill a crate with the materials it asks for and hand it in at your camp. For that you get Merchant's Favor, the currency you buy the recipes with."] = "Les Waylaid Crates tombent au hasard dans le monde et en donjon, et tu peux aussi en acheter à l'hôtel des ventes. Tu remplis une caisse avec les matériaux qu'elle demande et tu la rends à ton camp. En échange, tu obtiens du Merchant's Favor, la monnaie avec laquelle tu achètes les recettes.",
  ["Many recipes also need reputation with the camp. You earn reputation by doing Craftsman's Writs. You get a writ, craft the item it asks for and bring it to the customer."] = "Beaucoup de recettes demandent aussi de la réputation auprès du camp. Tu gagnes de la réputation en faisant des Craftsman's Writs. Tu obtiens un ordre, tu fabriques l'objet demandé et tu l'apportes au client.",
  ["Where the Camps Are"] = "Où se trouvent les camps",
  ["The Horde camp belongs to Durotar Supply and Logistics, and the Alliance camp belongs to the Azeroth Commerce Authority. Each camp has a recipe vendor for every crafting profession and Cooking, and both camps sell the same recipes (see Recipes by Profession below)."] = "Le camp de la Horde appartient à Durotar Supply and Logistics, et celui de l'Alliance à l'Azeroth Commerce Authority. Chaque camp a un marchand de recettes pour chaque métier d'artisanat et pour la Cuisine, et les deux camps vendent les mêmes recettes (voir Recettes par métier ci-dessous).",
  ["Three Corners, Redridge Mountains"] = "Three Corners, les Carmines",
  ["How to Earn Merchant's Favor"] = "Comment gagner du Merchant's Favor",
  ["You earn Merchant's Favor by filling Waylaid Crates with materials and bringing them to your camp."] = "Tu gagnes du Merchant's Favor en remplissant des Waylaid Crates de matériaux et en les apportant à ton camp.",
  ["Merchant's Favor is per character, so every character has to earn its own."] = "Le Merchant's Favor est propre à chaque personnage, chaque personnage doit donc gagner le sien.",
  ["Filling a Waylaid Crate"] = "Remplir une Waylaid Crate",
  ["{b}Find a Waylaid Crate.{/b} They drop randomly in the open world and in dungeons, and {b}you can also buy them on the Auction House{/b}. Each one asks for one kind of material, for example {i:248684:inv_crate_07:Waylaid Crate: Apprentice Textiles}."] = "{b}Trouve une Waylaid Crate.{/b} Elles tombent au hasard dans le monde et en donjon, et {b}tu peux aussi en acheter à l'hôtel des ventes{/b}. Chacune demande un type de matériau, par exemple {i:248684:inv_crate_07:Waylaid Crate: Apprentice Textiles}.",
  ["Right-click it and fill it with one of the bundles it lists, for example 40 Linen Cloth or 20 Light Leather (see Waylaid Crates and Rewards below). You get a Sealed crate, and that one binds to you."] = "Fais un clic droit dessus et remplis-la avec l'un des lots qu'elle indique, par exemple 40 Étoffe de lin ou 20 Cuir léger (voir Waylaid Crates et récompenses ci-dessous). Tu obtiens une caisse scellée (Sealed), et celle-ci est liée à toi.",
  ["Bring the Sealed crate to {n:0::Dokimi} at the Horde camp or {n:0::Marcy Baker} at the Alliance camp. You get Merchant's Favor and some silver for it."] = "Apporte la caisse scellée à {n:0::Dokimi} au camp de la Horde ou à {n:0::Marcy Baker} au camp de l'Alliance. Tu obtiens du Merchant's Favor et quelques pièces d'argent en échange.",
  ["Waylaid Crates and Rewards"] = "Waylaid Crates et récompenses",
  ["When you fill a Waylaid Crate, it turns into a Sealed crate of the same rank and color. You hand that one in at your camp for the Merchant's Favor in the last column. There are also blue Sealed crates and a Sealed Elite Crate, but I don't know yet what they give."] = "Quand tu remplis une Waylaid Crate, elle se transforme en caisse scellée du même rang et de la même couleur. Tu la rends à ton camp contre le Merchant's Favor de la dernière colonne. Il existe aussi des caisses scellées bleues et une Sealed Elite Crate, mais je ne sais pas encore ce qu'elles donnent.",
  ["The Textiles, Ore, Herbs and Curiosities crates take raw materials, and the Fabrics, Ingots and Parts crates take crafted ones."] = "Les caisses Textiles, Ore, Herbs et Curiosities prennent des matériaux bruts, et les caisses Fabrics, Ingots et Parts prennent des matériaux fabriqués.",
  ["{b}A crate needs only one of the bundles in its row, not all of them.{/b}"] = "{b}Une caisse ne demande qu'un seul des lots de sa ligne, pas tous.{/b}",
  ["Apprentice"] = "Apprenti",
  ["Journeyman"] = "Compagnon",
  ["You need level 10 to open these."] = "Il te faut le niveau 10 pour les ouvrir.",
  ["You also get {m:2:s:} {m:50:c:} for a white crate and {m:5:s:} for a green one."] = "Tu obtiens aussi {m:2:s:} {m:50:c:} pour une caisse blanche et {m:5:s:} pour une verte.",
  ["Crate"] = "Caisse",
  ["Fill it with one of these"] = "Remplis-la avec l'un de ces lots",
  ["Reward"] = "Récompense",
  ["You also get {m:5:s:} for a white crate and {m:10:s:} for a green one."] = "Tu obtiens aussi {m:5:s:} pour une caisse blanche et {m:10:s:} pour une verte.",
  ["You need level 20 to open these."] = "Il te faut le niveau 20 pour les ouvrir.",
  ["You also get {m:7:s:} {m:50:c:} for a white crate and {m:15:s:} for a green one."] = "Tu obtiens aussi {m:7:s:} {m:50:c:} pour une caisse blanche et {m:15:s:} pour une verte.",
  ["You need level 35 to open these."] = "Il te faut le niveau 35 pour les ouvrir.",
  ["Not known yet"] = "Pas encore connu",
  ["How to Earn Durotar Supply and Azeroth Commerce Authority Reputation"] = "Comment gagner de la réputation auprès de Durotar Supply et de l'Azeroth Commerce Authority",
  ["{b}Handing in Sealed crates doesn't give reputation.{/b} Reputation with Durotar Supply and Logistics or the Azeroth Commerce Authority comes from Craftsman's Writs, crafting orders that you deliver to a customer somewhere in the world. After reaching Friendly, empty Waylaid Crates give reputation too (see Crate Returns after Friendly below)."] = "{b}Rendre des caisses scellées ne donne pas de réputation.{/b} La réputation auprès de Durotar Supply and Logistics ou de l'Azeroth Commerce Authority vient des Craftsman's Writs, des commandes d'artisanat que tu livres à un client quelque part dans le monde. Une fois Amical atteint, les Waylaid Crates vides donnent aussi de la réputation (voir Retours de caisses après Amical ci-dessous).",
  ["The first time you fill a crate or start a writ, you also get a {i:280180:inv_misc_note_03:Shipping Label}. It starts a quest to your camp, which gives 2,000 reputation and 50 Merchant's Favor."] = "La première fois que tu remplis une caisse ou commences un ordre, tu obtiens aussi un {i:280180:inv_misc_note_03:Shipping Label}. Il lance une quête vers ton camp, qui donne 2,000 points de réputation et 50 Merchant's Favor.",
  ["A Journeyman writ gives 75 reputation, an Expert writ 125 and an Artisan writ 200. {b}You can do each writ once a day{/b}, and as many different writs a day as you want."] = "Un ordre Compagnon donne 75 points de réputation, un ordre Expert 125 et un ordre Artisan 200. {b}Tu peux faire chaque ordre une fois par jour{/b}, et autant d'ordres différents par jour que tu veux.",
  ["{b}Get a Craftsman's Writ.{/b} In the open world and in dungeons they drop as a {i:262888:inv_misc_note_02:Sealed Journeyman's Writ}, {i:262889:inv_misc_note_02:Sealed Expert's Writ} or {i:262890:inv_misc_note_02:Sealed Artisan's Writ}, an envelope with a random writ of that rank inside. {b}You can also buy writs on the Auction House.{/b}"] = "{b}Obtiens un Craftsman's Writ.{/b} Dans le monde et en donjon, ils tombent sous forme de {i:262888:inv_misc_note_02:Sealed Journeyman's Writ}, {i:262889:inv_misc_note_02:Sealed Expert's Writ} ou {i:262890:inv_misc_note_02:Sealed Artisan's Writ}, une enveloppe contenant un ordre aléatoire de ce rang. {b}Tu peux aussi acheter des ordres à l'hôtel des ventes.{/b}",
  ["Right-click the writ to start its quest, for example {i:264047:inv_misc_note_01:Craftsman's Writ: Lesser Wizard's Robe}."] = "Fais un clic droit sur l'ordre pour lancer sa quête, par exemple {i:264047:inv_misc_note_01:Craftsman's Writ: Lesser Wizard's Robe}.",
  ["Make the item it asks for or buy it on the Auction House. You don't need the profession yourself."] = "Fabrique l'objet demandé ou achète-le à l'hôtel des ventes. Tu n'as pas besoin d'avoir le métier toi-même.",
  ["Bring the item to the customer, your map shows where. The customer takes the item and the writ, and you get the reputation and a Coin Pouch with some silver. Writs don't give Merchant's Favor. {b}On the beta, the customer had no question mark over their head.{/b} I think it was a bug, so if you don't see one, right-click them anyway and the window to hand in the writ opens."] = "Apporte l'objet au client, ta carte indique où. Le client prend l'objet et l'ordre, et tu obtiens la réputation et une Coin Pouch avec quelques pièces d'argent. Les ordres ne donnent pas de Merchant's Favor. {b}Sur la bêta, le client n'avait pas de point d'interrogation au-dessus de la tête.{/b} Je pense que c'était un bug, donc si tu n'en vois pas, fais quand même un clic droit dessus et la fenêtre pour rendre l'ordre s'ouvre.",
  ["Crate Returns after Friendly"] = "Retours de caisses après Amical",
  ["At Friendly, you unlock the Uncertified Scribe in your camp, {n:0:horde:Kurvelk Shadowhoof} at the Horde camp and {n:0:alliance:Dianne Softstep} at the Alliance camp. Both sell the same two items:"] = "À Amical, tu débloques l'Uncertified Scribe de ton camp, {n:0:horde:Kurvelk Shadowhoof} au camp de la Horde et {n:0:alliance:Dianne Softstep} au camp de l'Alliance. Les deux vendent les deux mêmes objets :",
  ["Reputation"] = "Réputation",
  ["What it does"] = "Effet",
  ["Friendly"] = "Amical",
  ["Turns an empty Waylaid Crate into 50 reputation, see the steps below."] = "Transforme une Waylaid Crate vide en 50 points de réputation, voir les étapes ci-dessous.",
  ["Honored"] = "Honoré",
  ["Turns a Craftsman's Writ into a random writ of the same rank."] = "Transforme un Craftsman's Writ en un ordre aléatoire du même rang.",
  ["{b}Buy a {i:262902:inv_10_inscription2_repcontracts_scroll_02_uprez_color5:Forged Delivery Receipt}{/b} from the Uncertified Scribe."] = "{b}Achète un {i:262902:inv_10_inscription2_repcontracts_scroll_02_uprez_color5:Forged Delivery Receipt}{/b} auprès de l'Uncertified Scribe.",
  ["Buy a Waylaid Crate on the Auction House. The receipt seems to work on any of them, so buy the cheapest one."] = "Achète une Waylaid Crate à l'hôtel des ventes. Le reçu semble fonctionner sur n'importe laquelle, achète donc la moins chère.",
  ["Use the receipt on the crate. You get a {i:262917:inv_crate_01:Notarized Shipping Container}."] = "Utilise le reçu sur la caisse. Tu obtiens un {i:262917:inv_crate_01:Notarized Shipping Container}.",
  ["Hand the container to the same NPC who takes your Sealed crates. You get the reputation and 1 silver."] = "Rends le conteneur au même PNJ que celui qui prend tes caisses scellées. Tu obtiens la réputation et 1 pièce d'argent.",
  ["Recipes by Profession"] = "Recettes par métier",
  ["Both camps, Durotar Supply and Logistics (Horde) and the Azeroth Commerce Authority (Alliance), sell the same recipes for Merchant's Favor. This is what each profession gets:"] = "Les deux camps, Durotar Supply and Logistics (Horde) et l'Azeroth Commerce Authority (Alliance), vendent les mêmes recettes contre du Merchant's Favor. Voici ce que chaque métier obtient :",
  ["{b}Alchemy:{/b} potions and elixirs."] = "{b}Alchimie :{/b} potions et élixirs.",
  ["{b}Blacksmithing:{/b} mail and plate sets for tanks, melee, healers and paladins, and three weapons."] = "{b}Forge :{/b} ensembles en mailles et en plaques pour tanks, combattants au corps à corps, soigneurs et paladins, et trois armes.",
  ["{b}Cooking:{/b} six smoothies that give Spirit."] = "{b}Cuisine :{/b} six smoothies qui donnent de l'Esprit.",
  ["{b}Enchanting:{/b} necklace, weapon and armor enchants, relics (idols, totems and librams) and caster weapons (staves, off-hands and wands)."] = "{b}Enchantement :{/b} enchantements de collier, d'arme et d'armure, reliques (idoles, totems et librams) et armes de lanceur de sorts (bâtons, objets de main gauche et baguettes).",
  ["{b}Engineering:{/b} bombs, thrown weapons, goggles, belts, trinkets and gadgets."] = "{b}Ingénierie :{/b} bombes, armes de jet, lunettes, ceintures, bijoux et gadgets.",
  ["{b}Leatherworking:{/b} leather and mail sets for every role, and two armor kits."] = "{b}Travail du cuir :{/b} ensembles en cuir et en mailles pour chaque rôle, et deux kits d'armure.",
  ["{b}Tailoring:{/b} cloth sets for every spell school and for healers, and two reagent bags."] = "{b}Couture :{/b} ensembles en tissu pour chaque école de magie et pour les soigneurs, et deux sacs de composants.",
  ["{b}The armor and weapons you craft from these recipes bind on pickup{/b}, so you can only make them for yourself."] = "{b}Les armures et armes fabriquées avec ces recettes sont liées quand ramassées{/b}, tu ne peux donc les fabriquer que pour toi.",
  ["{n:0:horde:Apothecary Durelle} at the Horde camp and {n:0:alliance:Nina Surefire} at the Alliance camp sell 28 Alchemy recipes."] = "{n:0:horde:Apothecary Durelle} au camp de la Horde et {n:0:alliance:Nina Surefire} au camp de l'Alliance vendent 28 recettes d'Alchimie.",
